    def ZA_mega_evolution_battle_mode5(
            self, usenum=1, movemode=0, Z_Gaurd=0, Cplus_attack=0,
            testmode1=0):
        """最終戦専用mode 5を、通常MEGA戦とは別の入口から開始する。

        開始フラグ:
          0 開始直後／再挑戦選択後のリセット
          1 FIELD・緑床・BATTLEの再開画面確認
          2 緑床移動または通常90度の初期移動と、移動後の視点探索待機
          3 FIELD_Wの上入力（未確認FIELDは左入力で再確認）
          4 継続移動・ターゲット探索・再ロック・攻撃

        通常画面はAを常用し、B/X/YはC+確認時だけ技として使う。
        専用4技UIではC+に依存せず、ZL保持後にA/X/B/Yを入力する。
        共通関数へ渡す固定値をここへ集約し、mode 0～4とは混在させない。
        TESTMODE1の開始動作はMEGA_MODE5_TESTMODE1_MANUAL_SETTINGSで検索。
        """
        return self.ZA_mega_evolution_battle(
            usenum=usenum,
            Xaction=1, Aaction=1, Yaction=1, Baction=1,
            mode=0,
            dir1=20, dir2=90, dir3=40, dir4=90,
            see_r=0.24,
            escape_flag=0,
            endpicture="POKEMON_ZA_TEXT_WHITE_COMMENT",
            last_battle_mode=1,
            # 赤い被弾表示ではZLを外し、Yを6回送って回避時間を延ばす。
            # 実行前に共通helperが緑床を再確認し、床処理を優先する。
            red_edge_y_renda_seconds=0.2,
            red_edge_y_repeat=6,
            dir5=90,
            field_resume_dir5_seconds=(3.0 if movemode == 1 else 4.0),
            attack_unavailable_y_dodge=0,
            movemode=movemode,
            Z_Gaurd=Z_Gaurd,
            Cplus_attack=Cplus_attack,
            testmode1=testmode1)

    def ZA_mega_mode5_transition(self, next_phase, reason):
        """mode 5の現在フェーズを更新し、変化した理由を1行で記録する。"""
        previous=getattr(self, "_za_mega_mode5_phase", "WAIT_RESUME")
        self._za_mega_mode5_phase=next_phase
        if previous != next_phase:
            print(
                "[MEGA_MODE5] {} -> {} :: {}".format(
                    previous, next_phase, reason))

    def ZA_mega_mode5_trace(self, detection, action, force=False):
        """mode 5の開始フラグ・検知・実行内容をCommandsログへ記録する。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return False
        start_flag=int(getattr(self, "_za_mega_mode5_start_flag", 0))
        phase=str(getattr(self, "_za_mega_mode5_phase", "WAIT_RESUME"))
        detection=str(detection or "NONE")
        action=str(action or "NONE")
        trace_key=(start_flag, phase, detection, action)
        now=time.monotonic()
        if (not force
                and trace_key == getattr(
                    self, "_za_mega_mode5_trace_key", None)
                and now < float(getattr(
                    self, "_za_mega_mode5_trace_retry_at", 0.0))):
            return False
        self._za_mega_mode5_trace_key=trace_key
        self._za_mega_mode5_trace_retry_at=now + 5.0
        self._za_mega_mode5_last_detection=detection
        self._za_mega_mode5_last_action=action
        testmode1=int(bool(getattr(
            self, "_za_mega_testmode1_enabled", False)))
        resume_hp=str(getattr(
            self, "_za_mega_testmode1_resume_hp", "LEGACY"))
        hp_color=str(getattr(
            self, "_za_mega_testmode1_hp_color", "NONE"))
        hp_ratio=float(getattr(
            self, "_za_mega_testmode1_hp_fill_ratio", 0.0))
        test_phase=str(getattr(
            self, "_za_mega_testmode1_phase", "DISABLED"))
        print(
            "[STATE_MAIN_FUNCTION][MEGA_MODE5] "
            "TESTMODE1={} RESUME_HP={} HP_COLOR={} HP_RATIO={:.3f} "
            "TEST_PHASE={} "
            "START_FLAG={} PHASE={} DETECT={} ACTION={}".format(
                testmode1, resume_hp, hp_color, hp_ratio, test_phase,
                start_flag, phase, detection, action))
        # mode 5戦闘関数は完了まで外側のZA_story_mainへ戻らないため、
        # 外側だけに任せるとCommandsの状態表示が戦闘中に更新されない。
        # 状態変化／5秒間隔のtrace時に、同じステータス欄を直接更新する。
        status_builder=getattr(self, "ZA_story_status_text", None)
        status_printer=getattr(self, "print_t", None)
        status_clear=getattr(self, "print_tb", None)
        if callable(status_builder) and callable(status_printer):
            try:
                self.out_str=status_builder()
                if callable(status_clear):
                    status_clear("d")
                status_printer(self.out_str)
            except Exception as error:
                print(
                    "[MEGA_MODE5_STATUS] display update failed: {}".format(
                        error))
        return True

    def ZA_mega_mode5_set_start_flag(
            self, start_flag, detection, action):
        """mode 5開始フラグを0～4へ制限して更新する。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return int(start_flag)
        next_flag=max(0, min(4, int(start_flag)))
        previous=int(getattr(self, "_za_mega_mode5_start_flag", 0))
        self._za_mega_mode5_start_flag=next_flag
        self.ZA_mega_mode5_trace(
            detection, action, force=(previous != next_flag))
        return next_flag

    def ZA_mega_mode5_attack_watchdog_reset(self):
        """次の戦闘／会話へ、前戦の無攻撃時間とフリーランを持ち越さない。"""
        self._za_mega_mode5_no_attack_since=0.0
        self._za_mega_mode5_battle_seen_at=0.0
        self._za_mega_mode5_attack_guard_retry_at=0.0
        self._za_mega_mode5_high_hp_retry_at=0.0
        self._za_mega_mode5_free_run_active=False
        self._za_mega_mode5_free_run_started_at=0.0
        self._za_mega_mode5_free_run_next_attack_at=0.0
        self._za_mega_mode5_free_run_move_angle=None
        self._za_mega_mode5_retry_field_since=0.0
        self._za_mega_mode5_last_warning_seen_at=0.0
        self._za_mega_mode5_warning_check_retry_at=0.0
        self._za_mega_mode5_visible_warning=""

    def ZA_mega_mode5_initial_bootstrap_fallback_ready(
            self, field_detected, escape_detected, choice_guard,
            event_attack_picture=""):
        """FIELD/ESCAPEが10周連続でない時だけ先行4技探索を許可。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or choice_guard or event_attack_picture
                or field_detected or escape_detected):
            self._za_mega_mode5_missing_field_escape_count=0
            return False
        count=min(10, int(getattr(
            self, "_za_mega_mode5_missing_field_escape_count", 0)) + 1)
        self._za_mega_mode5_missing_field_escape_count=count
        if count == 10:
            self.ZA_mega_mode5_trace(
                "FIELD_ESCAPE_MISSING_10",
                "allow ZL and four-move UI fallback", force=True)
        return count >= 10

    def ZA_mega_mode5_note_attack_input(self, button):
        """技UI確認後に送った攻撃入力だけで300秒を計り直す。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return
        self._za_mega_mode5_no_attack_since=time.monotonic()
        self._za_mega_mode5_last_attack_button=str(button)

    def ZA_mega_mode5_stale_retry_field(self, nofiled, field_detected,
                                        choice_guard):
        """選択肢後にnofiled=0でもHARD FIELD／Escape復帰を検出。"""
        eligible=bool(
            getattr(self, "_za_mega_last_battle_mode", False)
            and nofiled == 0 and field_detected and not choice_guard
            and int(getattr(self, "_za_mega_mode5_start_flag", 0)) == 1
            and getattr(self, "_za_mega_mode5_phase", "") == "RETRY_SELECTION"
            and not self.ZA_mega_mode5_event_attack_blocked())
        if not eligible:
            self._za_mega_mode5_retry_field_since=0.0
            return False
        now=time.monotonic()
        since=float(getattr(self, "_za_mega_mode5_retry_field_since", 0.0))
        if since <= 0.0:
            self._za_mega_mode5_retry_field_since=now
            return False
        if now - since < 2.0:
            return False
        self._za_mega_mode5_retry_field_since=0.0
        self.ZA_mega_mode5_trace(
            "FIELD_AFTER_RETRY_SELECTION",
            "repair nofiled state and resume battle phases", force=True)
        return True

    def ZA_mega_mode5_no_attack_watchdog(
            self, battle_visible, choice_guard, safe_battle_visible=False):
        """FIELD表示中に確認済み攻撃・予兆が300秒なければ救済へ。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return False
        # RPush入力からFIELD安定確認、敵側への短い復帰移動が終わるまでは
        # 300秒時計を開始せず、古い状態からのフリーラン移行も許可しない。
        if (getattr(self, "_za_mega_mode5_rpush_wait_field", False)
                or getattr(
                    self,
                    "_za_mega_mode5_rpush_post_field_move_pending",
                    False)):
            self.ZA_mega_mode5_attack_watchdog_reset()
            return False
        # TESTMODE1の青側／赤側／青再追跡は、強い光2セットまたは
        # 同じ側で180秒経過後の
        # 通常C+不在＋敵色判定だけで遷移する。300秒watchdogから
        # 赤側やフリーランへ先回りさせない。
        test_phase=str(getattr(
            self, "_za_mega_testmode1_phase", "DISABLED"))
        if (getattr(self, "_za_mega_testmode1_enabled", False)
                and not (
                    getattr(
                        self, "_za_mega_mode5_free_run_active", False)
                    and test_phase == "EXISTING_CHARGE")
                and test_phase not in {
                    "DISABLED", "LEGACY_COMBAT", "FREE_RUN"}):
            self.ZA_mega_mode5_attack_watchdog_reset()
            return False
        now=time.monotonic()
        if choice_guard:
            self.ZA_mega_mode5_attack_watchdog_reset()
            return False
        if not battle_visible:
            if (now - float(getattr(
                    self, "_za_mega_mode5_battle_seen_at", 0.0)) > 2.0):
                self.ZA_mega_mode5_attack_watchdog_reset()
            return False
        self._za_mega_mode5_battle_seen_at=now
        if now >= float(getattr(
                self, "_za_mega_mode5_attack_guard_retry_at", 0.0)):
            self._za_mega_mode5_attack_guard_retry_at=now + 1.0
            if self.ZA_mega_mode5_event_attack_blocked():
                self.ZA_mega_mode5_attack_watchdog_reset()
                return False
        if now >= float(getattr(
                self, "_za_mega_mode5_warning_check_retry_at", 0.0)):
            self._za_mega_mode5_warning_check_retry_at=now + 0.5
            warning=(
                "POKEMON_ZA_LAST_BATTLE_CHARGE"
                if self.image_check("POKEMON_ZA_LAST_BATTLE_CHARGE")
                else "POKEMON_ZA_LAST_BATTLE_STRONG_LIGHT"
                if self.image_check("POKEMON_ZA_LAST_BATTLE_STRONG_LIGHT")
                else "")
            if warning:
                self._za_mega_mode5_last_warning_seen_at=now
                if warning != getattr(
                        self, "_za_mega_mode5_visible_warning", ""):
                    self.ZA_mega_mode5_trace(
                        warning,
                        "restart 300s no-warning watch", force=True)
            self._za_mega_mode5_visible_warning=warning
        since=float(getattr(self, "_za_mega_mode5_no_attack_since", 0.0))
        if since <= 0.0:
            self._za_mega_mode5_no_attack_since=now
            return False
        if getattr(self, "_za_mega_mode5_free_run_active", False):
            return True
        last_warning=float(getattr(
            self, "_za_mega_mode5_last_warning_seen_at", 0.0))
        if (now - max(since, last_warning) < 300.0
                or now < float(getattr(
                self, "_za_mega_mode5_high_hp_retry_at", 0.0))):
            return False
        if self.ZA_mega_mode5_event_attack_blocked():
            self.ZA_mega_mode5_attack_watchdog_reset()
            return False
        # 300秒境界で予兆が再表示された場合も発動しない。
        if (self.image_check("POKEMON_ZA_LAST_BATTLE_CHARGE")
                or self.image_check(
                    "POKEMON_ZA_LAST_BATTLE_STRONG_LIGHT")):
            self._za_mega_mode5_last_warning_seen_at=time.monotonic()
            return False
        # 青側障害物中はフリーランより赤側移行を優先する。
        # 技UI未確認のAはnote_attack_input()を呼ばないため、この300秒の
        # 「確認済み攻撃なし」に含まれる。赤側へ移った後で時計を再開始し、
        # そこでも300秒進展がない場合にだけフリーランを再検討する。
        test_phase=str(getattr(
            self, "_za_mega_testmode1_phase", "DISABLED"))
        if (getattr(self, "_za_mega_testmode1_enabled", False)
                and not getattr(
                    self, "_za_mega_testmode1_legacy_until_reset", False)
                and test_phase == "COVER_ATTACK"):
            self._za_mega_testmode1_phase="MOVE_TO_RED_COVER"
            self._za_mega_testmode1_red_only_since=0.0
            self._za_mega_testmode1_red_only_last_seen=0.0
            self._za_mega_testmode1_red_only_confirmations=0
            self._za_mega_testmode1_blue_last_seen_at=0.0
            self._za_mega_testmode1_enemy_check_retry_at=0.0
            self._za_mega_testmode1_warning_cycle_active=False
            self._za_mega_testmode1_warning_cycle_saw_strong=False
            self._za_mega_testmode1_warning_interval_active=False
            self._za_mega_testmode1_warning_interval_blue_seen=False
            self._za_mega_testmode1_warning_red_pending=False
            self._za_mega_testmode1_red_cover_move_not_before=0.0
            self.ZA_mega_mode5_trace(
                "TESTMODE1_NO_ATTACK_300S_RED_PRIORITY",
                "no confirmed attack/warning for 300s; move to red cover "
                "before free run",
                force=True)
            self.ZA_mega_mode5_attack_watchdog_reset()
            return False
        # 以前のHP_RATIOは選択肢リセット後も残り得る。発動時に2枚撮り直す。
        high_hp=True
        samples=[]
        for attempt in range(2):
            self.ZA_mega_mode5_hp_resume_mode()
            ratio=float(getattr(
                self, "_za_mega_testmode1_hp_fill_ratio", 0.0))
            color=getattr(self, "_za_mega_testmode1_hp_color", "NONE")
            samples.append((color, ratio))
            if color != "GREEN" or not 0.80 < ratio <= 1.05:
                high_hp=False
                if color != "NONE" or ratio > 0.0:
                    break
            if attempt == 0:
                self.wait(0.1)
        # 選択位置からHP引継ぎ／全快を推定しない。HPが読めない場合は
        # FIELDがあり、かつ予兆2種も300秒なかった時だけ補助判定する。
        hp_unknown=bool(
            len(samples) == 2
            and all(color == "NONE" and ratio <= 0.0
                    for color, ratio in samples))
        warning_absent=bool(
            not self.image_check("POKEMON_ZA_LAST_BATTLE_CHARGE")
            and not self.image_check(
                "POKEMON_ZA_LAST_BATTLE_STRONG_LIGHT"))
        if not warning_absent:
            self._za_mega_mode5_last_warning_seen_at=time.monotonic()
            return False
        unknown_safe=bool(hp_unknown and safe_battle_visible)
        if not high_hp and not unknown_safe:
            self._za_mega_mode5_high_hp_retry_at=now + 5.0
            self.ZA_mega_mode5_trace(
                "NO_ATTACK_300S_HP_NOT_HIGH",
                "fresh HP={}; safe FIELD={}; keep normal mode5".format(
                    samples, bool(safe_battle_visible)),
                force=True)
            return False
        self._za_mega_mode5_free_run_active=True
        self._za_mega_mode5_free_run_started_at=time.monotonic()
        self._za_mega_mode5_free_run_next_attack_at=0.0
        self._za_mega_mode5_initial_phase_active=False
        self._za_mega_mode5_green_priority_checks_remaining=0
        self._za_mega_mode5_view_search_block_until=0.0
        self._za_mega_mode5_post_move_wait_until=0.0
        self._za_mega_field_dir5_until=0.0
        # TESTMODE1の障害物待機が視点と左移動を止めないよう、次のSELECTまで解除。
        self._za_mega_testmode1_legacy_until_reset=True
        self._za_mega_testmode1_phase="LEGACY_COMBAT"
        self.ZA_mega_mode5_transition(
            "FREE_RUN", "300s without confirmed attack/charge/light; {}".format(
                "fresh HP > 80%" if high_hp
                else "HP unavailable; safe FIELD"))
        self.ZA_mega_mode5_trace(
            "NO_ATTACK_300S_HIGH_HP" if high_hp
            else "NO_ATTACK_300S_HP_UNKNOWN_NO_WARNING",
            "free run; fresh HP={}".format(samples), force=True)
        return True

    def ZA_mega_mode5_event_attack_blocked(self):
        """最終戦の技入力を止める会話・選択・終了画面を返す。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return ""
        common_blocker=next((
            picture for picture in (
                "POKEMON_ZA_TEXT_WHITE_COMMENT",
                "POKEMON_ZA_TEXT_GREEN_COMMENT",
                "POKEMON_ZA_X_MENU_OPEN",
                "POKEMON_ZA_REWORD",
                "POKEMON_ZA_REWORD_END",
                "POKEMON_ZA_REWORD_LOSE",
            ) if self.image_check(picture)), "")
        if common_blocker:
            return common_blocker
        defeat_blocker=(
            "POKEMON_ZA_TEXT_BLACK_COMMENT"
            if self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")
            else next((
                picture for picture in (
                    "POKEMON_ZA_3_SELECT_TUTORIAL",
                    "POKEMON_ZA_3_SELECT",
                    "POKEMON_ZA_4_SELECT",
                ) if self.ZA_mega_mode5_defeat_select_confirmed(
                    picture)), ""))
        if defeat_blocker:
            # 通常の黒Commentは黒背景でなくても入力を止めて送り処理へ渡す。
            # 番号付きSELECTはdefeat_select_confirmed()で黒背景と
            # FIELD／Lv不在を0.05秒前後で確認済み。
            return defeat_blocker
        return ""

    def ZA_mega_mode5_event_attack_picture(self, check_blockers=True):
        """C+が出ない最終戦の4技表示をmode 5だけで確認する。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return ""
        # 固有4技を1つ以上入力した後は、同じUIが演出中に残っていても
        # 再攻撃しない。次のHARD FIELD／Escapeで再戦処理へ入るまで、
        # FIELD待ち専用状態を維持する。
        if getattr(
                self, "_za_mega_mode5_event_attack_wait_field", False):
            return ""
        if (getattr(
                self, "_za_mega_mode5_defeat_sequence_active", False)
                and getattr(
                    self, "_za_mega_mode5_defeat_candidate_picture", "")):
            # 直前の固定4技中に二重確認した敗戦候補を、残存4技UIで
            # 上書きしない。次周回は敗戦処理へ確実に引き渡す。
            return ""
        picture="POKEMON_ZA_LAST_BATTLE_MOVE_UI"
        if not self.image_check(picture):
            return ""
        if check_blockers and self.ZA_mega_mode5_event_attack_blocked():
            return ""
        return picture

    def ZA_mega_mode5_last_name_no_hard_timeout(
            self, eligible, hard_field_detected, blocked=False,
            field_w_detected=False, field_back_w_detected=False,
            escape_detected=False):
        """FIELD系／Escapeなしで最終戦名が5秒連続した状態を返す。"""
        since_attr="_za_mega_mode5_last_name_no_hard_since"
        seen_attr="_za_mega_mode5_last_name_last_seen_at"

        def reset_timer():
            setattr(self, since_attr, 0.0)
            setattr(self, seen_attr, 0.0)

        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or not eligible or hard_field_detected or field_w_detected
                or field_back_w_detected or escape_detected or blocked):
            reset_timer()
            return False

        now=time.monotonic()
        name_visible=self.image_check("POKEMON_ZA_LAST_BATTLE_NAME")
        if not name_visible:
            reset_timer()
            return False
        setattr(self, seen_attr, now)
        started_at=float(getattr(self, since_attr, 0.0))
        if started_at <= 0.0:
            started_at=now
            setattr(self, since_attr, started_at)
            print(
                "[MEGA_MODE5_LAST_NAME_LOCKON] boss name visible; "
                "wait 5.0s with FIELD/Escape absent")
            return False
        settings_getter=getattr(
            self, "ZA_mega_mode5_testmode1_settings", None)
        settings=settings_getter() if callable(settings_getter) else {}
        stable_seconds=max(5.0, float(settings.get(
            "LAST_BATTLE_NAME_LOCKON_SECONDS", 5.0)))
        return bool(now - started_at >= stable_seconds)

    def ZA_mega_mode5_event_lockon_bootstrap(
            self, nofiled, resume_screen_detected=False,
            field_screen_detected=False, field_w_detected=False,
            choice_input_guard=False,
            allow_missing_field_fallback=False,
            field_back_w_detected=False, escape_detected=False,
            require_name_lockon=False):
        """固有4技を優先し、許可済みの名称5秒判定後だけZLする。"""
        if getattr(
                self, "_za_mega_mode5_event_attack_wait_field", False):
            self._za_mega_mode5_last_name_no_hard_since=0.0
            self._za_mega_mode5_last_name_last_seen_at=0.0
            return ""
        start_flag=int(getattr(
            self, "_za_mega_mode5_start_flag", 0))
        retry_selection_wait=bool(
            start_flag <= 1
            and getattr(self, "_za_mega_mode5_phase", "")
            == "RETRY_SELECTION"
            and getattr(self, "_za_mega_testmode1_phase", "")
            == "WAIT_RESUME")
        initial_wait_state=bool(
            start_flag <= 1
            and (int(nofiled) == 1 or retry_selection_wait))
        # 初回／再戦のFIELD待機では、別の単調時計で3分経過するまで
        # 名前画像そのものを確認しない。allow_missing_field_fallbackは
        # その3分経過を呼出側が確認済みであることを表す。
        timed_field_wait=bool(allow_missing_field_fallback)
        initial_wait=bool(
            timed_field_wait
            and (initial_wait_state or start_flag == 3
                 or getattr(
                     self, "_za_mega_mode5_rpush_wait_field", False)))
        active_wait=bool(
            int(nofiled) == 0 and start_flag == 4
            and getattr(self, "_za_mega_mode5_battle_active", False))
        blocked_picture=self.ZA_mega_mode5_event_attack_blocked()
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or not (initial_wait or active_wait)):
            self.ZA_mega_mode5_last_name_no_hard_timeout(
                False, False, blocked=True)
            return ""
        if choice_input_guard or blocked_picture:
            self.ZA_mega_mode5_last_name_no_hard_timeout(
                False, False, blocked=True)
            return ""

        picture=("" if require_name_lockon else
                 self.ZA_mega_mode5_event_attack_picture(
                     check_blockers=False))
        if picture:
            self.ZA_mega_mode5_last_name_no_hard_timeout(
                False, True)
            self._za_mega_mode5_event_name_ui_missing_latched=False
            return picture
        # 固有4技が見えない場合だけ、FIELD系とEscapeを確認する。
        # FIELD_W/BACK_Wが同時一致してもHARD FIELDを省略しない。
        hard_field_detected=self.image_check(
            "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")
        field_w_detected=bool(
            field_w_detected or self.image_check("POKEMON_ZA_FIELD_W"))
        field_back_w_detected=bool(
            field_back_w_detected
            or self.image_check("POKEMON_ZA_FIELD_BACK_W"))
        escape_detected=bool(
            escape_detected or self.image_check("POKEMON_ZA_ESCAPE"))
        # ZL後に固有4技UIが出なかった同じ名称表示では、5秒判定を
        # 再開してZLを無期限に送り直さない。名称が一度消えた次の
        # エピソードだけ、改めて5秒確認を許可する。
        if getattr(
                self, "_za_mega_mode5_event_name_ui_missing_latched", False):
            if self.ZA_mega_mode5_event_name_ui_missing_update():
                self.ZA_mega_mode5_last_name_no_hard_timeout(
                    False, False, blocked=True)
                return ""
        name_timeout_due=self.ZA_mega_mode5_last_name_no_hard_timeout(
            initial_wait or active_wait,
            hard_field_detected,
            blocked=False,
            field_w_detected=field_w_detected,
            field_back_w_detected=field_back_w_detected,
            escape_detected=escape_detected)
        now=time.monotonic()
        name_timeout_tracking=bool(
            (initial_wait or active_wait)
            and not (hard_field_detected or field_w_detected
                     or field_back_w_detected or escape_detected)
            and float(getattr(
                self, "_za_mega_mode5_last_name_no_hard_since", 0.0))
            > 0.0)
        if not name_timeout_due:
            if name_timeout_tracking:
                return "WAIT_LAST_BATTLE_NAME_5S"
            return ""

        retry_at=float(getattr(
            self, "_za_mega_mode5_event_lockon_retry_at", 0.0))
        if now < retry_at:
            return "WAIT_EVENT_ATTACK_UI"
        self._za_mega_mode5_event_lockon_retry_at=now + 1.0
        self._za_mega_mode5_event_attack_pending_from_name_lockon=False

        # 名称5秒成立直後に遅れて実SELECT／黒Commentが出た場合は、
        # ZLより敗戦処理を優先する。
        defeat_candidate=self.ZA_mega_mode5_defeat_candidate_picture()
        if defeat_candidate:
            self._za_mega_mode5_event_attack_pending_from_name_lockon=False
            self._za_mega_mode5_defeat_candidate_picture=defeat_candidate
            self.ZA_ZL_ACTION("END")
            return "DEFEAT_EVENT_LOCKON_ABORTED"

        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_SEE(action="END")
        # Python側のZL_stateとゲーム側のロック状態がずれる場合もあるため、
        # この開始待ちだけはいったん解放してから確実に保持し直す。
        self.ZA_ZL_ACTION("END")
        self.wait(0.1)
        self.ZA_ZL_ACTION("")
        self.wait(0.15)
        # 高負荷時の4技描画待ちを含め、ZLから合計0.30秒後に再照合する。
        self.wait(0.15)
        defeat_candidate=self.ZA_mega_mode5_defeat_candidate_picture()
        if defeat_candidate:
            self._za_mega_mode5_event_attack_pending_from_name_lockon=False
            self._za_mega_mode5_defeat_candidate_picture=defeat_candidate
            self.ZA_ZL_ACTION("END")
            self.ZA_mega_mode5_trace(
                "DEFEAT_EVENT_LOCKON_ABORTED",
                "defeat SELECT/comment appeared after ZL; cancel event attack",
                force=True)
            return "DEFEAT_EVENT_LOCKON_ABORTED"
        picture=self.ZA_mega_mode5_event_attack_picture()
        if picture:
            now=time.monotonic()
            self._za_mega_mode5_event_attack_pending_from_name_lockon=True
            self._za_mega_mode5_lockon_confirmed_until=now + 0.8
            self._za_mega_mode5_visual_lockon_until=now + 0.8
            self._za_mega_mode5_event_name_ui_missing_latched=False
            self.ZA_mega_mode5_trace(
                picture,
                "ZL lockon first; recheck LAST48 move UI", force=True)
            return picture
        post_zl_blocker=self.ZA_mega_mode5_event_attack_blocked()
        post_zl_recovery_picture=next((
            candidate for candidate in (
                "POKEMON_ZA_FIELD_W",
                "POKEMON_ZA_FIELD_BACK_W",
                "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK",
                "POKEMON_ZA_ESCAPE",
                "POKEMON_ZA_R_push",
            ) if self.image_check(candidate)), "")
        if post_zl_blocker or post_zl_recovery_picture:
            self._za_mega_mode5_event_attack_pending_from_name_lockon=False
            self.ZA_ZL_ACTION("END")
            self.ZA_mega_mode5_trace(
                "EVENT_ATTACK_BLOCKED_AFTER_ZL",
                "{} appeared after ZL; hand off to screen processing".format(
                    post_zl_blocker or post_zl_recovery_picture),
                force=True)
            return "EVENT_ATTACK_BLOCKED_AFTER_ZL"
        # 固有4技UIを確認できない限り攻撃しない。通常Aの盲入力も行わず、
        # 同じ名称表示で再試行せず、直前の青／赤／フリーランへ戻す。
        self.ZA_mega_mode5_trace(
            "EVENT_ATTACK_UI_MISSING",
            "ZL lockon first; recheck LAST48 move UI", force=True)
        self._za_mega_mode5_event_attack_pending_from_name_lockon=False
        self._za_mega_mode5_event_name_ui_missing_latched=True
        self._za_mega_mode5_last_name_no_hard_since=0.0
        self._za_mega_mode5_last_name_last_seen_at=0.0
        return "EVENT_ATTACK_UI_MISSING_AFTER_ZL"

    def ZA_mega_mode5_event_attack_axby(
            self, detected_picture="",
            dir1=0, dir2=0, dir3=0, dir4=0, see_r=0):
        """最終戦4技UIではC+に依存せずZL保持後A/X/B/Yを送る。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or getattr(
                    self, "_za_mega_mode5_event_attack_wait_field", False)
                or int(getattr(
                    self, "_za_mega_mode5_start_flag", 0)) != 4
                or not getattr(
                    self, "_za_mega_mode5_battle_active", False)):
            return False
        detected_picture=(
            detected_picture or self.ZA_mega_mode5_event_attack_picture())
        if not detected_picture:
            return False

        # この画面にはC+表示がない。PLUS判定／入力を通さず、右視点を
        # 止めてZLを保持してから4技を直接入力する。左移動は止めない。
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_SEE(action="END")
        # 既に保持済みならZA_ZL_ACTION("")は一度ZLを解放してしまい、
        # 直前に表示された4技UIが消えるため再入力しない。
        if getattr(self, "ZL_state", 0) != 1:
            self.ZA_ZL_ACTION("")
        self.wait(0.1)
        self.ZA_mega_mode5_trace(
            detected_picture,
            "ZL lockon + A/X/B/Y (C+ unavailable)", force=True)

        pending_from_name_lockon=bool(getattr(
            self,
            "_za_mega_mode5_event_attack_pending_from_name_lockon",
            False))
        pressed=[]
        defeat_interrupted=False
        for button in (Button.A, Button.X, Button.B, Button.Y):
            self.checkIfAlive()
            if not self.ZA_mega_mode5_event_attack_picture(
                    check_blockers=True):
                defeat_candidate=self.ZA_mega_mode5_defeat_candidate_picture()
                if defeat_candidate:
                    defeat_interrupted=True
                    self._za_mega_mode5_event_attack_pending_from_name_lockon=(
                        False)
                    self._za_mega_mode5_defeat_candidate_picture=(
                        defeat_candidate)
                    self.ZA_mega_mode5_trace(
                        "DEFEAT_EVENT_ATTACK_ABORTED",
                        "{} appeared before {}; stop fixed-four input".format(
                            defeat_candidate, button.name),
                        force=True)
                print(
                    "[MEGA_MODE5_EVENT_ATTACK] move UI cleared after {} -> "
                    "stop remaining attack input".format(
                        "/".join(pressed) if pressed else "ZL"))
                break
            self.pressRep(
                button, repeat=1, duration=0.04,
                wait=0.1, interval=0.1)
            note_attack=getattr(
                self, "ZA_mega_mode5_note_attack_input", None)
            if callable(note_attack):
                note_attack(button.name)
            pressed.append(button.name)
            # 最初の固有技を送れた後は、以降のUI消失を従来どおり
            # 「入力済み」としてFIELD待機へ渡す。
            self._za_mega_mode5_event_attack_pending_from_name_lockon=False
        if not pressed and not defeat_interrupted:
            # ZL直後には4技UIを確認できても、最初のA直前に消えることが
            # ある。このゼロ入力だけを通常戦闘へ流すと、同じ名称の
            # 5秒確認→ZLを無期限にやり直すため、UIが実際に消えた場合は
            # 「ZL後に4技UIなし」と同じ直近戦闘復帰へ接続する。
            blocker=self.ZA_mega_mode5_event_attack_blocked()
            recovery_picture=next((
                picture for picture in (
                    "POKEMON_ZA_FIELD_W",
                    "POKEMON_ZA_FIELD_BACK_W",
                    "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK",
                    "POKEMON_ZA_ESCAPE",
                    "POKEMON_ZA_R_push",
                ) if self.image_check(picture)), "")
            move_ui_still_visible=bool(
                self.ZA_mega_mode5_event_attack_picture(
                    check_blockers=False))
            if (pending_from_name_lockon
                    and not blocker and not recovery_picture
                    and not move_ui_still_visible):
                self._za_mega_mode5_event_attack_pending_from_name_lockon=(
                    False)
                self._za_mega_mode5_event_name_ui_missing_latched=True
                self._za_mega_mode5_last_name_no_hard_since=0.0
                self._za_mega_mode5_last_name_last_seen_at=0.0
                self.ZA_mega_mode5_trace(
                    "EVENT_ATTACK_UI_MISSING_BEFORE_FIRST_MOVE",
                    "move UI vanished before A; resume recent combat",
                    force=True)
                self.ZA_mega_mode5_resume_recent_combat_after_event_ui_missing(
                    dir1,dir2,dir3,dir4,see_r)
            else:
                if blocker or recovery_picture:
                    self._za_mega_mode5_event_attack_pending_from_name_lockon=(
                        False)
                    self.ZA_ZL_ACTION("END")
                self.ZA_mega_mode5_trace(
                    "EVENT_ATTACK_ZERO_INPUT_DEFERRED",
                    "{}; defer fixed-four input to next loop".format(
                        blocker or recovery_picture or
                        ("move UI became visible again"
                         if move_ui_still_visible else
                         "move UI vanished outside name lockon")),
                    force=True)
            # どのゼロ入力理由でもこの周回を消費し、通常攻撃、強い光、
            # TESTMODE1へフォールスルーさせない。
            return True
        if pressed and not defeat_interrupted:
            defeat_candidate=self.ZA_mega_mode5_defeat_candidate_picture()
            if defeat_candidate:
                defeat_interrupted=True
                self._za_mega_mode5_defeat_candidate_picture=(
                    defeat_candidate)
                self.ZA_mega_mode5_trace(
                    "DEFEAT_EVENT_ATTACK_ABORTED",
                    "{} appeared after fixed-four input; keep defeat state".format(
                        defeat_candidate),
                    force=True)
        if defeat_interrupted:
            # 実SELECT／黒Commentを確認した周回ではZLを解放して戦闘を
            # 停止する。戻り値Trueで呼出側を即continueさせ、同じ周回の
            # 通常攻撃・強い光・TESTMODE1へ流さない。
            self._za_mega_mode5_event_attack_pending_from_name_lockon=False
            self.ZA_ZL_ACTION("END")
            self._za_mega_mode5_battle_active=False
            self.ZA_mega_mode5_transition(
                "RETRY_SELECTION",
                "defeat candidate interrupted fixed-four input")
            self.ZA_mega_mode5_set_start_flag(
                0, "DEFEAT_EVENT_ATTACK_ABORTED",
                "stop battle input and hand off to defeat processing")
        if pressed and not defeat_interrupted:
            now=time.monotonic()
            self._za_mega_mode5_lockon_confirmed_until=now + 0.8
            self._za_mega_mode5_visual_lockon_until=now + 0.8
            self._za_mega_mode5_event_lockon_retry_at=now + 0.5
            self.ZA_mega_mode5_event_attack_enter_field_wait(
                detected_picture, pressed)
        # 戻り値は「この周回の固有4技処理を消費したか」。実敗戦候補で
        # 中断した場合もTrueとして、同じ周回の通常攻撃へ流さない。
        return bool(pressed) or defeat_interrupted

    def ZA_mega_mode5_event_attack_enter_field_wait(
            self, detected_picture="", pressed_buttons=()):
        """固有4技入力後を敗戦相当のFIELD再戦待ちへ切り替える。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or not pressed_buttons):
            return False

        # 黒背景5秒確認済みを意味する敗戦ラッチ自体は捏造しない。
        # 再戦待ちに必要な状態だけを敗戦時と同じ値へそろえる。
        self._za_mega_mode5_defeat_sequence_active=False
        self._za_mega_mode5_defeat_background_since=0.0
        self._za_mega_mode5_defeat_prompt_logged=False
        self._za_mega_mode5_defeat_prompt_a_retry_at=0.0
        self._za_mega_mode5_defeat_candidate_picture=""
        self._za_mega_mode5_battle_active=False
        self._za_mega_mode5_post_move_wait_until=0.0
        self._za_mega_mode5_lockon_confirmed_until=0.0
        self._za_mega_mode5_visual_lockon_until=0.0
        self._za_mega_mode5_event_lockon_retry_at=0.0
        self._za_mega_mode5_event_attack_pending_from_name_lockon=False
        self._za_mega_mode5_event_name_ui_missing_latched=False
        self._za_mega_mode5_event_name_ui_missing_clear_since=0.0
        self._za_mega_colored_enemy_track_position=None
        self._za_mega_colored_enemy_track_seen_at=0.0
        self._za_mega_colored_enemy_candidate_position=None
        self._za_mega_colored_enemy_candidate_color=None
        self._za_mega_colored_enemy_candidate_pixels=0.0
        self._za_mega_colored_enemy_candidate_seen_at=0.0
        self._za_mega_colored_enemy_candidate_hits=0
        self._za_mega_field_w_up_attempts=0
        self._za_mega_field_w_up_retry_at=0.0
        self._za_mega_field_w_up_latched=False
        self._za_mega_mode5_field_left_attempts=0
        self._za_mega_mode5_field_left_retry_at=0.0
        self._za_mega_rclick_dir3_until=0.0
        self._za_mega_field_dir5_until=0.0
        self._za_mega_field_dir4_until=0.0

        post_roll_reset=getattr(
            self, "ZA_mega_field_post_attack_roll_reset", None)
        if callable(post_roll_reset):
            post_roll_reset()
        self.ZA_mega_mode5_transition(
            "RETRY_SELECTION",
            "fixed four-move attack complete; wait for FIELD retry")
        reset_for_selection=getattr(
            self, "ZA_mega_mode5_testmode1_reset_for_selection", None)
        if callable(reset_for_selection):
            reset_for_selection("EVENT_FIXED4_ATTACK_COMPLETE")
        else:
            watchdog_reset=getattr(
                self, "ZA_mega_mode5_attack_watchdog_reset", None)
            if callable(watchdog_reset):
                watchdog_reset()
            field_wait_reset=getattr(
                self, "ZA_mega_mode5_field_wait_reset", None)
            if callable(field_wait_reset):
                field_wait_reset()

        # selection reset内では通常の再戦選択としてラッチを解除するため、
        # 固有4技完了の専用待ちはreset後に立てる。
        self._za_mega_mode5_event_attack_wait_field=True
        self.ZA_ZL_ACTION("END")
        self.ZA_mega_mode5_set_start_flag(
            0,
            "EVENT_ATTACK_COMPLETE",
            "{} input complete; enter defeat-equivalent FIELD wait".format(
                "/".join(str(button) for button in pressed_buttons)))
        self.ZA_mega_mode5_trace(
            "EVENT_ATTACK_WAIT_FIELD",
            "ignore remaining move UI; wait for FIELD retry",
            force=True)
        return True

    def ZA_mega_target_marker_direction(self, include_upper=False):
        # 画面下中央をプレイヤー位置とし、検出したマーカー中心までの
        # ベクトルをそのまま左スティック角度へ変換する。
        self._za_mega_target_marker_position=None
        self._za_mega_target_from_color=False
        self._za_mega_last_target_frame=None
        targets = getattr(self, "IMAGE_DETECTION_TARGETS", {})
        marker_variants = [
            (target, targets[target][0])
            for target in (
                "POKEMON_ZA_TARGET_LEFT_LOW",
                "POKEMON_ZA_TARGET_RIGHT_LOW")
            if targets.get(target)
        ]
        if marker_variants:
            camera = getattr(self, "camera", None)
            if camera is None:
                return 0
            if hasattr(camera, "readFreshFrame"):
                frame = camera.readFreshFrame(timeout=0.75)
            else:
                frame = camera.readFrame() if hasattr(
                    camera, "readFrame") else None
            if frame is None:
                return 0
            self._za_mega_last_target_frame=frame
            detection_details = []
            for target, variant in marker_variants:
                template_path = str(variant.get("template_path", ""))
                normalized_path = template_path.replace("\\", "/")
                if (not os.path.isabs(template_path)
                        and normalized_path.startswith("Template/")):
                    template_path = self.get_filespec(
                        normalized_path[len("Template/"):], mode="t")
                template = cv2.imread(template_path, cv2.IMREAD_COLOR)
                if template is None:
                    continue
                source_match = frame
                template_match = template
                if variant.get("use_gray", False):
                    source_match = cv2.cvtColor(
                        source_match, cv2.COLOR_BGR2GRAY)
                    template_match = cv2.cvtColor(
                        template_match, cv2.COLOR_BGR2GRAY)
                if (source_match.shape[0] < template_match.shape[0]
                        or source_match.shape[1] < template_match.shape[1]):
                    continue
                result = cv2.matchTemplate(
                    source_match,
                    template_match,
                    cv2.TM_CCOEFF_NORMED)
                # テンプレート矩形が左上マップへ少しでも重なる候補を除外する。
                result = result.copy()
                result_height, result_width = result.shape[:2]
                template_height, template_width = template_match.shape[:2]
                exclusion_right = min(result_width, 210)
                exclusion_bottom = min(result_height, 210)
                if exclusion_right > 0 and exclusion_bottom > 0:
                    result[0:exclusion_bottom, 0:exclusion_right] = -2.0
                if (getattr(self, "_za_mega_last_battle_mode", False)
                        and getattr(self, "_za_mega_movemode", 0) == 1):
                    # mode 5の左下には手持ちポケモンの固定UIがあり、
                    # 青緑の細い輪郭がターゲットマーカーと誤一致する。
                    # 1280x720基準のx<430・y>=500だけを候補から外し、
                    # それより上／右に出る実マーカーは従来どおり残す。
                    lower_left_ui_right = min(
                        result_width,
                        int(round(frame.shape[1] * (430.0 / 1280.0))))
                    lower_left_ui_top = min(
                        result_height,
                        int(round(frame.shape[0] * (500.0 / 720.0))))
                    if (lower_left_ui_right > 0
                            and lower_left_ui_top < result_height):
                        result[
                            lower_left_ui_top:,
                            0:lower_left_ui_right] = -2.0
                _, score, _, location = cv2.minMaxLoc(result)
                threshold = float(variant.get("threshold", 0.5))
                marker_color_ratio=1.0
                if (getattr(self, "_za_mega_last_battle_mode", False)
                        and getattr(self, "_za_mega_movemode", 0) == 1):
                    # 小さい円弧テンプレートは紫の壁や柱の輪郭にも0.5前後で
                    # 一致する。mode 5では実マーカーの青緑色も同時に確認し、
                    # 壁をターゲットとして保存方向を更新し続けない。
                    marker_x,marker_y=location
                    marker_patch=frame[
                        marker_y:marker_y + template_height,
                        marker_x:marker_x + template_width]
                    if marker_patch.size:
                        marker_hsv=cv2.cvtColor(
                            marker_patch, cv2.COLOR_BGR2HSV)
                        marker_color_mask=cv2.inRange(
                            marker_hsv, (80, 80, 100), (115, 255, 255))
                        marker_color_ratio=(
                            float(cv2.countNonZero(marker_color_mask))
                            / max(1, int(marker_color_mask.size)))
                    else:
                        marker_color_ratio=0.0
                normal_matched=(
                    float(score) >= threshold
                    and marker_color_ratio >= 0.22)
                detection_details.append({
                    "name": target,
                    "matched": normal_matched,
                    "score": float(score),
                    "marker_color_ratio": marker_color_ratio,
                    "position": location,
                    "template_size": (
                        int(template_width), int(template_height)),
                })
                if include_upper and not normal_matched:
                    # 上向き時に画面上端で欠けたマーカーだけをmode 4で補足する。
                    for trim_ratio in (0.25, 0.5):
                        trim_y = max(
                            1, min(
                                template_height - 2,
                                int(round(template_height * trim_ratio))))
                        upper_template = template_match[trim_y:, :]
                        upper_height, upper_width = upper_template.shape[:2]
                        search_height = min(
                            source_match.shape[0], upper_height + 5)
                        upper_source = source_match[:search_height, :]
                        if (upper_source.shape[0] < upper_height
                                or upper_source.shape[1] < upper_width):
                            continue
                        upper_result = cv2.matchTemplate(
                            upper_source,
                            upper_template,
                            cv2.TM_CCOEFF_NORMED).copy()
                        upper_result_height, upper_result_width = (
                            upper_result.shape[:2])
                        # 欠けたテンプレートは上端5px以内だけを候補とする。
                        if upper_result_height > 5:
                            upper_result[5:, :] = -2.0
                        upper_exclusion_right = min(
                            upper_result_width, 210)
                        if upper_exclusion_right > 0:
                            upper_result[:, :upper_exclusion_right] = -2.0
                        _, upper_score, _, upper_location = cv2.minMaxLoc(
                            upper_result)
                        upper_threshold = max(0.6, threshold)
                        detection_details.append({
                            "name": target,
                            "matched": (
                                float(upper_score) >= upper_threshold),
                            "score": float(upper_score),
                            "position": (
                                int(upper_location[0]),
                                int(upper_location[1]) - trim_y),
                            "template_size": (
                                int(template_width), int(template_height)),
                            "upper_clipped": True,
                        })
            if not detection_details:
                return 0
            matched_details = [
                item for item in detection_details
                if item.get("matched")]
            detail = max(
                matched_details or detection_details,
                key=lambda item: float(item.get("score", -1.0)))
            self.last_image_detection = detail
            if not detail.get("matched"):
                return 0
            x, y = detail["position"]
            width, height = detail["template_size"]
            marker_x = float(x) + float(width) / 2.0
            marker_y = float(y) + float(height) / 2.0
            self._za_mega_target_marker_position=(marker_x, marker_y)
            if (getattr(self, "_za_mega_last_battle_mode", False)
                    and getattr(self, "_za_mega_movemode", 0) == 1):
                # 色補助ではなく実マーカーを取れた時だけ、短時間の
                # ロックオン確認としてY技／攻撃可能フォールバックへ渡す。
                self._za_mega_mode5_lockon_confirmed_until=(
                    time.monotonic() + 0.8)
                self._za_mega_mode5_visual_lockon_until=(
                    time.monotonic() + 0.8)
                # 最後に見えた側は記録するが、右スティック探索方向は
                # ここで更新しない。再検知のたびに0/180度を反転すると
                # 同じ狭い範囲を往復するため、mode 5の探索は一方向を維持する。
                if marker_x < 610.0:
                    self._za_mega_marker_last_side=180.0
                elif marker_x > 670.0:
                    self._za_mega_marker_last_side=0.0
                self._za_mega_marker_search_retry_at=(
                    time.monotonic() + 0.15)
            delta_x = marker_x - 640.0
            delta_y = 720.0 - marker_y
            if abs(delta_x) < 1.0 and abs(delta_y) < 1.0:
                angle = 90.0
            else:
                angle = (
                    math.degrees(math.atan2(delta_y, delta_x))
                    + 360.0) % 360.0
            return Direction(Stick.LEFT, angle, 0.5)

        # 画像定義を持たない旧環境・単体テストでは従来判定へ戻す。
        if (self.image_check("POKEMON_ZA_TARGET_LEFT_LOW")
                or self.image_check("POKEMON_ZA_TARGET_LEFT_RIHGT_CHECK_LOW")):
            return -2
        if (self.image_check("POKEMON_ZA_TARGET_RIGHT_LOW")
                or self.image_check("POKEMON_ZA_TARGET_RIGHT_RIHGT_CHECK_LOW")):
            return -1
        return 0

    def ZA_mega_mode5_colored_enemy_direction(
            self, frame=None, allow_resume=False, blue_only=False,
            refresh_frame=False):
        """mode 5だけ、赤／青の敵色をマーカー未検出時の位置補助に使う。"""
        self._za_mega_colored_enemy_position=None
        self._za_mega_colored_enemy_color=None
        self._za_mega_colored_enemy_near=False
        # 移動へ使う確定色とは別に、このfresh frameで幾何条件まで通った
        # 生の敵色を残す。赤のみ復帰側がさらに3回・3秒確認するため、
        # ここで同じ3回安定化を二重に要求しない。
        self._za_mega_colored_enemy_observed_color=None
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or getattr(self, "_za_mega_movemode", 0) != 1):
            return 0
        now=time.monotonic()
        # 赤／青はテンプレート画像ではなく色領域なので、会話・選択肢・
        # 暗転・必殺技演出にも候補が現れる。直前に戦闘FIELDを画像確認した
        # 短い区間だけ許可し、画面外状態の色で移動方向を上書きしない。
        if (not allow_resume
                and (int(getattr(
                    self, "_za_mega_mode5_start_flag", 0)) != 4
                     or not getattr(
                        self, "_za_mega_mode5_battle_active", False)
                     or now >= float(getattr(
                        self, "_za_mega_mode5_color_field_until", 0.0)))):
            return 0
        if frame is None and not refresh_frame:
            frame=getattr(self, "_za_mega_last_target_frame", None)
        if frame is None:
            camera=getattr(self, "camera", None)
            if camera is None:
                return 0
            if hasattr(camera, "readFreshFrame"):
                frame=camera.readFreshFrame(timeout=0.75)
            else:
                frame=(camera.readFrame()
                       if hasattr(camera, "readFrame") else None)
        if frame is None or getattr(frame, "size", 0) == 0:
            return 0

        previous_position=getattr(
            self, "_za_mega_colored_enemy_track_position", None)
        previous_color=getattr(
            self, "_za_mega_colored_enemy_track_color", None)
        previous_seen=float(getattr(
            self, "_za_mega_colored_enemy_track_seen_at", 0.0))
        recent_track=bool(
            previous_position and now - previous_seen <= 0.9)
        height,width=frame.shape[:2]
        x0,x1=int(width * 0.06),int(width * 0.94)
        y0,y1=int(height * 0.08),int(height * 0.86)
        region=frame[y0:y1, x0:x1]
        if region.size == 0:
            return 0
        hsv=cv2.cvtColor(region, cv2.COLOR_BGR2HSV)
        blue_channel,green_channel,red_channel=cv2.split(region)
        blue_i=blue_channel.astype("int16")
        green_i=green_channel.astype("int16")
        red_i=red_channel.astype("int16")
        # 最終戦の赤敵は赤紫側(H=158～179)。通常赤(H=0～12)まで含めると
        # 主人公の髪・手持ちUIを敵として拾うため、ここでは対象外にする。
        red_hsv_mask=cv2.inRange(hsv, (158, 125, 105), (179, 255, 255))
        # Hueだけでは紫壁や暗い演出を拾うため、BGRでも赤成分が緑より
        # 十分強く、青より大幅に弱くないことを確認する。
        red_dominant=(
            (red_i >= green_i + 38)
            & (red_i >= blue_i - 20)
            & (red_channel >= 110))
        red_mask=cv2.bitwise_and(
            red_hsv_mask, red_dominant.astype("uint8") * 255)
        # 録画で青敵はH=103～113付近、背景の紫～青壁は
        # H=119以上が主だったため、青側を狭くして背景を除外する。
        blue_hsv_mask=cv2.inRange(hsv, (102, 150, 105), (115, 255, 255))
        # 暗い青背景や半透明UIはVが低く、BとGの差も小さい。
        # 青敵本体の青優勢画素だけをHSV候補へ重ねる。
        blue_dominant=(
            (blue_i >= red_i + 28)
            & (blue_i >= green_i + 8)
            & (blue_channel >= 110))
        blue_mask=cv2.bitwise_and(
            blue_hsv_mask, blue_dominant.astype("uint8") * 255)
        player_x=float(width) * 0.50
        player_y=float(height) * 0.90
        frame_area=float(width * height)
        candidates=[]
        open_kernel=cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3))
        close_kernel=cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (7, 7))
        for color_name,raw_mask in (("red", red_mask), ("blue", blue_mask)):
            mask=cv2.morphologyEx(raw_mask, cv2.MORPH_OPEN, open_kernel)
            mask=cv2.morphologyEx(mask, cv2.MORPH_CLOSE, close_kernel)
            contours,_=cv2.findContours(
                mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            for contour in contours:
                area=float(cv2.contourArea(contour))
                if area < max(600.0, frame_area * 0.00065):
                    continue
                rect_x,rect_y,rect_w,rect_h=cv2.boundingRect(contour)
                if (rect_w < int(width * 0.012)
                        or rect_h < int(height * 0.022)):
                    continue
                if (rect_w < int(width * 0.07)
                        and rect_h < int(height * 0.07)):
                    continue
                aspect=float(rect_w) / max(1.0, float(rect_h))
                if aspect < 0.16 or aspect > 6.0:
                    continue
                # 横長の通知・手持ちUIを除外する。敵の赤／青部位は縦長、
                # または画面高の25%以上を占める大きな連続領域になる。
                if (rect_h < int(rect_w * 0.85)
                        and rect_h < int(height * 0.25)):
                    continue
                # 被弾時の画面端の赤、上部HPバー、下部技UIは敵にしない。
                # 一方、録画では生存中の青敵が画面左端で欠け、検知ROIの
                # 左境界へ接したことで青なしと誤判定されていた。左下UIは
                # 後段の位置条件で除外し、中段にある十分高い青敵だけ許可する。
                blue_enemy_at_left_edge=(
                    color_name == "blue"
                    and rect_x <= 2
                    and rect_h >= int(height * 0.10)
                    and rect_y + y0 < int(height * 0.62)
                    and rect_y + y0 + rect_h > int(height * 0.18))
                if ((rect_x <= 2 and not blue_enemy_at_left_edge)
                        or rect_x + rect_w >= region.shape[1] - 2
                        or rect_y + rect_h >= region.shape[0] - 2):
                    continue
                center_x=float(rect_x + rect_w * 0.5 + x0)
                center_y=float(rect_y + rect_h * 0.5 + y0)
                global_top=rect_y + y0
                global_bottom=global_top + rect_h
                # 常時表示される上部HP／名称と下部の手持ち・技UIは、
                # 赤青が連続していても敵本体ではない。
                if global_bottom <= int(height * 0.18):
                    continue
                if global_top >= int(height * 0.78):
                    continue
                if (center_y > float(height) * 0.62
                        and (center_x < float(width) * 0.36
                             or center_x > float(width) * 0.70)):
                    continue
                # 全画面寄りの色フラッシュや太い攻撃エフェクトを除外する。
                # 敵本体として追う範囲は画面幅42%・高さ58%以内に限定する。
                if (rect_w > int(width * 0.42)
                        or rect_h > int(height * 0.58)):
                    continue
                # 主人公の赤い髪は中央付近にある小～中サイズの縦領域。
                # ここを除外しないと、敵を見失った時に自分へ追従してしまう。
                if (color_name == "red"
                        and float(width) * 0.38 <= center_x <= float(width) * 0.62
                        and float(height) * 0.18 <= center_y
                        and rect_w < int(width * 0.18)
                        and rect_h < int(height * 0.38)):
                    continue
                # 左下は手持ち・HP表示の固定領域。敵色よりUIを優先して
                # しまうため、画面下寄りの左側候補は追従対象から外す。
                if (center_x < float(width) * 0.34
                        and center_y > float(height) * 0.62):
                    continue
                if center_y < float(height) * 0.18 and aspect > 2.5:
                    continue
                if (rect_w > int(width * 0.40)
                        and rect_h < int(height * 0.12)):
                    continue
                color_pixels=float(cv2.countNonZero(
                    raw_mask[rect_y:rect_y + rect_h,
                             rect_x:rect_x + rect_w]))
                minimum_pixels=max(900.0, frame_area * 0.0009)
                coverage=color_pixels / max(1.0, float(rect_w * rect_h))
                hull_area=float(cv2.contourArea(cv2.convexHull(contour)))
                solidity=area / max(1.0, hull_area)
                if (color_pixels < minimum_pixels
                        or coverage < 0.10
                        or solidity < 0.56):
                    continue
                center_distance=(
                    abs(center_x - player_x) / max(1.0, float(width) * 0.5))
                score=color_pixels * max(0.65, 1.10 - 0.30 * center_distance)
                # 最大面積だけで選ぶと、同じ敵の複数部位間で中心Xが飛ぶ。
                # 直近0.9秒は同色かつ近い輪郭を優先し、追従方向を安定させる。
                if recent_track:
                    track_distance=math.hypot(
                        center_x - float(previous_position[0]),
                        center_y - float(previous_position[1]))
                    track_ratio=(track_distance
                                 / max(1.0, float(width) * 0.45))
                    if color_name == previous_color and track_ratio <= 1.0:
                        score*=1.0 + 2.5 * (1.0 - track_ratio)
                    elif color_name == previous_color:
                        score*=0.55
                    else:
                        score*=0.40
                candidates.append((
                    score, color_pixels, color_name, center_x, center_y,
                    rect_x + x0, rect_y + y0, rect_w, rect_h, coverage,
                    solidity))
        if not candidates:
            return 0

        # 両方を同時に確認できた場合は、先に倒したい青敵を優先する。
        # 候補なしの色を無理に選ばず、青が見えない時だけ赤へ戻す。
        blue_candidates=[
            candidate for candidate in candidates
            if candidate[2] == "blue"]
        if blue_only and not blue_candidates:
            return 0
        preferred_candidates=(
            blue_candidates if blue_only else (blue_candidates or candidates))
        (score,color_pixels,color_name,raw_target_x,raw_target_y,
         rect_x,rect_y,rect_w,rect_h,coverage,solidity)=max(
             preferred_candidates, key=lambda item: item[0])
        del score
        self._za_mega_colored_enemy_observed_color=color_name
        # 色だけでの初回一致は、攻撃エフェクトの一瞬の発光と区別できない。
        # 実ロックオン画像がない場合は、同色・近い位置・近い面積を3回
        # 連続確認してから移動へ使う。実マーカー／C+／EYE確認中は
        # 移動角度をdir1へ固定するため、即時確定しても急旋回しない。
        previous_candidate_position=getattr(
            self, "_za_mega_colored_enemy_candidate_position", None)
        previous_candidate_color=getattr(
            self, "_za_mega_colored_enemy_candidate_color", None)
        previous_candidate_pixels=float(getattr(
            self, "_za_mega_colored_enemy_candidate_pixels", 0.0))
        previous_candidate_seen=float(getattr(
            self, "_za_mega_colored_enemy_candidate_seen_at", 0.0))
        candidate_hits=int(getattr(
            self, "_za_mega_colored_enemy_candidate_hits", 0))
        position_close=bool(
            previous_candidate_position
            and math.hypot(
                float(raw_target_x) - float(previous_candidate_position[0]),
                float(raw_target_y) - float(previous_candidate_position[1]))
            <= float(width) * 0.10)
        area_ratio=(
            color_pixels / max(1.0, previous_candidate_pixels))
        candidate_continues=bool(
            previous_candidate_color == color_name
            and now - previous_candidate_seen <= 5.0
            and position_close
            and 0.55 <= area_ratio <= 1.80)
        candidate_hits=(candidate_hits + 1 if candidate_continues else 1)
        self._za_mega_colored_enemy_candidate_position=(
            float(raw_target_x), float(raw_target_y))
        self._za_mega_colored_enemy_candidate_color=color_name
        self._za_mega_colored_enemy_candidate_pixels=color_pixels
        self._za_mega_colored_enemy_candidate_seen_at=now
        self._za_mega_colored_enemy_candidate_hits=candidate_hits
        visual_lockon_active=bool(
            getattr(self, "ZL_state", 0) == 1
            and now < float(getattr(
                self, "_za_mega_mode5_visual_lockon_until", 0.0)))
        accepted_track=bool(
            recent_track and candidate_continues
            and color_name == previous_color
            and math.hypot(
                float(raw_target_x) - float(previous_position[0]),
                float(raw_target_y) - float(previous_position[1]))
            <= float(width) * 0.12)
        if not (visual_lockon_active or accepted_track or candidate_hits >= 3):
            return 0
        target_x=float(raw_target_x)
        target_y=float(raw_target_y)
        if (recent_track and color_name == previous_color
                and math.hypot(
                    target_x - float(previous_position[0]),
                    target_y - float(previous_position[1]))
                <= float(width) * 0.45):
            # 新しい位置をやや強くしたEMAで、追従性を残しながら座標飛びを抑える。
            target_x=float(previous_position[0]) * 0.45 + target_x * 0.55
            target_y=float(previous_position[1]) * 0.45 + target_y * 0.55
        self._za_mega_colored_enemy_track_position=(target_x, target_y)
        self._za_mega_colored_enemy_track_color=color_name
        self._za_mega_colored_enemy_track_seen_at=now
        self._za_mega_colored_enemy_position=(target_x, target_y)
        self._za_mega_colored_enemy_color=color_name
        # 敵の中心が下寄り、または輪郭が大きい場合は十分近い。
        # movemode側で直進を止め、距離を保つ横移動へ切り替える。
        self._za_mega_colored_enemy_near=bool(
            target_y >= float(height) * 0.58
            or rect_h >= int(height * 0.30)
            or rect_w >= int(width * 0.22))
        self._za_mega_target_marker_position=(target_x, target_y)
        self._za_mega_target_from_color=True
        if target_x < 610.0:
            self._za_mega_marker_last_side=180.0
        elif target_x > 670.0:
            self._za_mega_marker_last_side=0.0
        delta_x=target_x - player_x
        delta_y=player_y - target_y
        angle=(math.degrees(math.atan2(delta_y, delta_x)) + 360.0) % 360.0
        detection_key=(color_name, int(target_x // 120), int(target_y // 120))
        if detection_key != getattr(
                self, "_za_mega_colored_enemy_log_key", None):
            print(
                "[MEGA_MOVEMODE] colored enemy {} x={:.0f} y={:.0f} "
                "pixels={:.0f}".format(
                    color_name, target_x, target_y, color_pixels))
            self._za_mega_colored_enemy_log_key=detection_key
        self.last_image_detection={
            "name": "ZA_MODE5_COLORED_ENEMY_{}".format(color_name.upper()),
            "matched": True,
            "position": (int(rect_x), int(rect_y)),
            "template_size": (int(rect_w), int(rect_h)),
            "color_pixels": color_pixels,
            "coverage": coverage,
            "solidity": solidity,
            "candidate_hits": candidate_hits,
            "visual_lockon": visual_lockon_active,
            "standoff": self._za_mega_colored_enemy_near,
        }
        if hasattr(self, "displayRectangle"):
            # 通常の画像検知と同じプレビュー座標へ、確定した色候補だけを
            # 短時間表示する。赤敵は赤、青敵は青の枠で区別する。
            outline=("#ff1744" if color_name == "red" else "#00b0ff")
            self.displayRectangle(
                (int(rect_x), int(rect_y)), int(rect_w), int(rect_h),
                tag="ZA_MODE5_COLOR_{}_{}".format(
                    color_name.upper(), int(time.perf_counter() * 1000)),
                ms=600, color=[outline, "orange"], crop=[])
        return Direction(Stick.LEFT, angle, 0.5)

    def ZA_mega_mode5_marker_search_view_stop(self, relock=False):
        """mode 5の連続視点探索を安全に解除する。"""
        if getattr(self, "_za_mega_marker_search_view_holding", False):
            search_angle=float(getattr(
                self, "_za_mega_marker_search_view_angle", 180.0))
            self.holdEnd(Direction(Stick.RIGHT, search_angle))
        self._za_mega_marker_search_view_holding=False
        self._za_mega_marker_search_lock_until=0.0
        if relock:
            # ZL_state=1でもゲーム側の対象だけ外れている場合があるため、
            # 解除→再保持を行い、0.45秒の画像確認猶予へ入る。
            self.ZA_ZL_ACTION("")
        return True

    def ZA_mega_mode5_colored_enemy_relock(self):
        """赤／青の敵位置へ短く視点を寄せ、ZLを再保持する。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or getattr(self, "_za_mega_movemode", 0) != 1):
            return False
        position=getattr(self, "_za_mega_colored_enemy_position", None)
        if not position:
            return False
        now=time.monotonic()
        if now < float(getattr(
                self, "_za_mega_colored_relock_retry_at", 0.0)):
            return True

        # 実マーカー／EYEでロックオンを確認できている間は、色補助で
        # ZLを解除しない。ゲーム側の追尾を優先し、色は移動方向だけに使う。
        if (getattr(self, "ZL_state", 0) == 1
                and now < float(getattr(
                    self, "_za_mega_mode5_visual_lockon_until", 0.0))):
            # 実ロックオン確認中は右視点だけ止める。relock=Trueは
            # ZLを一度解放して再入力するため、確認済みロックを壊してしまう。
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self._za_mega_colored_relock_retry_at=now + 0.6
            return True

        # 緑床を待つ開始直後は色を移動方向にだけ使い、視点は動かさない。
        green_priority_active=bool(
            getattr(self, "_za_mega_mode5_initial_phase_active", False)
            or int(getattr(
                self, "_za_mega_mode5_green_priority_checks_remaining", 0)) > 0)
        if ((green_priority_active
             and not getattr(self, "_za_mega_z_guard_holding", False))
                or now < float(getattr(
                    self, "_za_mega_mode5_view_search_block_until", 0.0))):
            self.ZA_mega_mode5_marker_search_view_stop(relock=True)
            self._za_mega_colored_relock_retry_at=now + 0.35
            return True

        frame=getattr(self, "_za_mega_last_target_frame", None)
        width=(float(frame.shape[1]) if frame is not None
               and getattr(frame, "size", 0) else 1280.0)
        target_x=float(position[0])
        center_x=width * 0.5
        # 中央付近なら左右補正を繰り返さず、ZLだけを保持する。
        deadband=width * 0.14
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        if abs(target_x - center_x) <= deadband:
            if getattr(self, "ZL_state", 0) == 0:
                self.ZA_ZL_ACTION("")
            self._za_mega_colored_relock_retry_at=now + 0.35
            return True

        view_angle=180.0 if target_x < center_x else 0.0
        horizontal_ratio=min(
            1.0, abs(target_x - center_x) / max(1.0, center_x))
        view_seconds=max(0.06, min(0.16, horizontal_ratio * 0.20))
        # 色位置は補助判定なので、既に保持しているZLを解除しない。
        # ロック済みなら右入力はゲーム側の追尾を壊さず、未ロックなら
        # ZLを保持したまま短く視点を寄せて再捕捉を狙える。
        relock_after_pulse=(getattr(self, "ZL_state", 0) == 0)
        self.press(
            Direction(Stick.RIGHT, view_angle, 0.48),
            duration=view_seconds,
            wait=0.0)
        if relock_after_pulse:
            self.ZA_ZL_ACTION("")
        # ZL再保持後にゲーム側がロックオンする猶予を与え、細かな解除を防ぐ。
        self._za_mega_colored_relock_retry_at=now + 0.85
        print(
            "[MEGA_COLOR_RELOCK] {} x={:.0f} view={:.0f} duration={:.2f}s".format(
                getattr(self, "_za_mega_colored_enemy_color", "enemy"),
                target_x, view_angle, view_seconds))
        return True

    def ZA_mega_mode5_marker_search_view(self):
        """mode 5でマーカーを見失った間、最後の左右へ視点を連続して送る。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or getattr(self, "_za_mega_movemode", 0) != 1):
            return False
        if (getattr(self, "_za_mega_testmode1_enabled", False)
                and getattr(self, "_za_mega_testmode1_phase", "")
                not in {"EXISTING_CHARGE", "FREE_RUN", "LEGACY_COMBAT"}):
            # TESTMODE1は再開準備から障害物攻撃まで視点を固定する。
            # 予兆検知後のcharge処理と赤敵だけになった後の既存mode5は、
            # それぞれの専用／通常右視点確認を許可する。
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            return False
        now=time.monotonic()
        green_hold_active=bool(getattr(
            self, "_za_mega_z_guard_holding", False))
        if (not green_hold_active and (
                getattr(
                    self, "_za_mega_mode5_initial_phase_active", False)
                or int(getattr(
                    self,
                    "_za_mega_mode5_green_priority_checks_remaining",
                    0)) > 0
                or now < float(getattr(
                    self,
                    "_za_mega_mode5_view_search_block_until",
                    0.0)))):
            # 開始直後は正面の敵と緑床を先に確認し、右スティックで
            # 画面を動かさない。既に残る探索保持もここで解除する。
            if getattr(self, "_za_mega_marker_search_view_holding", False):
                self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            if not getattr(
                    self, "_za_mega_mode5_view_search_block_logged", False):
                print("[MEGA_VIEW_SEARCH] initial hold; prioritize green floor")
                self._za_mega_mode5_view_search_block_logged=True
            return True
        self._za_mega_mode5_view_search_block_logged=False
        if getattr(self, "_za_mega_marker_search_view_holding", False):
            if now < getattr(self, "_za_mega_marker_search_retry_at", 0.0):
                return True
            # 連続回転の間にZLを保持する周期を入れ、マーカーを
            # 画面に入れただけで通り越さないようにする。
            self.ZA_mega_mode5_marker_search_view_stop(relock=True)
            self._za_mega_marker_search_lock_until=now + 0.45
            print("[MEGA_VIEW_SEARCH] pause view; ZL relock check")
            trace=getattr(self, "ZA_mega_mode5_trace", None)
            if callable(trace):
                trace(
                    "TARGET_MARKER_MISSING",
                    "pause view and retry ZL for 0.45s")
            return True
        if now < getattr(self, "_za_mega_marker_search_lock_until", 0.0):
            return True
        search_angle=float(getattr(
            self, "_za_mega_marker_search_direction", 180.0))
        if search_angle not in (0.0, 180.0):
            search_angle=180.0
        # press(0.2秒)で毎回中立へ戻さず、画像チェック中も視点入力を
        # 保持する。探索方向は時間で左右反転させない。
        search_strength=max(0.45, min(0.6, float(getattr(
            self, "_za_mega_marker_search_strength", 0.24)) * 2.0))
        # 探索のたびにZLを解除すると、敵を画面へ入れても攻撃可能に
        # 戻るまで空白が生じる。ZLは保持し、未保持時だけ先に押す。
        if getattr(self, "ZL_state", 0) == 0:
            self.ZA_ZL_ACTION("")
        self.hold(Direction(Stick.RIGHT, search_angle, search_strength), wait=0.0)
        self._za_mega_marker_search_view_holding=True
        self._za_mega_marker_search_view_angle=search_angle
        self._za_mega_marker_search_retry_at=now + 0.70
        print(
            "[MEGA_VIEW_SEARCH] rotate angle={:.0f} strength={:.2f}".format(
                search_angle, search_strength))
        trace=getattr(self, "ZA_mega_mode5_trace", None)
        if callable(trace):
            trace(
                "TARGET_MARKER_MISSING",
                "hold right-stick view angle={:.0f}".format(search_angle))
        return True

    def ZA_mega_mode5_free_run_update(self, dir1, dir2, dir3, dir4):
        """300秒無攻撃後だけ、視点探索・連続移動・安全なA攻撃を行う。"""
        if (getattr(self, "_za_mega_mode5_rpush_wait_field", False)
                or getattr(
                    self,
                    "_za_mega_mode5_rpush_post_field_move_pending",
                    False)):
            return False
        if not getattr(self, "_za_mega_mode5_free_run_active", False):
            return False
        if self.ZA_mega_mode5_event_attack_blocked():
            return False
        if not self.ZA_mega_mode5_a_attack_ready():
            return False
        now=time.monotonic()
        marker=self.ZA_mega_target_marker_direction()
        visual_lock=bool(
            getattr(self, "ZL_state", 0) == 1
            and now < float(getattr(
                self, "_za_mega_mode5_visual_lockon_until", 0.0)))
        if isinstance(marker, Direction) or visual_lock:
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            if getattr(self, "ZL_state", 0) == 0:
                self.ZA_ZL_ACTION("")
        else:
            # 左右の細かな往復ではなく、同じ向きへの視点探索を続ける。
            self.ZA_mega_mode5_marker_search_view()
        elapsed=max(0.0, now - float(getattr(
            self, "_za_mega_mode5_free_run_started_at", now))) % 9.0
        move_angle=(20.0 if elapsed < 4.0 else
                    300.0 if elapsed < 7.0 else 160.0)
        self.ZA_MOVE_LStick(
            dir1, dir2, dir3, dir4,
            Direction(Stick.LEFT, move_angle, 1.0),
            "RELOAD", force_direction=True)
        if move_angle != getattr(
                self, "_za_mega_mode5_free_run_move_angle", None):
            self._za_mega_mode5_free_run_move_angle=move_angle
            self.ZA_mega_mode5_trace(
                "FREE_RUN_MOVE",
                "continuous move angle={:.0f}; view search".format(
                    move_angle), force=True)
        if now >= float(getattr(
                self, "_za_mega_mode5_free_run_next_attack_at", 0.0)):
            self.pressRep(
                Button.A, repeat=1, duration=0.04,
                wait=0.0, interval=0.1)
            self.ZA_mega_mode5_note_attack_input("A_FREE_RUN")
            self._za_mega_mode5_free_run_next_attack_at=(
                time.monotonic() + 0.6)
        return True

    def ZA_mega_movemode_update(
            self, dir1, dir2, dir3, dir4, include_upper=0):
        """movemode 1で未ロック時は接近し、ロック後は距離を保つ。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or getattr(self, "_za_mega_movemode", 0) != 1):
            return False
        now=time.monotonic()
        visual_lockon_active=bool(
            getattr(self, "ZL_state", 0) == 1
            and now < float(getattr(
                self, "_za_mega_mode5_visual_lockon_until", 0.0)))
        if (getattr(
                self, "_za_mega_mode5_low_yellow_hp_active", False)
                and visual_lockon_active):
            self._za_mega_mode5_low_yellow_hp_lock_seen=True
        yellow_low_hp_post_lock=bool(
            getattr(self, "_za_mega_mode5_low_yellow_hp_active", False)
            and getattr(
                self, "_za_mega_mode5_low_yellow_hp_lock_seen", False))
        initial_phase_active=bool(getattr(
            self, "_za_mega_mode5_initial_phase_active", False))
        initial_approach_started=bool(getattr(
            self, "_za_mega_mode5_initial_approach_started", False))
        initial_approach_until=float(getattr(
            self, "_za_mega_field_dir5_until", 0.0))
        if (initial_phase_active and initial_approach_started
                and initial_approach_until > 0.0
                and now >= initial_approach_until):
            # 緑床確認回数は画像判定の重さで実時間が大きく延びるため、
            # 3秒の初期接近終了後まで90度移動を拘束しない。
            # 未消費の確認回数も破棄し、この周回から視点探索へ切り替える。
            self._za_mega_field_dir5_until=0.0
            self._za_mega_mode5_initial_phase_active=False
            self._za_mega_mode5_green_priority_checks_remaining=0
            self._za_mega_mode5_view_search_block_until=0.0
            initial_phase_active=False
            print(
                "[MEGA_INITIAL_MOVE] 90deg approach timeout; "
                "release move and allow target search")
        if now < getattr(self, "_za_mega_field_dir5_until", 0.0):
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,5,"RELOAD")
            return True
        if initial_phase_active:
            # 緑床の優先確認と90度の開始移動が終わるまで、マーカー／敵色を
            # 調べず同じ方向を維持する。視点探索へ早く抜けて壁へ向かわない。
            if (int(getattr(
                    self,
                    "_za_mega_mode5_green_priority_checks_remaining",
                    0)) <= 0):
                self._za_mega_mode5_initial_phase_active=False
                self._za_mega_mode5_view_search_block_until=0.0
                print(
                    "[MEGA_INITIAL_MOVE] 90deg approach complete; "
                    "allow target search")
            else:
                self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,5,"RELOAD")
                return True

        marker_direction = self.ZA_mega_target_marker_direction(
            include_upper=bool(include_upper))
        if not isinstance(marker_direction, Direction):
            color_detector=getattr(
                self, "ZA_mega_mode5_colored_enemy_direction", None)
            if callable(color_detector):
                marker_direction=color_detector(
                    frame=getattr(self, "_za_mega_last_target_frame", None))
        if not isinstance(marker_direction, Direction):
            cached_direction = getattr(
                self, "_za_mega_movemode_direction", None)
            if (isinstance(cached_direction, Direction)
                    and now < getattr(
                        self, "_za_mega_movemode_direction_until", 0.0)):
                # 攻撃演出などの一時的な未検知では直前方向を短く使う。
                # mode 5は短いpressを繰り返すと中立パケットのたびに減速する。
                # 強度1.0の保持を継続し、その間も同じ方向へ視点探索する。
                if getattr(self, "ZL_state", 0) == 0:
                    self.ZA_ZL_ACTION("")
                self._za_mega_movemode_searching=False
                cached_angle=float(cached_direction.angle_for_show)
                if yellow_low_hp_post_lock:
                    # ロックオン後に残っていた接近方向（55～60度前後）を
                    # 再送しない。近距離後退中だけ300度、それ以外は
                    # 20度の距離維持へ置き換える。
                    cached_angle=(
                        300.0 if getattr(
                            self, "_za_mega_mode5_lockon_retreating", False)
                        else 20.0)
                cached_movement=Direction(
                    Stick.LEFT, cached_angle, 1.0)
                self._za_mega_movemode_direction=cached_movement
                self.ZA_MOVE_LStick(
                    dir1,dir2,dir3,dir4,
                    cached_movement,
                    "RELOAD", force_direction=True)
                if visual_lockon_active:
                    stop_search=getattr(
                        self, "ZA_mega_mode5_marker_search_view_stop", None)
                    if callable(stop_search):
                        stop_search(relock=False)
                else:
                    self.ZA_mega_mode5_marker_search_view()
                return True
            # 保存方向が切れた後も、最後に見えた側へ強度1.0で移動し続け、
            # 右スティックを一定方向へ保持して赤／青またはマーカーを探す。
            self._za_mega_movemode_searching=True
            self.ZA_mega_mode5_marker_search_view()
            last_side=getattr(self, "_za_mega_marker_last_side", None)
            if yellow_low_hp_post_lock:
                # 黄色低HPで一度ロックオンした後は、未検知になっても
                # 55／125度の接近フォールバックへ戻さない。
                fallback_angle=(
                    160.0 if last_side == 180.0 else 20.0)
            else:
                fallback_angle=125.0 if last_side == 180.0 else 55.0
            fallback_movement=Direction(
                Stick.LEFT, fallback_angle, 1.0)
            self._za_mega_movemode_direction=fallback_movement
            self._za_mega_movemode_direction_until=now + 0.8
            self.ZA_MOVE_LStick(
                dir1,dir2,dir3,dir4,
                fallback_movement,"RELOAD",force_direction=True)
            if not getattr(
                    self, "_za_mega_movemode_fallback_logged", False):
                print(
                    "[MEGA_MOVEMODE] marker missing; "
                    "hold move angle={:.0f} strength=1.0 while view searches".format(
                        fallback_angle))
                self._za_mega_movemode_fallback_logged=True
            trace=getattr(self, "ZA_mega_mode5_trace", None)
            if callable(trace):
                trace(
                    "TARGET_AND_COLOR_MISSING",
                    "continuous move angle={:.0f} while view searches".format(
                        fallback_angle))
            return True

        target_from_color=bool(getattr(
            self, "_za_mega_target_from_color", False))
        if target_from_color:
            # 色を検出できている間に固定方向の全周探索を続けると、敵を
            # 画面へ入れた直後に通り越す。敵側へ短く寄せてZLを再保持する。
            self._za_mega_movemode_searching=True
            self.ZA_mega_mode5_colored_enemy_relock()
        else:
            # 実マーカーを取り直した場合だけ視点保持を止め、
            # 移動より先にロックオンを戻す。
            stop_search=getattr(
                self, "ZA_mega_mode5_marker_search_view_stop", None)
            if callable(stop_search):
                stop_search(relock=False)
            if getattr(self, "ZL_state", 0) == 0:
                self.ZA_ZL_ACTION("")
        marker_angle=float(marker_direction.angle_for_show) % 360.0
        marker_position=getattr(
            self, "_za_mega_target_marker_position", None)
        visual_color_lockon=bool(
            target_from_color
            and getattr(self, "ZL_state", 0) == 1
            and now < float(getattr(
                self, "_za_mega_mode5_visual_lockon_until", 0.0)))
        visual_lockon_confirmed=bool(
            getattr(self, "ZL_state", 0) == 1
            and now < float(getattr(
                self, "_za_mega_mode5_visual_lockon_until", 0.0)))
        yellow_low_hp_standoff=bool(
            getattr(
                self, "_za_mega_mode5_low_yellow_hp_active", False)
            and visual_lockon_confirmed)
        if yellow_low_hp_standoff:
            self._za_mega_mode5_low_yellow_hp_lock_seen=True
        yellow_low_hp_post_lock=bool(
            getattr(self, "_za_mega_mode5_low_yellow_hp_active", False)
            and getattr(
                self, "_za_mega_mode5_low_yellow_hp_lock_seen", False))
        # 画面中央付近でも敵の輪郭が大きい場合は接近を打ち切る。
        # マーカーが下寄り、または赤青敵が近い間は横移動で距離を保つ。
        color_target_near=bool(
            target_from_color and getattr(
                self, "_za_mega_colored_enemy_near", False))
        marker_y=(
            float(marker_position[1])
            if marker_position else 0.0)
        lockon_retreating=bool(getattr(
            self, "_za_mega_mode5_lockon_retreating", False))
        if yellow_low_hp_standoff:
            # 近距離で斜め後退を開始し、十分に離れるまでは継続する。
            # 開始と終了の境界を分け、1フレームの位置揺れで
            # 300度／20度を往復しないようにする。
            if lockon_retreating:
                lockon_retreating=bool(
                    color_target_near or marker_y > 360.0)
            else:
                lockon_retreating=bool(
                    color_target_near or marker_y >= 420.0)
        else:
            lockon_retreating=False
        self._za_mega_mode5_lockon_retreating=lockon_retreating
        near_target=bool(
            marker_position
            and (float(marker_position[1]) >= 460.0
                 or color_target_near
                 or lockon_retreating))
        previous_near=bool(getattr(
            self, "_za_mega_movemode_near_target", False))
        if yellow_low_hp_standoff:
            # 黄色HP約1/4で再開した場合だけ、ロックオン後は敵方向へ
            # 接近し続けない。近い間は通常方向に対応する斜め後方
            # （0度側なら300度）へ下がり、ロックオンを維持できる距離まで
            # 離れたら0～20度側の横移動へ切り替える。攻撃は継続する。
            normal_angle=float(dir1) % 360.0
            normal_on_right=bool(
                normal_angle <= 90.0 or normal_angle >= 270.0)
            if lockon_retreating:
                move_angle=300.0 if normal_on_right else 240.0
            else:
                move_angle=(
                    max(0.0, min(20.0, normal_angle))
                    if normal_on_right
                    else max(160.0, min(180.0, normal_angle)))
            movement=Direction(Stick.LEFT, move_angle, 1.0)
            self._za_mega_movemode_orbit_until=0.0
        elif yellow_low_hp_post_lock:
            # 一度ロックオンした後に画像が一時的に外れても、赤青の
            # 位置由来の約60～90度へ接近しない。20度側で距離を保ち、
            # 視点探索とZL再入力による再捕捉だけを行う。
            normal_angle=float(dir1) % 360.0
            move_angle=(
                max(0.0, min(20.0, normal_angle))
                if normal_angle <= 90.0 or normal_angle >= 270.0
                else max(160.0, min(180.0, normal_angle)))
            movement=Direction(Stick.LEFT, move_angle, 1.0)
            self._za_mega_movemode_orbit_until=0.0
        elif visual_color_lockon:
            # ロックオン済みならゲーム側が敵を正面へ追尾する。近距離では
            # 直進せず20/160度の横移動へ切り替え、攻撃距離を残す。
            if near_target:
                orbit_sign=int(getattr(
                    self, "_za_mega_movemode_orbit_sign", 1))
                if orbit_sign not in (-1, 1):
                    orbit_sign=1
                self._za_mega_movemode_orbit_sign=orbit_sign
                move_angle=(160.0 if orbit_sign > 0 else 20.0)
            else:
                move_angle=max(20.0, min(160.0, float(dir1)))
            movement=Direction(Stick.LEFT, move_angle, 1.0)
            self._za_mega_movemode_orbit_until=0.0
        elif near_target:
            orbit_sign=int(getattr(
                self, "_za_mega_movemode_orbit_sign", 1))
            if orbit_sign not in (-1, 1):
                orbit_sign=1
            self._za_mega_movemode_orbit_sign=orbit_sign
            # 周回方向も3秒ごとに反転するとロックオンカメラも
            # 左右往復し、移動幅が小さくなる。mode 5は一方向の周回を維持する。
            self._za_mega_movemode_orbit_until=now + 3.0
            # mode 5では後方（180～360度）へ回り込むとロックオンが外れ
            # やすいため、前方半面の範囲でだけ左右へ動く。
            # 真横の0/180度まで寄せると、緑床待機の解除直後などに
            # 床の外へ一直線に抜けやすい。前方寄りの20～160度に留める。
            move_angle=max(
                20.0,
                min(160.0, marker_angle + 55.0 * orbit_sign))
            movement=Direction(Stick.LEFT, move_angle, 1.0)
        else:
            # 接近時も真横・後方へ抜けない。マーカーが端に見えても
            # 前方成分を残し、柵へ0度で押し続ける状態を避ける。
            move_angle=max(20.0, min(160.0, marker_angle))
            movement=Direction(Stick.LEFT, move_angle, 1.0)
            self._za_mega_movemode_orbit_until=0.0

        self._za_mega_movemode_fallback_logged=False
        self._za_mega_movemode_searching=target_from_color
        self._za_mega_movemode_missing_move_retry_at=0.0
        self._za_mega_movemode_near_target=near_target
        self._za_mega_movemode_direction=movement
        # 攻撃演出でマーカーが短時間隠れても接近方向を失わない。
        # 誤検知した壁方向を長く保持しない。短い攻撃演出だけを補える
        # 1.0秒に留め、その後は固定方向の視点探索へ移る。
        self._za_mega_movemode_direction_until=(
            now + (
                0.35 if lockon_retreating
                else (0.55 if getattr(
                    self, "_za_mega_target_from_color", False) else 1.0)))
        # ターゲット捕捉後も中立へ戻さず、強度1.0を次の判定まで保持する。
        # 次周回で位置を取り直して方向だけ置換するため、停止パルスを挟まない。
        self.ZA_MOVE_LStick(
            dir1,dir2,dir3,dir4,
            movement,"RELOAD",force_direction=True)
        trace=getattr(self, "ZA_mega_mode5_trace", None)
        if callable(trace):
            if target_from_color:
                detection="{}_ENEMY".format(str(getattr(
                    self, "_za_mega_colored_enemy_color", "COLOR")).upper())
            else:
                detection=str(getattr(
                    self, "last_image_detection", {}).get(
                        "name", "TARGET_MARKER"))
            if yellow_low_hp_standoff and lockon_retreating:
                trace_action=(
                    "yellow low HP lock; diagonal retreat angle={:.1f}")
            elif yellow_low_hp_standoff:
                trace_action=(
                    "yellow low HP lock; range reached lateral angle={:.1f}")
            elif yellow_low_hp_post_lock:
                trace_action=(
                    "yellow low HP post-lock; block approach angle={:.1f}")
            elif visual_color_lockon and near_target:
                trace_action=(
                    "visual lock close; standoff move angle={:.1f}")
            elif visual_color_lockon:
                trace_action=(
                    "visual lock confirmed; hold dir1 angle={:.1f}")
            else:
                trace_action=(
                    "continuous move angle={:.1f} toward target")
            trace(
                detection,
                trace_action.format(float(movement.angle_for_show)))
        if near_target != previous_near:
            if yellow_low_hp_standoff:
                movement_state=(
                    "retreat" if lockon_retreating else "range_hold")
            else:
                movement_state=("orbit" if near_target else "approach")
            print(
                "[MEGA_MOVEMODE] {} angle={:.1f} marker_y={:.1f}".format(
                    movement_state,
                    float(movement.angle_for_show),
                    float(marker_position[1])))
        return True

    def ZA_mega_green_safe_floor_direction(self, frame=None):
        """画面下部の緑床について、足元到達状態と移動方向を返す。"""
        self._za_mega_green_floor_move_seconds=0.0
        self._za_mega_green_floor_distance_ratio=0.0
        if frame is None:
            camera=getattr(self, "camera", None)
            if camera is None:
                return False, None, 0.0
            if hasattr(camera, "readFreshFrame"):
                frame=camera.readFreshFrame(timeout=0.75)
            else:
                frame=(camera.readFrame()
                       if hasattr(camera, "readFrame") else None)
        if frame is None or getattr(frame, "size", 0) == 0:
            return False, None, 0.0

        height,width=frame.shape[:2]
        x0,x1=int(width * 0.05),int(width * 0.95)
        # 最終戦の安全床は遠方では画面上寄りに横長で現れる。
        # 従来の38%開始では見えている床を候補にできなかったため、
        # 上側まで探索し、下側UIは後段の形状・位置条件で除外する。
        y0,y1=int(height * 0.20),int(height * 0.96)
        region=frame[y0:y1, x0:x1]
        if region.size == 0:
            return False, None, 0.0
        hsv=cv2.cvtColor(region, cv2.COLOR_BGR2HSV)
        # 安全床は明るい黄緑～緑。暗い青緑の岩（H≈105/V≈60）は
        # 床ではないため、色相上限と明度下限の両方で除外する。
        hsv_green_mask=cv2.inRange(hsv, (25, 40, 80), (95, 255, 255))
        blue,green,red=cv2.split(region)
        green_dominant=(
            (green.astype("int16") >= red.astype("int16") + 12)
            & (green.astype("int16") >= blue.astype("int16") + 8)
            & (green >= 85))
        green_mask=cv2.bitwise_or(
            hsv_green_mask,
            (green_dominant.astype("uint8") * 255))
        kernel=cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5))
        green_mask=cv2.morphologyEx(
            green_mask, cv2.MORPH_OPEN, kernel)
        green_mask=cv2.morphologyEx(
            green_mask, cv2.MORPH_CLOSE, kernel)

        # カメラ原画では主人公の足元は画面中央付近。Commands録画の
        # 右側ログ表示でゲーム像が縮んだ座標を基準にしない。
        foot_x0=max(0, int(width * 0.42) - x0)
        foot_x1=min(region.shape[1], int(width * 0.60) - x0)
        foot_y0=max(0, int(height * 0.72) - y0)
        foot_y1=min(region.shape[0], int(height * 0.95) - y0)
        # 足元到達は輪郭整形前のHSVマスクを使う。床の境界ではOPEN処理で
        # 緑画素が約3割失われ、実際には床へ入っていても見逃していた。
        # HSVだけなら灰色床や暗い青緑を拾わず、左下UIの誤認も抑えられる。
        foot_mask=hsv_green_mask[foot_y0:foot_y1, foot_x0:foot_x1]
        foot_pixels=max(1, int(foot_mask.size))
        foot_ratio=float(cv2.countNonZero(foot_mask)) / foot_pixels
        # 緑文字・ゲージ・攻撃エフェクトの点在画素を床上と誤認しないよう、
        # 総量だけでなく連続した緑領域の大きさも確認する。
        foot_kernel=cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (7, 7))
        foot_floor_mask=cv2.morphologyEx(
            foot_mask, cv2.MORPH_OPEN, foot_kernel)
        foot_contours,_=cv2.findContours(
            foot_floor_mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        largest_foot_area=max(
            (float(cv2.contourArea(contour)) for contour in foot_contours),
            default=0.0)
        largest_foot_ratio=largest_foot_area / foot_pixels
        # 実際の床境界は足元領域の約1割を連続して占める。
        if foot_ratio >= 0.10 and largest_foot_ratio >= 0.07:
            return True, None, foot_ratio

        contours,_=cv2.findContours(
            green_mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        # 安全床はまとまった面積を持つ。従来の250pxでは左下UIや
        # 緑色の攻撃エフェクトまで候補になったため、画面比率で除外する。
        minimum_area=max(
            1800.0,
            float(region.shape[0] * region.shape[1]) * 0.006)
        # 最終戦の通常カメラにおける主人公の足元位置。画面中央を使うと
        # 右前方の床へ必要以上に横移動するため、実録画の表示位置へ合わせる。
        player_x=float(width) * 0.50
        player_y=float(height) * 0.88
        candidates=[]
        for contour in contours:
            area=float(cv2.contourArea(contour))
            if area < minimum_area:
                continue
            rect_x,rect_y,rect_w,rect_h=cv2.boundingRect(contour)
            if (rect_w < int(width * 0.05)
                    or rect_h < int(height * 0.025)
                    or float(rect_w) / max(1.0, float(rect_h)) < 1.2
                    or float(rect_w) / max(1.0, float(rect_h)) > 12.0):
                continue
            moments=cv2.moments(contour)
            if not moments.get("m00"):
                continue
            center_x=float(moments["m10"] / moments["m00"] + x0)
            center_y=float(moments["m01"] / moments["m00"] + y0)
            # 遠方の安全床も候補にする。探索領域の上端に貼り付く
            # 細い色ノイズだけをここで除外する。
            if center_y < float(height) * 0.22:
                continue
            # 画面最下部は手持ち／技UIの領域であり、緑床の探索対象外。
            if center_y > float(height) * 0.92:
                continue
            # 左下の出撃ポケモンHP枠を除外する。ただし接近した安全床も
            # 左下へ大きく広がるため、十分な面積と縦幅がある領域は残す。
            if (center_x < float(width) * 0.32
                    and center_y > float(height) * 0.70
                    and (rect_h < int(height * 0.12)
                         or area < float(region.shape[0] * region.shape[1]) * 0.02)):
                continue
            distance=math.hypot(center_x - player_x, center_y - player_y)
            candidates.append((area / (1.0 + distance * 0.5), center_x, center_y))
        if not candidates:
            return False, None, foot_ratio

        _,target_x,target_y=max(candidates, key=lambda item: item[0])
        delta_x=target_x - player_x
        delta_y=player_y - target_y
        angle=(math.degrees(math.atan2(delta_y, delta_x)) + 360.0) % 360.0
        # 継続追従ではなく、床中心までの画面上距離から1回分の移動時間を
        # 決める。最終戦の遠方床は従来係数では到達前に止まっていたため、
        # 最大強度のまま距離係数を上げ、3秒以内の1回移動で到達を狙う。
        # contour走査の最後の候補ではなく、実際に採用した床中心との
        # 距離から移動時間を決める。
        distance=math.hypot(delta_x, delta_y)
        distance_ratio=distance / max(1.0, float(height))
        self._za_mega_green_floor_distance_ratio=distance_ratio
        self._za_mega_green_floor_move_seconds=max(
            0.35, min(3.0, distance_ratio * 7.0))
        return False, Direction(Stick.LEFT, angle, 1.0), foot_ratio

    def ZA_mega_z_guard_update(
            self, dir1, dir2, dir3, dir4, wait_seconds=2.5,
            hold_until_disappears=False):
        """Z_Gaurd 1で緑床へ移動し、通常は2.5秒停止する。"""
        wait_seconds=max(0.0, float(wait_seconds))
        if not getattr(self, "_za_mega_z_guard_enabled", False):
            return False
        now=time.monotonic()
        hp75_initial_green=bool(
            getattr(self, "_za_mega_last_battle_mode", False)
            and getattr(self, "_za_mega_testmode1_enabled", False)
            and getattr(self, "_za_mega_testmode1_resume_hp", "") == "HP75"
            and getattr(self, "_za_mega_testmode1_phase", "")
            == "HP75_EXISTING"
            and getattr(self, "_za_mega_mode5_initial_phase_active", False)
            and not hold_until_disappears)
        hp75_green_angle=90.0
        if hp75_initial_green:
            settings_getter=getattr(
                self, "ZA_mega_mode5_testmode1_settings", None)
            if callable(settings_getter):
                hp75_green_angle=float(settings_getter()[
                    "HP75_INITIAL_GREEN_MOVE_ANGLE"])
            # HP75再開直後は緑床の画面位置に合わせて視点を回さず、
            # 現在画角のまま固定方向へ移動する。
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self.ZA_MOVE_SEE(action="END")
        on_green,direction,foot_ratio=(
            self.ZA_mega_green_safe_floor_direction())
        move_seconds=max(0.0, float(getattr(
            self, "_za_mega_green_floor_move_seconds", 0.0)))
        # 移動時間だけを増やすと、従来の2.2秒基準で近い床まで遠方扱いに
        # なってしまう。遠方破棄は画面上の実距離で判定し、移動幅と分離する。
        floor_distance_ratio=max(0.0, float(getattr(
            self, "_za_mega_green_floor_distance_ratio",
            move_seconds / 4.5)))
        if ((on_green or isinstance(direction, Direction))
                and not getattr(self, "_za_mega_z_guard_holding", False)):
            # 遠方として追跡を破棄する場合も、床を検知した時点で先に
            # mode 5探索保持と通常Rstickを止める。従来は遠方分岐が
            # 先にreturnし、復帰直後でも視点だけ回り続けていた。
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self.ZA_MOVE_SEE(action="END")
        # 最終戦は攻撃時間を優先する。画面距離から2.2秒を超える床だけを
        # 遠方とみなし、その床が消えるまで再追跡しない。
        if (getattr(self, "_za_mega_last_battle_mode", False)
                and not getattr(
                    self, "_za_mega_mode5_initial_phase_active", False)
                and not getattr(self, "_za_mega_z_guard_holding", False)
                and not on_green and isinstance(direction, Direction)
                and floor_distance_ratio > (2.2 / 4.5)):
            self._za_mega_z_guard_skip_current_floor=True
            self._za_mega_z_guard_skip_last_seen=now
            print(
                "[MEGA_Z_GUARD] skip distant floor "
                "duration={:.2f}s; prioritize attack".format(move_seconds))
            trace=getattr(self, "ZA_mega_mode5_trace", None)
            if callable(trace):
                trace(
                    "GREEN_FLOOR_TOO_FAR",
                    "skip floor and continue target attack")
            return False
        if getattr(self, "_za_mega_z_guard_skip_current_floor", False):
            if getattr(
                    self, "_za_mega_z_guard_normal_hold_completed", False):
                # 通常時の2.5秒待機後は、同じ床を再取得して
                # 停止ループに戻らない。床が消えたら次の候補を許可する。
                if on_green or isinstance(direction, Direction):
                    self._za_mega_z_guard_skip_last_seen=now
                    return False
                if now - float(getattr(
                        self, "_za_mega_z_guard_skip_last_seen", now)) < 0.6:
                    return False
                self._za_mega_z_guard_skip_current_floor=False
                self._za_mega_z_guard_skip_last_seen=0.0
                self._za_mega_z_guard_normal_hold_completed=False
                print(
                    "[MEGA_Z_GUARD] completed floor disappeared; "
                    "allow next floor")
            else:
                if on_green:
                    # 破棄中でも足元へ床が来た場合は通り越さず、通常の
                    # 床上確認へ戻す。
                    self._za_mega_z_guard_skip_current_floor=False
                    self._za_mega_z_guard_skip_last_seen=0.0
                    print("[MEGA_Z_GUARD] reached skipped floor; hold")
                else:
                    if isinstance(direction, Direction):
                        self._za_mega_z_guard_skip_last_seen=now
                        # 1回移動で届かなかった同じ床を繰り返し追わない。
                        # 敵追従・攻撃はこの周回から再開できる。
                        return False
                    if now - float(getattr(
                            self, "_za_mega_z_guard_skip_last_seen", now)) < 0.6:
                        return False
                    self._za_mega_z_guard_skip_current_floor=False
                    self._za_mega_z_guard_skip_last_seen=0.0
                    print("[MEGA_Z_GUARD] skipped floor disappeared; allow next floor")
        if (not getattr(self, "_za_mega_z_guard_holding", False)
                and not on_green and isinstance(direction, Direction)):
            # 最初の候補は右スティック停止直前の回転中フレームから
            # 算出されている。停止後の画面で方向を取り直さないと、
            # 実際の床位置と移動角度がずれるためfresh frameを再取得する。
            self.wait(0.1)
            settled_on_green,settled_direction,settled_foot_ratio=(
                self.ZA_mega_green_safe_floor_direction())
            if (not settled_on_green
                    and not isinstance(settled_direction, Direction)):
                print(
                    "[MEGA_Z_GUARD] floor candidate lost after view stop; "
                    "skip movement")
                return False
            on_green=settled_on_green
            direction=settled_direction
            foot_ratio=settled_foot_ratio
            # 視点停止後の再取得で距離も更新されるため、移動上限には
            # 停止前ではなく、この確定フレームの距離を使用する。
            move_seconds=max(0.0, float(getattr(
                self, "_za_mega_green_floor_move_seconds", move_seconds)))
            floor_distance_ratio=max(0.0, float(getattr(
                self, "_za_mega_green_floor_distance_ratio",
                floor_distance_ratio)))
            if (hp75_initial_green and not on_green
                    and isinstance(direction, Direction)):
                direction=Direction(
                    Stick.LEFT, hp75_green_angle, 1.0)
        if getattr(self, "_za_mega_z_guard_holding", False):
            # 一度でも緑床移動／床上待機へ入った後は、FIELDだけで
            # TESTMODE1障害物経路を再開しない。
            enter_legacy=getattr(
                self, "ZA_mega_mode5_testmode1_enter_legacy", None)
            if callable(enter_legacy):
                enter_legacy("GREEN_FLOOR")
            # 待機を続けるのは足元が緑の場合だけ。離れた場所に緑床が
            # 見えているだけで、移動を止め続けない。
            floor_visible=on_green
            if floor_visible:
                self._za_mega_z_guard_last_seen=now
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            if (floor_visible
                    and getattr(self, "_za_mega_last_battle_mode", False)):
                testmode1_green_latched=bool(
                    getattr(self, "_za_mega_testmode1_enabled", False)
                    and getattr(
                        self, "_za_mega_testmode1_legacy_until_reset", False))
                if hp75_initial_green or testmode1_green_latched:
                    # TESTMODE1を通常mode5へ切り替えた後も、
                    # 現在の緑床待機が終わるまで視点は固定する。
                    self.ZA_mega_mode5_marker_search_view_stop(relock=False)
                    self.ZA_MOVE_SEE(action="END")
                else:
                    # 通常時は左移動を止めたまま、右スティックだけで次の
                    # 赤／青・ターゲットマーカーを先に探してよい。
                    self.ZA_mega_mode5_marker_search_view()
            hold_until=float(getattr(
                self, "_za_mega_z_guard_hold_until", 0.0))
            if getattr(
                    self, "_za_mega_z_guard_hold_until_disappears", False):
                # 強い光の予兆中だけは、単一フレームのエフェクトで
                # 解除せず、緑床が0.6秒連続で消えるまで待機する。
                if (floor_visible or now - float(getattr(
                        self, "_za_mega_z_guard_last_seen", now)) < 0.6):
                    return True
            elif now < hold_until:
                return True
            self._za_mega_z_guard_holding=False
            self._za_mega_z_guard_active=False
            self._za_mega_z_guard_on_green_count=0
            self._za_mega_z_guard_direction=None
            self._za_mega_z_guard_direction_until=0.0
            if getattr(
                    self, "_za_mega_z_guard_hold_until_disappears", False):
                print("[MEGA_Z_GUARD] green floor disappeared; resume battle")
            else:
                # 通常時は床表示が残っても固定待機で必ず復帰する。
                # 同じ床が消えるまでは再追跡しない。
                self._za_mega_z_guard_normal_hold_completed=True
                self._za_mega_z_guard_skip_current_floor=True
                self._za_mega_z_guard_skip_last_seen=now
                print(
                    "[MEGA_Z_GUARD] post-move wait complete; "
                    "resume battle and ignore same floor")
            self._za_mega_z_guard_hold_until=0.0
            self._za_mega_z_guard_hold_until_disappears=False
            return False

        if on_green:
            # 単一フレームの緑エフェクトでは停止しない。連続2フレームで
            # 足元のまとまった緑領域を確認した場合だけ床上待機へ入る。
            # ただし1フレーム目でも旧方向を再送せず即時停止し、静止状態で
            # 2フレーム目を確認する。これにより床の通り越しを防ぐ。
            on_green_count=(
                int(getattr(self, "_za_mega_z_guard_on_green_count", 0)) + 1)
            self._za_mega_z_guard_on_green_count=on_green_count
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self._za_mega_z_guard_active=False
            self._za_mega_z_guard_direction=None
            self._za_mega_z_guard_direction_until=0.0
            if on_green_count < 2:
                print(
                    "[MEGA_Z_GUARD] green floor edge detected; brake and confirm")
                return True
            enter_legacy=getattr(
                self, "ZA_mega_mode5_testmode1_enter_legacy", None)
            if callable(enter_legacy):
                enter_legacy("GREEN_FLOOR")
            self._za_mega_z_guard_holding=True
            self._za_mega_z_guard_last_seen=now
            self._za_mega_z_guard_hold_until=(now + wait_seconds)
            self._za_mega_z_guard_hold_until_disappears=bool(
                hold_until_disappears)
            self._za_mega_z_guard_normal_hold_completed=False
            # 到達前の接近／周回方向を残すと、床消失後に古い0度系の
            # 入力を再利用する場合があるため、待機開始時に破棄する。
            self._za_mega_movemode_direction=None
            self._za_mega_movemode_direction_until=0.0
            self._za_mega_movemode_orbit_until=0.0
            print(
                "[MEGA_Z_GUARD] green floor reached ratio={:.3f}; {}".format(
                    foot_ratio,
                    ("hold until gone" if hold_until_disappears
                     else "hold {:.1f}s".format(wait_seconds))))
            return True
        self._za_mega_z_guard_on_green_count=0
        if isinstance(direction, Direction):
            # 確定した床方向へ動く直前にも、指定回転と探索保持の両方を
            # 明示的に停止する。緑床移動中は右スティックを再開しない。
            enter_legacy=getattr(
                self, "ZA_mega_mode5_testmode1_enter_legacy", None)
            if callable(enter_legacy):
                enter_legacy("GREEN_FLOOR")
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self.ZA_MOVE_SEE(action="END")
            print(
                "[MEGA_Z_GUARD] green floor found; one-shot move "
                "angle={:.1f} duration={:.2f}s strength=1.0{}".format(
                    float(direction.angle_for_show), move_seconds,
                    " HP75_FIXED_VIEW" if hp75_initial_green else ""))
            trace=getattr(self, "ZA_mega_mode5_trace", None)
            if callable(trace):
                trace(
                    "GREEN_FLOOR",
                    "stop view; {}move angle={:.1f} duration={:.2f}s".format(
                        "HP75 fixed-view " if hp75_initial_green else "continuous ",
                        float(direction.angle_for_show), move_seconds))
            # それまでの戦闘移動を緑床方向へ置換する。短いpressを繰り返すと
            # 区間ごとに中立へ戻って減速するため、移動中は強度1.0を保持し、
            # 方向だけを更新する。到達後は左スティックを必ず中立へ戻す。
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            # ロックオン中の横移動は遅いため、安全床への移動時だけZLを
            # 解除し、最大強度1.0の通常移動にする。
            if getattr(self, "ZL_state", 0) != 0:
                self.ZA_ZL_ACTION("END")
            move_limit=max(0.25, min(3.0, move_seconds))
            moved_seconds=0.0
            post_on_green=False
            post_direction=direction
            move_direction=direction
            post_ratio=foot_ratio
            missing_direction_checks=0
            while moved_seconds + 0.001 < move_limit:
                # 0.10秒ごとに床位置を取り直すが、左スティックは解除しない。
                # ZA_MOVE_LStickは同じStickの保持値を1パケットで置換する。
                self.ZA_MOVE_LStick(
                    dir1,dir2,dir3,dir4,
                    Direction(
                        Stick.LEFT,
                        move_direction.angle_for_show,
                        1.0),
                    "RELOAD",force_direction=True)
                step_seconds=max(
                    0.0, min(0.10, move_limit - moved_seconds))
                self.wait(step_seconds)
                moved_seconds+=step_seconds
                post_on_green,post_direction,post_ratio=(
                    self.ZA_mega_green_safe_floor_direction())
                if post_on_green:
                    break
                if isinstance(post_direction, Direction):
                    if not hp75_initial_green:
                        move_direction=post_direction
                    missing_direction_checks=0
                    continue
                # 移動中のブラーや攻撃エフェクトで床候補が消えても、
                # 最初に2フレーム確認した床までの距離予算は使い切る。
                # 上限は画面距離から算出済み（最大3秒）なので無制限にはならない。
                missing_direction_checks+=1
                if missing_direction_checks == 1:
                    print(
                        "[MEGA_Z_GUARD] floor temporarily missed; "
                        "keep strength=1.0 until move budget ends")
                continue
            # 緑床到達後／移動予算終了後は左移動を残さない。
            # 右スティック探索はこの停止対象に含めない。
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self._za_mega_z_guard_active=False
            self._za_mega_z_guard_direction=None
            self._za_mega_z_guard_direction_until=0.0
            if post_on_green:
                self._za_mega_z_guard_holding=True
                hold_started_at=time.monotonic()
                self._za_mega_z_guard_last_seen=hold_started_at
                self._za_mega_z_guard_hold_until=(
                    hold_started_at + wait_seconds)
                self._za_mega_z_guard_hold_until_disappears=bool(
                    hold_until_disappears)
                self._za_mega_z_guard_normal_hold_completed=False
                self._za_mega_z_guard_on_green_count=2
                self._za_mega_z_guard_skip_current_floor=False
                self._za_mega_z_guard_skip_last_seen=0.0
                self._za_mega_movemode_direction=None
                self._za_mega_movemode_direction_until=0.0
                self._za_mega_movemode_orbit_until=0.0
                print(
                    "[MEGA_Z_GUARD] one-shot move reached floor "
                    "ratio={:.3f}; {}".format(
                        post_ratio,
                        ("hold until gone" if hold_until_disappears
                         else "hold {:.1f}s".format(wait_seconds))))
                return True
            # 距離予算を使い切っても床が見えている場合だけ、同じ床を
            # 再追従し続けない。候補自体が消えた場合は次の床を許可する。
            # 床上判定を取りこぼしても、移動後は2〜3秒の
            # 停止を確実に入れる。停止後は同じ床を再追跡しない。
            hold_started_at=time.monotonic()
            self._za_mega_z_guard_holding=True
            self._za_mega_z_guard_last_seen=hold_started_at
            self._za_mega_z_guard_hold_until=(
                hold_started_at + wait_seconds)
            self._za_mega_z_guard_hold_until_disappears=bool(
                hold_until_disappears)
            self._za_mega_z_guard_normal_hold_completed=False
            self._za_mega_z_guard_on_green_count=0
            self._za_mega_z_guard_skip_current_floor=isinstance(
                post_direction, Direction)
            self._za_mega_z_guard_skip_last_seen=(
                time.monotonic()
                if self._za_mega_z_guard_skip_current_floor else 0.0)
            print(
                "[MEGA_Z_GUARD] one-shot move ended; "
                "hold {:.1f}s (moved={:.2f}/{:.2f}s candidate={})".format(
                    wait_seconds,
                    moved_seconds, move_limit,
                    isinstance(post_direction, Direction)))
            return True
        self._za_mega_z_guard_active=False
        self._za_mega_z_guard_direction=None
        self._za_mega_z_guard_direction_until=0.0
        return False

    def ZA_mega_relock_toward_marker(self,dir1,dir2,dir3,dir4,dodge_repeat=0,include_upper_marker=0):
        now = time.monotonic()
        if (now < getattr(
                self, "_za_mega_field_dir5_until", 0.0)
                and getattr(self, "_za_mega_dir5", -1) >= 0):
            # dir5開始移動中も、ロックオンし直して移動を途切れさせない。
            if dodge_repeat:
                self.pressRep(
                    Button.Y,
                    repeat=dodge_repeat,
                    duration=0.04,
                    wait=0.0,
                    interval=0.1)
            self.ZA_MOVE_LStick(
                dir1,dir2,dir3,dir4,5,"RELOAD")
            return
        if now < getattr(
                self, "_za_mega_field_dir4_until", 0.0):
            # 再開直後はZL解除・小幅補正・待機の反復を行わず、
            # 回避ボタンを保ったまdir4の連続移動を優先する。
            if dodge_repeat:
                self.pressRep(
                    Button.Y,
                    repeat=dodge_repeat,
                    duration=0.04,
                    wait=0.0,
                    interval=0.1)
            self.ZA_MOVE_LStick(
                dir1,dir2,dir3,dir4,4,"RELOAD")
            return
        if dodge_repeat:
            self.pressRep(
                Button.Y,
                repeat=dodge_repeat,
                duration=0.04,
                wait=0.0,
                interval=0.1)
        # 前回のマーカー補正が残っていても、先に通常移動へ戻す。
        resume_dirnum = self.ZA_mega_keep_left_moving(
            dir1,dir2,dir3,dir4)
        if now < getattr(self, "_za_mega_relock_retry_at", 0.0):
            return
        mode5_dynamic=bool(
            getattr(self, "_za_mega_last_battle_mode", False)
            and getattr(self, "_za_mega_movemode", 0) == 1)
        # 直接Lを送る経路は抑えているため、mode 5は2秒ごとに短時間だけ
        # 再取得を試し、ロックオンが外れたままの時間を長くしない。
        self._za_mega_relock_retry_at = now + (
            2.0 if mode5_dynamic else 1.0)
        marker_direction = self.ZA_mega_target_marker_direction(
            include_upper=bool(include_upper_marker))
        # mode 0～4は従来どおり、マーカー確認後に一度ZLを解除する。
        # mode 5だけは未検知探索中の非ロックオン時間を増やさない。
        if not mode5_dynamic:
            self.ZA_ZL_ACTION("END")
        if marker_direction:
            if mode5_dynamic:
                self.ZA_ZL_ACTION("END")
            self.ZA_MOVE_LStick(
                dir1,dir2,dir3,dir4,marker_direction,"RELOAD")
            # mode 5の非ロックオン時間を最短化する。
            self.wait(
                0.1 if mode5_dynamic else 0.2)
            # マーカー方向を保持したままLでその向きを画面中央へ合わせる。
            self.pressRep(
                Button.L,
                repeat=1,
                duration=0.04,
                wait=0.0,
                interval=0.1)
            self.ZA_ZL_ACTION("")
        else:
            if mode5_dynamic:
                self.ZA_mega_mode5_marker_search_view()
            else:
                # 通常modeの旧動作：短い解除間隔後にZLを再入力する。
                self.wait(0.1)
                self.ZA_ZL_ACTION("")
        self.ZA_MOVE_LStick(
            dir1,dir2,dir3,dir4,resume_dirnum,"RELOAD")

    def ZA_mega_nonfield_picture_confirmed(self,picture):
        # 戦闘中の一時的な誤検知で移動をENDしない。
        # 移動を保持したまま次フレーム側で再確認する。
        self.wait(0.05)
        return (
            not self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")
            and self.image_check(picture)
        )

    def ZA_mega_mode5_defeat_background_confirmed(
            self, threshold=0.985, force=False):
        """敗北画面を指定黒背景画像との直接画素比較で確認する。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                and not force):
            return True
        try:
            frame=read_command_frame(self)
        except RuntimeError:
            return False
        if frame is None or getattr(frame, "size", 0) == 0:
            return False
        template=getattr(self, "_za_mega_mode5_defeat_black_template", None)
        if template is None:
            serial_root=os.path.dirname(os.path.dirname(
                os.path.abspath(_image_detection.__file__)))
            template_path=os.path.join(
                serial_root, "Template", "ZA_Story", "Common",
                "za_black_back.png")
            template=cv2.imread(template_path, cv2.IMREAD_COLOR)
            if template is None:
                if not getattr(
                        self, "_za_mega_mode5_defeat_template_error_logged",
                        False):
                    print(
                        "[MEGA_MODE5_DEFEAT] za_black_back.png is missing: "
                        + template_path)
                    self._za_mega_mode5_defeat_template_error_logged=True
                return False
            self._za_mega_mode5_defeat_black_template=template
        height,width=template.shape[:2]
        if frame.shape[0] < height or frame.shape[1] < width:
            return False
        source=frame[0:height, 0:width]
        if source.shape[2] == 4:
            source=cv2.cvtColor(source, cv2.COLOR_BGRA2BGR)
        # 指定されたza_black_back.pngの画素そのものと直接比較する。
        # キャプチャのビデオレンジ黒（0ではなく16前後）を
        # 許容するため、RGB各差24以下の画素比率を一致度とする。
        difference=cv2.absdiff(source, template)
        black_mask=cv2.inRange(difference, (0, 0, 0), (24, 24, 24))
        score=(
            float(cv2.countNonZero(black_mask))
            / float(max(1, height * width)))
        matched=score >= float(threshold)
        self._za_mega_mode5_defeat_background_score=score
        # 画像検知モニター上で、専用の黒背景判定範囲も
        # 通常テンプレートと同様に確認できるよう赤枠を表示する。
        now=time.monotonic()
        if now >= float(getattr(
                self, "_za_mega_mode5_defeat_rect_retry_at", 0.0)):
            display_rectangle=getattr(self, "displayRectangle", None)
            if callable(display_rectangle):
                display_rectangle(
                    (0, 0), width, height,
                    "MEGA_MODE5_DEFEAT_BLACK_{:.6f}".format(now),
                    600, color=["red", "orange"], crop=[])
            self._za_mega_mode5_defeat_rect_retry_at=now + 0.30
        if matched and not getattr(
                self, "_za_mega_mode5_defeat_background_logged", False):
            print(
                "[MEGA_MODE5_DEFEAT] black background image confirmed "
                "score={:.6f}".format(score))
            self._za_mega_mode5_defeat_background_logged=True
            self._za_mega_mode5_defeat_background_rejected_logged=False
        elif (not matched and not getattr(
                self, "_za_mega_mode5_defeat_background_rejected_logged",
                False)):
            print(
                "[MEGA_MODE5_DEFEAT] reject candidate: template pixel ratio "
                "score={:.6f} threshold={:.6f}".format(
                    score, float(threshold)))
            self._za_mega_mode5_defeat_background_rejected_logged=True
            self._za_mega_mode5_defeat_background_logged=False
        return matched

    def ZA_mega_mode5_normal_black_comment_confirmed(self):
        """黒背景ではない通常の黒Commentを安定確認する。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return False
        picture="POKEMON_ZA_TEXT_BLACK_COMMENT"
        if not self.image_check(picture):
            return False
        if self.ZA_mega_mode5_defeat_background_confirmed():
            return False
        if self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"):
            return False
        self.wait(0.05)
        return (
            self.image_check(picture)
            and not self.ZA_mega_mode5_defeat_background_confirmed()
            and not self.image_check(
                "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"))

    def ZA_mega_mode5_normal_black_comment_advance(
            self, retry_seconds=0.30):
        """確認済みの通常黒CommentをAで送り、再戦状態は変更しない。"""
        now=time.monotonic()
        if now < float(getattr(
                self, "_za_mega_mode5_normal_comment_retry_at", 0.0)):
            return True
        self.pressRep(
            Button.A, repeat=1, duration=0.15,
            wait=0.2, interval=0.1)
        self._za_mega_mode5_normal_comment_retry_at=(
            now + max(0.1, float(retry_seconds)))
        self.ZA_mega_mode5_trace(
            "NORMAL_BLACK_COMMENT",
            "non-defeat background; advance comment with A",
            force=True)
        return True

    def ZA_mega_mode5_begin_rpush_field_wait(
            self, dir1, dir2, dir3, dir4, see_r):
        """RPush後は全入力を止め、FIELDだけを待つ専用状態へ入る。"""
        test_phase=str(getattr(
            self, "_za_mega_testmode1_phase", "COVER_ATTACK"))
        self._za_mega_mode5_rpush_resume_phase=test_phase
        self._za_mega_mode5_rpush_resume_red=bool(test_phase in {
            "WAIT_RED_COVER_DELAY", "MOVE_TO_RED_COVER",
            "FACE_RED", "RED_COVER_ATTACK",
        })
        # RPush前の無攻撃経過時間や、すでに成立したフリーランを
        # イベント演出の後へ持ち越さない。FIELD復帰後に0秒から計り直す。
        self.ZA_mega_mode5_attack_watchdog_reset()
        self._za_mega_mode5_defeat_sequence_active=False
        self._za_mega_mode5_defeat_background_since=0.0
        self._za_mega_mode5_defeat_prompt_logged=False
        self._za_mega_mode5_defeat_prompt_a_retry_at=0.0
        self._za_mega_mode5_defeat_candidate_picture=""
        self._za_mega_mode5_event_attack_wait_field=False
        self._za_mega_mode5_event_attack_pending_from_name_lockon=False
        self._za_mega_mode5_event_name_ui_missing_latched=False
        self._za_mega_mode5_event_name_ui_missing_clear_since=0.0
        self._za_mega_mode5_x_menu_b_attempts=0
        self._za_mega_mode5_last_name_no_hard_since=0.0
        self._za_mega_mode5_last_name_last_seen_at=0.0
        self._za_mega_mode5_field_wait_since=time.monotonic()
        self._za_mega_mode5_field_wait_context="RPUSH"
        self._za_mega_mode5_field_wait_timeout_logged=False
        side_cycle_reset=getattr(
            self, "ZA_mega_mode5_testmode1_side_cycle_reset", None)
        if callable(side_cycle_reset):
            side_cycle_reset(test_phase)
        if test_phase != "FREE_RUN":
            self._za_mega_mode5_free_run_active=False
        self._za_mega_mode5_rpush_wait_field=True
        self._za_mega_mode5_rpush_field_picture=""
        self._za_mega_mode5_rpush_field_candidate=""
        self._za_mega_mode5_rpush_field_confirmations=0
        self._za_mega_mode5_rpush_post_field_move_pending=False
        # RPush前に見えていた予兆状態をFIELD復帰後へ持ち越さない。
        # 強い光の実処理は、後段でもフリーラン中だけに限定する。
        self._za_mega_last_charge_state="IDLE"
        self._za_mega_last_charge_check_retry_at=0.0
        self._za_mega_last_charge_search_deadline=0.0
        self._za_mega_last_charge_cooldown_until=0.0
        self._za_mega_last_charge_skip_count=0
        self._za_mega_last_charge_attack_suspended=False
        self._za_mega_testmode1_red_premove_block_until=0.0
        self._za_mega_testmode1_red_premove_waiting_strong_light=False
        self._za_mega_rclick_dir3_until=0.0
        self._za_mega_field_dir5_until=0.0
        self._za_mega_field_dir4_until=0.0
        self._za_mega_mode5_battle_active=False
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_MOVE_SEE(action="END",in_see_r=see_r)
        self.ZA_ZL_ACTION("END")
        self.ZA_mega_mode5_trace(
            "RPUSH_FIELD_WAIT_START",
            "reset 300s watchdog; discard every detection/input until FIELD",
            force=True)

    def ZA_mega_mode5_rpush_field_wait_update(
            self, dir1, dir2, dir3, dir4, see_r):
        """RPush待機中はFIELD系3画像だけを確認する。"""
        if not getattr(self, "_za_mega_mode5_rpush_wait_field", False):
            return "inactive"
        self.checkIfAlive()
        field_picture=next((
            picture for picture in (
                "POKEMON_ZA_FIELD_W",
                "POKEMON_ZA_FIELD_BACK_W",
                "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK",
            ) if self.image_check(picture)), "")
        if field_picture:
            previous=str(getattr(
                self, "_za_mega_mode5_rpush_field_candidate", ""))
            confirmations=int(getattr(
                self, "_za_mega_mode5_rpush_field_confirmations", 0))
            if previous == field_picture:
                confirmations+=1
            else:
                self._za_mega_mode5_rpush_field_candidate=field_picture
                confirmations=1
            self._za_mega_mode5_rpush_field_confirmations=confirmations
            # 演出中のFIELD単発誤一致で専用待機を解除しない。同じFIELDを
            # 3周連続確認する間も、他画像を見ず全入力停止を維持する。
            if confirmations < 3:
                self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
                self.ZA_MOVE_SEE(action="END",in_see_r=see_r)
                self.ZA_ZL_ACTION("END")
                self.ZA_mega_mode5_trace(
                    "RPUSH_FIELD_CONFIRMING",
                    "{} stable check {}/3; keep every input stopped".format(
                        field_picture, confirmations))
                self.wait(0.1)
                return "waiting"
            self._za_mega_mode5_rpush_wait_field=False
            self._za_mega_mode5_rpush_field_picture=field_picture
            self._za_mega_mode5_rpush_field_candidate=""
            self._za_mega_mode5_rpush_field_confirmations=0
            self._za_mega_mode5_rpush_post_field_move_pending=True
            # FIELDへ実際に戻った時点を300秒時計の新しい起点とする。
            self.ZA_mega_mode5_attack_watchdog_reset()
            self.ZA_mega_mode5_trace(
                field_picture,
                "FIELD confirmed after RPush; resume next loop", force=True)
            return "field"
        self._za_mega_mode5_rpush_field_candidate=""
        self._za_mega_mode5_rpush_field_confirmations=0
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_MOVE_SEE(action="END",in_see_r=see_r)
        self.ZA_ZL_ACTION("END")
        self.ZA_mega_mode5_trace(
            "RPUSH_FIELD_WAIT",
            "ignore non-FIELD detections and keep all movement stopped")
        self.wait(0.1)
        return "waiting"

    def ZA_mega_mode5_rpush_post_field_move_update(
            self, dir1, dir2, dir3, dir4, see_r):
        """RPush後のFIELD復帰では障害物初期化をせず、敵側へ短く移動する。"""
        if not getattr(
                self, "_za_mega_mode5_rpush_post_field_move_pending", False):
            return False
        if (int(getattr(self, "_za_mega_mode5_start_flag", 0)) != 4
                or not getattr(
                    self, "_za_mega_mode5_battle_active", False)):
            return False
        settings=self.ZA_mega_mode5_testmode1_settings()
        red_side=bool(getattr(
            self, "_za_mega_mode5_rpush_resume_red", False))
        move_angle=float(settings[
            "RPUSH_FIELD_RED_MOVE_ANGLE" if red_side else
            "RPUSH_FIELD_BLUE_MOVE_ANGLE"])
        move_seconds=max(0.0, float(settings[
            "RPUSH_FIELD_MOVE_SECONDS"]))
        self._za_mega_mode5_rpush_post_field_move_pending=False
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        self.ZA_ZL_ACTION("END")
        self.press(
            Direction(Stick.LEFT, move_angle, 1.0),
            duration=move_seconds, wait=0.0)
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_mega_mode5_trace(
            ("RPUSH_FIELD_RED_MOVE" if red_side
             else "RPUSH_FIELD_BLUE_MOVE"),
            "move {:.0f}deg for {:.1f}s; skip face/L/cover restart".format(
                move_angle, move_seconds),
            force=True)
        return True

    def ZA_mega_mode5_defeat_background_prompt_confirmed(
            self, stable_seconds=None):
        """敗北黒背景を5秒連続確認し、Comment／SELECT許可をラッチする。"""
        if getattr(self, "_za_mega_mode5_defeat_sequence_active", False):
            return True
        if not self.ZA_mega_mode5_defeat_background_confirmed():
            self._za_mega_mode5_defeat_background_since=0.0
            self._za_mega_mode5_defeat_prompt_logged=False
            self._za_mega_mode5_defeat_prompt_a_retry_at=0.0
            return False
        settings=self.ZA_mega_mode5_testmode1_settings()
        configured_seconds=max(5.0, float(settings.get(
            "DEFEAT_BLACK_STABLE_SECONDS", 5.0)))
        required_seconds=(
            configured_seconds if stable_seconds is None else
            max(configured_seconds, float(stable_seconds)))
        now=time.monotonic()
        since=float(getattr(
            self, "_za_mega_mode5_defeat_background_since", 0.0))
        if since <= 0.0:
            self._za_mega_mode5_defeat_background_since=now
            return False
        ready=(now - since) >= required_seconds
        if ready and not getattr(
                self, "_za_mega_mode5_defeat_prompt_logged", False):
            print(
                "[MEGA_MODE5_DEFEAT] black background stable {:.1f}s; "
                "allow mode5 Comment/SELECT recovery".format(
                    required_seconds))
            self._za_mega_mode5_defeat_prompt_logged=True
        if ready:
            self._za_mega_mode5_defeat_sequence_active=True
        return ready

    def ZA_mega_mode5_defeat_prompt_advance(self, retry_seconds=0.80):
        """SELECT描画前の敗戦質問をAで送り、再戦選択肢を表示する。"""
        if not self.ZA_mega_mode5_defeat_background_prompt_confirmed(
                stable_seconds=0.0):
            return False
        now=time.monotonic()
        if now < float(getattr(
                self, "_za_mega_mode5_defeat_prompt_a_retry_at", 0.0)):
            return True
        self.pressRep(
            Button.A, repeat=1, duration=0.15,
            wait=0.2, interval=0.1)
        self._za_mega_mode5_defeat_prompt_a_retry_at=(
            now + max(0.1, float(retry_seconds)))
        self.ZA_mega_mode5_trace(
            "DEFEAT_BLACK_PROMPT",
            "stable black background; A to display retry SELECT",
            force=True)
        return True

    def ZA_mega_mode5_defeat_select_check(self, picture):
        """mode 5敗北時だけRPush除外前のSELECT生照合結果を使用する。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return self.image_check(picture)
        # za_black_back.pngを5秒連続確認する前はSELECT画像を照合しない。
        if not getattr(self, "_za_mega_mode5_defeat_sequence_active", False):
            return False
        raw_check=getattr(self, "_image_check_target", None)
        if callable(raw_check):
            return bool(raw_check(picture))
        return self.image_check(picture)

    def ZA_mega_mode5_defeat_ui_clear(self):
        """mode 5敗北SELECTを許可する非FIELD／非戦闘UIを確認する。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return True
        # mode5のSELECTは生照合を使うため、image_check_confirmation()
        # にあるFIELD／Lv除外が自動では適用されない。ここで
        # 同じ除外を明示し、戦闘／復帰画面を敗北SELECTにしない。
        return not any(self.image_check(picture) for picture in (
            "POKEMON_ZA_FIELD_W",
            "POKEMON_ZA_FIELD_BACK_W",
            "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK",
            "POKEMON_ZA_BATTLE_ACTIVE_LEVEL",
            "POKEMON_ZA_ESCAPE",
        ))

    def ZA_mega_mode5_rpush_prompt_confirmed(self):
        """mode 5の実RPushを敗北黒背景の誤一致と分離する。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or not self.image_check("POKEMON_ZA_R_push")):
            return False
        return not self.ZA_mega_mode5_defeat_background_confirmed()

    def ZA_mega_mode5_defeat_select_confirmed(self, picture):
        """5秒黒背景ラッチ後のSELECTを生照合＋UI不在で確定する。"""
        if (getattr(self, "_za_mega_last_battle_mode", False)
                and not getattr(
                    self, "_za_mega_mode5_defeat_sequence_active", False)):
            return False
        if not self.ZA_mega_mode5_defeat_select_check(picture):
            return False
        if not self.ZA_mega_mode5_defeat_ui_clear():
            return False
        self.wait(0.05)
        return (
            self.ZA_mega_mode5_defeat_select_check(picture)
            and self.ZA_mega_mode5_defeat_ui_clear()
            and getattr(
                self, "_za_mega_mode5_defeat_sequence_active", False))

    def ZA_mega_mode5_defeat_black_comment_confirmed(self):
        """5秒黒背景ラッチ後の黒CommentをUI不在で二重確認する。"""
        picture="POKEMON_ZA_TEXT_BLACK_COMMENT"
        if (not getattr(self, "_za_mega_mode5_defeat_sequence_active", False)
                or not self.ZA_mega_mode5_defeat_ui_clear()
                or not self.image_check(picture)):
            return False
        self.wait(0.05)
        return bool(
            getattr(self, "_za_mega_mode5_defeat_sequence_active", False)
            and self.ZA_mega_mode5_defeat_ui_clear()
            and self.image_check(picture))

    def ZA_mega_mode5_defeat_candidate_picture(self):
        """黒背景5秒と組になった黒Comment／敗戦SELECTだけを返す。"""
        if (not getattr(self, "_za_mega_mode5_defeat_sequence_active", False)
                or not self.ZA_mega_mode5_defeat_ui_clear()):
            return ""
        # 固定4技の各入力直前／直後に二重確認した候補は、次周回で
        # 画像が切り替わっても敗戦処理へ確実に引き渡す。
        latched=str(getattr(
            self, "_za_mega_mode5_defeat_candidate_picture", ""))
        if latched:
            return latched
        if self.ZA_mega_mode5_defeat_black_comment_confirmed():
            return "POKEMON_ZA_TEXT_BLACK_COMMENT"
        return next((
            picture for picture in (
                "POKEMON_ZA_3_SELECT_TUTORIAL",
                "POKEMON_ZA_3_SELECT",
                "POKEMON_ZA_4_SELECT",
            ) if self.ZA_mega_mode5_defeat_select_confirmed(picture)), "")

    def ZA_mega_mode5_defeat_event_name_recovery_ready(self):
        """残留した敗戦ラッチから最終イベントの名称確認へ退避できるか返す。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or not getattr(
                    self, "_za_mega_mode5_defeat_sequence_active", False)
                or getattr(
                    self, "_za_mega_mode5_event_attack_wait_field", False)):
            return False

        # 遅れて表示された実SELECT／黒Commentを必ず優先する。
        # 黒背景単独は敗戦確定ではないため、名称救済を阻止しない。
        if self.ZA_mega_mode5_defeat_candidate_picture():
            self._za_mega_mode5_last_name_no_hard_since=0.0
            self._za_mega_mode5_last_name_last_seen_at=0.0
            return False
        if getattr(
                self, "_za_mega_mode5_event_name_ui_missing_latched", False):
            self._za_mega_mode5_last_name_no_hard_since=0.0
            self._za_mega_mode5_last_name_last_seen_at=0.0
            return False
        if not self.image_check("POKEMON_ZA_LAST_BATTLE_NAME"):
            self._za_mega_mode5_last_name_no_hard_since=0.0
            self._za_mega_mode5_last_name_last_seen_at=0.0
            return False
        return True

    def ZA_mega_mode5_defeat_wait_update(self):
        """敗戦候補を確認する。黒背景単独では敗戦状態へ遷移しない。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return "none"
        if not self.ZA_mega_mode5_defeat_ui_clear():
            # FIELD／Lv／Escapeが一度でも戻った区間は、黒背景5秒の
            # 連続確認にも敗戦ラッチにも流用しない。
            self._za_mega_mode5_defeat_sequence_active=False
            self._za_mega_mode5_defeat_background_since=0.0
            self._za_mega_mode5_defeat_prompt_logged=False
            self._za_mega_mode5_defeat_prompt_a_retry_at=0.0
            self._za_mega_mode5_defeat_candidate_picture=""
            return "none"
        stable=self.ZA_mega_mode5_defeat_background_prompt_confirmed()
        confirming=bool(
            stable
            or getattr(self, "_za_mega_mode5_defeat_sequence_active", False)
            or float(getattr(
                self, "_za_mega_mode5_defeat_background_since", 0.0)) > 0.0)
        if not stable:
            return "confirming" if confirming else "none"
        candidate=self.ZA_mega_mode5_defeat_candidate_picture()
        if candidate:
            self._za_mega_mode5_defeat_candidate_picture=candidate
            return "defeat"
        # 黒背景を5秒確認できても、それだけでは敗戦にしない。
        # Aで質問を進め、黒CommentまたはSELECTが描画されるまで待つ。
        self.ZA_mega_mode5_defeat_prompt_advance()
        return "confirming"

    def ZA_mega_mode5_x_menu_b_recovery(
            self, max_attempts=20, before_recovery=None):
        """mode5 FIELD待機中のXメニューをB最大20回で閉じる。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return "none"
        if not self.image_check("POKEMON_ZA_X_MENU_OPEN"):
            self._za_mega_mode5_x_menu_b_attempts=0
            return "none"
        if callable(before_recovery):
            before_recovery()
        marker_stop=getattr(
            self, "ZA_mega_mode5_marker_search_view_stop", None)
        if callable(marker_stop):
            marker_stop(relock=False)
        view_stop=getattr(self, "ZA_MOVE_SEE", None)
        if callable(view_stop):
            view_stop(action="END")
        self.ZA_ZL_ACTION("END")
        attempt_limit=max(1, int(max_attempts))
        attempts=max(0, int(getattr(
            self, "_za_mega_mode5_x_menu_b_attempts", 0)))
        while (attempts < attempt_limit
                and self.image_check("POKEMON_ZA_X_MENU_OPEN")):
            self.checkIfAlive()
            self.pressRep(
                Button.B, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            attempts+=1
        menu_open=self.image_check("POKEMON_ZA_X_MENU_OPEN")
        self._za_mega_mode5_x_menu_b_attempts=(
            attempts if menu_open else 0)
        self.ZA_mega_mode5_trace(
            "X_MENU_FIELD_WAIT",
            "B {}/{}; {}".format(
                attempts, attempt_limit,
                "still open" if menu_open else "closed"),
            force=True)
        return "x_menu"

    def ZA_mega_mode5_field_wait_reset(self, clear_name=True):
        """3分FIELD欠落時計を、他のmode5時計と独立して初期化する。"""
        self._za_mega_mode5_field_wait_since=0.0
        self._za_mega_mode5_field_wait_context=""
        self._za_mega_mode5_field_wait_timeout_logged=False
        if clear_name:
            self._za_mega_mode5_last_name_no_hard_since=0.0
            self._za_mega_mode5_last_name_last_seen_at=0.0

    def ZA_mega_mode5_remember_recent_combat_phase(self):
        """名称イベントの誤待機前にいた青／赤／フリーランを保持する。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or not getattr(self, "_za_mega_testmode1_enabled", False)):
            return str(getattr(
                self, "_za_mega_mode5_recent_combat_phase", ""))
        phase=str(getattr(self, "_za_mega_testmode1_phase", ""))
        if (getattr(self, "_za_mega_mode5_free_run_active", False)
                and phase in {"FREE_RUN", "LEGACY_COMBAT", "EXISTING_CHARGE"}):
            phase="FREE_RUN"
        elif phase == "EXISTING_CHARGE":
            phase=str(getattr(
                self, "_za_mega_testmode1_phase_before_charge", ""))
        phase_aliases={
            "MOVE_TO_COVER": "COVER_ATTACK",
            "FACE_BLUE": "COVER_ATTACK",
            "WAIT_RED_COVER_DELAY": "RED_COVER_ATTACK",
            "MOVE_TO_RED_COVER": "RED_COVER_ATTACK",
            "FACE_RED": "RED_COVER_ATTACK",
        }
        phase=phase_aliases.get(phase, phase)
        if phase in {
                "COVER_ATTACK", "RED_COVER_ATTACK",
                "BLUE_CHASE_ATTACK", "FREE_RUN"}:
            self._za_mega_mode5_recent_combat_phase=phase
        return str(getattr(
            self, "_za_mega_mode5_recent_combat_phase", ""))

    def ZA_mega_mode5_event_name_ui_missing_update(self):
        """UIなし後は同じ名称表示での再ZLを抑止し、消失後だけ解除する。"""
        if not getattr(
                self, "_za_mega_mode5_event_name_ui_missing_latched", False):
            self._za_mega_mode5_event_name_ui_missing_clear_since=0.0
            return False
        if self.image_check("POKEMON_ZA_LAST_BATTLE_NAME"):
            self._za_mega_mode5_event_name_ui_missing_clear_since=0.0
            return True
        now=time.monotonic()
        since=float(getattr(
            self, "_za_mega_mode5_event_name_ui_missing_clear_since", 0.0))
        if since <= 0.0:
            self._za_mega_mode5_event_name_ui_missing_clear_since=now
            return True
        if now - since < 0.5:
            return True
        self._za_mega_mode5_event_name_ui_missing_latched=False
        self._za_mega_mode5_event_name_ui_missing_clear_since=0.0
        self._za_mega_mode5_event_lockon_retry_at=0.0
        self._za_mega_mode5_last_name_no_hard_since=0.0
        self._za_mega_mode5_last_name_last_seen_at=0.0
        self.ZA_mega_mode5_trace(
            "EVENT_NAME_CLEARED",
            "boss name disappeared; allow a future 5s name/ZL check",
            force=True)
        return False

    def ZA_mega_mode5_resume_recent_combat_after_event_ui_missing(
            self, dir1, dir2, dir3, dir4, see_r):
        """名称5秒後のZLで4技UIがなければ直前の戦闘処理へ戻す。"""
        # ZL直後に遅れて実SELECT／黒Commentが現れた場合は、復帰より
        # 敗戦処理を優先する。高負荷での1フレーム遅延も再確認する。
        candidate=self.ZA_mega_mode5_defeat_candidate_picture()
        if not candidate:
            self.wait(0.05)
            candidate=self.ZA_mega_mode5_defeat_candidate_picture()
        if candidate:
            self._za_mega_mode5_defeat_candidate_picture=candidate
            self.ZA_ZL_ACTION("END")
            return False

        recent=self.ZA_mega_mode5_remember_recent_combat_phase()
        if recent not in {
                "COVER_ATTACK", "RED_COVER_ATTACK",
                "BLUE_CHASE_ATTACK", "FREE_RUN"}:
            recent="FREE_RUN"
        self._za_mega_mode5_recent_combat_phase=recent

        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_MOVE_SEE(action="END",in_see_r=see_r)
        self.ZA_ZL_ACTION("END")
        self.ZA_mega_mode5_attack_watchdog_reset()
        self._za_mega_mode5_defeat_sequence_active=False
        self._za_mega_mode5_defeat_background_since=0.0
        self._za_mega_mode5_defeat_prompt_logged=False
        self._za_mega_mode5_defeat_prompt_a_retry_at=0.0
        self._za_mega_mode5_defeat_candidate_picture=""
        self._za_mega_mode5_event_attack_wait_field=False
        self._za_mega_mode5_event_attack_pending_from_name_lockon=False
        self._za_mega_mode5_event_name_ui_missing_latched=True
        self._za_mega_mode5_event_name_ui_missing_clear_since=0.0
        self._za_mega_mode5_event_lockon_retry_at=0.0
        self._za_mega_mode5_x_menu_b_attempts=0
        self.ZA_mega_mode5_field_wait_reset()
        self._za_mega_mode5_rpush_wait_field=False
        self._za_mega_mode5_rpush_field_picture=""
        self._za_mega_mode5_rpush_field_candidate=""
        self._za_mega_mode5_rpush_field_confirmations=0
        self._za_mega_mode5_rpush_post_field_move_pending=False
        self._za_mega_mode5_initial_phase_active=False
        self._za_mega_mode5_green_priority_checks_remaining=0
        self._za_mega_mode5_post_move_wait_until=0.0
        self._za_mega_mode5_lockon_confirmed_until=0.0
        self._za_mega_mode5_visual_lockon_until=0.0
        self._za_mega_mode5_state_lockon_logged=False
        self._za_mega_colored_enemy_track_position=None
        self._za_mega_colored_enemy_track_seen_at=0.0
        self._za_mega_colored_enemy_candidate_position=None
        self._za_mega_colored_enemy_candidate_color=None
        self._za_mega_colored_enemy_candidate_pixels=0.0
        self._za_mega_colored_enemy_candidate_seen_at=0.0
        self._za_mega_colored_enemy_candidate_hits=0
        self._za_mega_last_charge_state="IDLE"
        self._za_mega_last_charge_check_retry_at=0.0
        self._za_mega_last_charge_search_deadline=0.0
        self._za_mega_last_charge_cooldown_until=0.0
        self._za_mega_last_charge_skip_count=0
        self._za_mega_last_charge_attack_suspended=False
        self._za_mega_z_guard_active=False
        self._za_mega_z_guard_holding=False
        self._za_mega_z_guard_direction=None
        self._za_mega_z_guard_direction_until=0.0
        self._za_mega_testmode1_legacy_until_reset=False
        self._za_mega_testmode1_reinitialize_pending=False
        self._za_mega_testmode1_existing_charge_latched=False
        self._za_mega_testmode1_phase_before_charge=""
        self._za_mega_testmode1_red_premove_block_until=0.0
        self._za_mega_testmode1_red_premove_waiting_strong_light=False
        self._za_mega_mode5_battle_active=True

        if recent == "FREE_RUN":
            self.ZA_mega_mode5_testmode1_enter_free_run(
                "name 5s -> ZL, but fixed-four UI absent")
        else:
            self._za_mega_mode5_free_run_active=False
            self._za_mega_testmode1_phase=recent
            self._za_mega_testmode1_returned_to_blue=(
                recent == "BLUE_CHASE_ATTACK")
            self._za_mega_testmode1_premove_due=(recent in {
                "COVER_ATTACK", "RED_COVER_ATTACK"})
            self._za_mega_testmode1_next_dodge_at=0.0
            self.ZA_mega_mode5_testmode1_side_cycle_reset(recent)
            self.ZA_mega_mode5_transition(
                "TARGET_ATTACK",
                "fixed-four UI absent; resume recent {}".format(recent))
        self.ZA_mega_mode5_set_start_flag(
            4, "EVENT_ATTACK_UI_MISSING_AFTER_ZL",
            "resume recent {}; suppress ZL until boss name clears".format(
                recent))
        self.ZA_mega_mode5_trace(
            "EVENT_NAME_COMBAT_RESUME",
            "fixed-four UI absent after ZL; resume {}".format(recent),
            force=True)
        return True

    def ZA_mega_mode5_indefinite_field_wait_update(
            self, active, context, nofiled,
            dir1=0, dir2=0, dir3=0, dir4=0, see_r=0):
        """無期限FIELD待機へX／敗戦／3分イベント割込みを追加する。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or not active):
            return "inactive"

        stale_name_recovery=(
            self.ZA_mega_mode5_defeat_event_name_recovery_ready())
        event_picture=self.ZA_mega_mode5_event_attack_picture()
        if event_picture and not stale_name_recovery:
            self.ZA_mega_mode5_field_wait_reset()
            return event_picture

        before_recovery=lambda: self.ZA_MOVE_LStick(
            dir1,dir2,dir3,dir4,1,"END")
        x_menu_state=self.ZA_mega_mode5_x_menu_b_recovery(
            max_attempts=20, before_recovery=before_recovery)
        if x_menu_state != "none":
            return x_menu_state

        field_w=self.image_check("POKEMON_ZA_FIELD_W")
        field_back=self.image_check("POKEMON_ZA_FIELD_BACK_W")
        field_hard=self.image_check(
            "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")
        escape=self.image_check("POKEMON_ZA_ESCAPE")
        battle_level=self.image_check("POKEMON_ZA_BATTLE_ACTIVE_LEVEL")
        if field_w or field_back or field_hard or escape or battle_level:
            self.ZA_mega_mode5_field_wait_reset()
            return "none"

        # イベント導入の正規暗転で立った敗戦ラッチが、FIELDを挟まず
        # アンジュフラエッテ戦へ持ち越される場合がある。実SELECT／
        # 黒Commentがなければ、黒背景単独の一致にかかわらずラッチを保持し
        # 既存の名称5秒確認→ZL→4技UI再確認を優先する。名称確認中に
        # SELECTが遅れて出れば、次周で通常の敗戦処理へ戻る。
        if stale_name_recovery:
            event_result=self.ZA_mega_mode5_event_lockon_bootstrap(
                nofiled,
                resume_screen_detected=True,
                field_screen_detected=False,
                allow_missing_field_fallback=True,
                require_name_lockon=True)
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_MOVE_SEE(action="END",in_see_r=see_r)
            if event_result == "POKEMON_ZA_LAST_BATTLE_MOVE_UI":
                # 実入力直前／途中の遅延SELECTも止められるよう、敗戦
                # ラッチは最初の固有技入力が成功するまで維持する。
                self.ZA_mega_mode5_field_wait_reset()
                self.ZA_mega_mode5_trace(
                    "DEFEAT_EVENT_NAME_LOCKON",
                    "defeat SELECT absent; boss name 5s -> ZL move UI",
                    force=True)
                return event_result
            if event_result == "EVENT_ATTACK_UI_MISSING_AFTER_ZL":
                if self.ZA_mega_mode5_resume_recent_combat_after_event_ui_missing(
                        dir1,dir2,dir3,dir4,see_r):
                    return "resume_combat"
                return "waiting"
            if event_result != "WAIT_EVENT_ATTACK_UI":
                self.ZA_ZL_ACTION("END")
            self.ZA_mega_mode5_trace(
                "DEFEAT_EVENT_NAME_RECOVERY",
                "stale defeat latch; wait boss name 5s before ZL")
            return "waiting"

        defeat_state=self.ZA_mega_mode5_defeat_wait_update()
        if defeat_state == "defeat":
            self.ZA_mega_mode5_field_wait_reset()
            return "defeat"
        if defeat_state == "confirming":
            # 黒背景単独では敗戦へ移さないが、イベント時計も進めない。
            self._za_mega_mode5_field_wait_since=time.monotonic()
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_MOVE_SEE(action="END",in_see_r=see_r)
            self.ZA_ZL_ACTION("END")
            return "waiting"

        if getattr(
                self, "_za_mega_mode5_event_attack_wait_field", False):
            # 固有4技を入力済みなら、残った4技UIや180秒後の名称判定で
            # 再攻撃せず、敗戦後と同じくFIELD復帰だけを待つ。
            self._za_mega_mode5_field_wait_since=0.0
            self._za_mega_mode5_field_wait_context="EVENT_ATTACK_WAIT_FIELD"
            self._za_mega_mode5_field_wait_timeout_logged=False
            self._za_mega_mode5_last_name_no_hard_since=0.0
            self._za_mega_mode5_last_name_last_seen_at=0.0
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_MOVE_SEE(action="END",in_see_r=see_r)
            self.ZA_ZL_ACTION("END")
            self.ZA_mega_mode5_trace(
                "EVENT_ATTACK_WAIT_FIELD",
                "fixed four-move input complete; hold until FIELD retry")
            return "waiting"

        wait_context=str(context or "FIELD_WAIT")
        now=time.monotonic()
        previous_context=str(getattr(
            self, "_za_mega_mode5_field_wait_context", ""))
        since=float(getattr(
            self, "_za_mega_mode5_field_wait_since", 0.0))
        if previous_context != wait_context or since <= 0.0:
            self._za_mega_mode5_field_wait_context=wait_context
            self._za_mega_mode5_field_wait_since=now
            self._za_mega_mode5_field_wait_timeout_logged=False
            self._za_mega_mode5_last_name_no_hard_since=0.0
            self._za_mega_mode5_last_name_last_seen_at=0.0
            return "none"
        settings=self.ZA_mega_mode5_testmode1_settings()
        timeout_seconds=max(180.0, float(settings.get(
            "FIELD_WAIT_EVENT_TIMEOUT_SECONDS", 180.0)))
        if now - since < timeout_seconds:
            return "none"
        if not getattr(
                self, "_za_mega_mode5_field_wait_timeout_logged", False):
            self._za_mega_mode5_field_wait_timeout_logged=True
            self.ZA_mega_mode5_trace(
                "FIELD_WAIT_EVENT_TIMEOUT",
                "FIELD absent {:.1f}s; begin boss-name event check".format(
                    timeout_seconds),
                force=True)
        result=self.ZA_mega_mode5_event_lockon_bootstrap(
            nofiled,
            field_screen_detected=False,
            field_w_detected=False,
            field_back_w_detected=False,
            escape_detected=False,
            choice_input_guard=False,
            allow_missing_field_fallback=True)
        if result == "POKEMON_ZA_LAST_BATTLE_MOVE_UI":
            self.ZA_mega_mode5_field_wait_reset()
            return result
        if result == "EVENT_ATTACK_UI_MISSING_AFTER_ZL":
            if self.ZA_mega_mode5_resume_recent_combat_after_event_ui_missing(
                    dir1,dir2,dir3,dir4,see_r):
                return "resume_combat"
            return "waiting"
        if result in {
                "WAIT_LAST_BATTLE_NAME_5S", "WAIT_EVENT_ATTACK_UI",
                "DEFEAT_EVENT_LOCKON_ABORTED",
                "EVENT_ATTACK_BLOCKED_AFTER_ZL"}:
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_MOVE_SEE(action="END",in_see_r=see_r)
            return "waiting"
        return "none"

    def ZA_mega_last_battle_tutorial_confirmed(
            self, initial_wait=0.4, attempts=5, interval=0.2):
        # 汎用3_SELECTは選択画面の描画途中でも先に一致し得るため、
        # 専用テンプレートが安定するまで少し待って複数フレームを確認する。
        self.wait(initial_wait)
        attempts=max(1, int(attempts))
        for attempt in range(attempts):
            if (self.ZA_mega_mode5_defeat_select_check(
                    "POKEMON_ZA_3_SELECT_TUTORIAL")
                    and self.ZA_mega_mode5_defeat_ui_clear()
                    and getattr(
                        self, "_za_mega_mode5_defeat_sequence_active", False)
                    ):
                return True
            if attempt + 1 < attempts:
                self.wait(interval)
        return False

    def ZA_mega_red_screen_edge_check(
            self, frame=None, edge_fraction=0.08,
            side_red_ratio=0.06, total_red_ratio=0.04):
        """上下左右のうち2辺以上が赤いダメージ画面だけを検知する。"""
        if frame is None:
            camera = getattr(self, "camera", None)
            if camera is None:
                return False
            try:
                if hasattr(camera, "readFreshFrame"):
                    frame = camera.readFreshFrame(timeout=0.75)
                else:
                    frame = camera.readFrame() if hasattr(
                        camera, "readFrame") else None
            except RuntimeError:
                return False
        if (frame is None or getattr(frame, "size", 0) == 0
                or len(frame.shape) != 3):
            return False
        if frame.shape[2] == 4:
            frame = cv2.cvtColor(frame, cv2.COLOR_BGRA2BGR)
        elif frame.shape[2] != 3:
            return False

        height, width = frame.shape[:2]
        edge_y = max(1, min(height // 2, int(height * edge_fraction)))
        edge_x = max(1, min(width // 2, int(width * edge_fraction)))
        middle_top = edge_y
        middle_bottom = max(middle_top + 1, height - edge_y)
        edge_regions = (
            frame[:edge_y, :],
            frame[height - edge_y:, :],
            frame[middle_top:middle_bottom, :edge_x],
            frame[middle_top:middle_bottom, width - edge_x:],
        )
        red_pixels = 0
        edge_pixels = 0
        red_sides = 0
        for region in edge_regions:
            if region.size == 0:
                continue
            hsv = cv2.cvtColor(region, cv2.COLOR_BGR2HSV)
            red_mask = cv2.bitwise_or(
                cv2.inRange(hsv, (0, 90, 60), (15, 255, 255)),
                cv2.inRange(hsv, (165, 90, 60), (179, 255, 255)))
            region_pixels = int(region.shape[0] * region.shape[1])
            region_red_pixels = int(cv2.countNonZero(red_mask))
            edge_pixels += region_pixels
            red_pixels += region_red_pixels
            if (region_pixels > 0
                    and region_red_pixels / region_pixels >= side_red_ratio):
                red_sides += 1
        return (
            red_sides >= 2
            and edge_pixels > 0
            and red_pixels / edge_pixels >= total_red_ratio)

    def ZA_mega_red_edge_y_renda(
            self, seconds, endpicture="", end2picture="",
            repeat_count=0, interrupt_pictures=(),
            interrupt_check_interval=0.3,
            continuous_wait_seconds=0.1):
        """赤い画面端を避けるためYを送り、停止理由を返す。"""
        endpictures = tuple(
            picture for picture in (endpicture, end2picture) if picture)
        interrupt_pictures=tuple(
            picture for picture in interrupt_pictures if picture)
        interrupt_check_interval=max(
            0.1, float(interrupt_check_interval))
        continuous_wait_seconds=max(
            0.0, float(continuous_wait_seconds))
        next_interrupt_check=0.0

        def interrupt_result():
            nonlocal next_interrupt_check
            now=time.monotonic()
            if (not interrupt_pictures
                    or now < next_interrupt_check):
                return ""
            next_interrupt_check=now + interrupt_check_interval
            if any(self.image_check(picture)
                   for picture in interrupt_pictures):
                return "guard"
            return ""

        repeat_count=max(0, int(repeat_count))
        if continuous_wait_seconds <= 0.0:
            # 明示待機なしの赤枠／FIELD復帰後ローリングでは、画像検知を
            # 同期実行すると各Yの間に検知時間がそのまま入る。Y送信だけを
            # 専用threadで継続し、終了画像等は呼出元threadで監視する。
            import threading

            deadline=(
                time.monotonic() + max(0.0, float(seconds)))
            stop_sender=threading.Event()
            sender_done=threading.Event()
            sender_state={
                "count": 0, "error": None,
                "first_sent_at": 0.0, "last_sent_at": 0.0}

            def send_y_without_detection_gap():
                try:
                    while not stop_sender.is_set():
                        if repeat_count:
                            if sender_state["count"] >= repeat_count:
                                break
                        elif time.monotonic() >= deadline:
                            break
                        self.checkIfAlive()
                        sent_at=time.monotonic()
                        if sender_state["count"] == 0:
                            sender_state["first_sent_at"]=sent_at
                        sender_state["last_sent_at"]=sent_at
                        self.pressRep(
                            Button.Y, repeat=1, duration=0.04,
                            wait=0.0, interval=0.0)
                        sender_state["count"] += 1
                except BaseException as error:
                    sender_state["error"] = error
                finally:
                    # 停止要求がY押下中に入っても押下状態を残さない。
                    keys=getattr(self, "keys", None)
                    input_end=getattr(keys, "inputEnd", None)
                    if callable(input_end):
                        try:
                            input_end(Button.Y)
                        except Exception:
                            pass
                    sender_done.set()

            sender=threading.Thread(
                target=send_y_without_detection_gap,
                name="ZA-mega-Y-stream", daemon=True)
            sender.start()
            result="complete"
            try:
                while not sender_done.is_set():
                    self.checkIfAlive()
                    if any(self.image_check(picture)
                           for picture in endpictures):
                        result="endpicture"
                        break
                    if sender_done.is_set():
                        break
                    interrupted=interrupt_result()
                    if interrupted:
                        result=interrupted
                        break
                    if sender_done.is_set():
                        break
                    if self.ZA_mega_choice_input_guard():
                        result="guard"
                        break
                    if sender_done.is_set():
                        break
                    if self.ZA_mega_field_attack_only_suppress_y_dodge():
                        result="attack_only"
                        break
            finally:
                stop_sender.set()
                sender.join(timeout=1.0)
            if sender.is_alive():
                raise RuntimeError(
                    "Y連続送信threadを停止できません。")
            if sender_state["error"] is not None:
                raise sender_state["error"]
            sent_count=sender_state["count"]
            average_interval=0.0
            if sent_count > 1:
                average_interval=(
                    sender_state["last_sent_at"]
                    - sender_state["first_sent_at"]
                ) / (sent_count - 1)
            print(
                "[MEGA_Y_STREAM] result={} count={} "
                "average_start_interval={:.4f}s".format(
                    result, sent_count, average_interval))
            return result

        if repeat_count:
            for repeat_index in range(repeat_count):
                self.checkIfAlive()
                if any(self.image_check(picture) for picture in endpictures):
                    return "endpicture"
                interrupted=interrupt_result()
                if interrupted:
                    return interrupted
                if self.ZA_mega_choice_input_guard():
                    return "guard"
                if self.ZA_mega_field_attack_only_suppress_y_dodge():
                    return "attack_only"
                self.pressRep(
                    Button.Y, repeat=1, duration=0.04,
                    wait=0.0, interval=0.05)
                if (repeat_index + 1 < repeat_count
                        and continuous_wait_seconds > 0.0):
                    self.wait(continuous_wait_seconds)
            return "complete"
        deadline = time.monotonic() + max(0.0, float(seconds))
        while time.monotonic() < deadline:
            self.checkIfAlive()
            if any(self.image_check(picture) for picture in endpictures):
                return "endpicture"
            interrupted=interrupt_result()
            if interrupted:
                return interrupted
            if self.ZA_mega_choice_input_guard():
                return "guard"
            if self.ZA_mega_field_attack_only_suppress_y_dodge():
                return "attack_only"
            self.pressRep(
                Button.Y, repeat=1, duration=0.04,
                wait=0.0, interval=0.05)
            if continuous_wait_seconds > 0.0:
                self.wait(min(
                    continuous_wait_seconds,
                    max(0.0, deadline - time.monotonic())))
        return "complete"

    def ZA_mega_last_battle_charge_dodge(
            self, dir1, dir2, dir3, dir4, see_r,
            endpicture="", end2picture="", seconds=3.0, reason="timeout"):
        """最終戦の強い光を、非ロックオンY連打で回避する。"""
        seconds=max(0.0, float(seconds))
        if reason == "green_too_far":
            # 遠い緑床は即座に破棄し、強い光の発動全体を
            # 覆えるよう非ロックオンY回避を7秒維持する。
            seconds=7.0
        self._za_mega_last_charge_state="DODGE"
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        self.ZA_ZL_ACTION("END")
        print(
            "[MEGA_CHARGE] {}: no reachable green floor; "
            "unlock and Y rolling for {:.1f}s".format(reason, seconds))
        self.ZA_mega_mode5_trace(
            "STRONG_LIGHT_" + str(reason).upper(),
            "no reachable green floor; non-lockon Y for {:.1f}s".format(
                seconds),
            force=True)
        result=self.ZA_mega_red_edge_y_renda(
            seconds, endpicture=endpicture, end2picture=end2picture)
        if result == "complete":
            # 旧移動方向は再送しない。ZLだけ戻し、次周期のmode 5探索で
            # 新しい敵方向を取得する。
            self.ZA_ZL_ACTION("")
            self._za_mega_last_charge_state="COOLDOWN"
            self._za_mega_last_charge_cooldown_until=(
                time.monotonic() + 5.0)
            self.ZA_mega_mode5_trace(
                "STRONG_LIGHT_DODGE_COMPLETE",
                "relock; wait for warning notices to disappear",
                force=True)
            return "dodge"
        self._za_mega_last_charge_state="IDLE"
        self._za_mega_last_charge_search_deadline=0.0
        return result

    def ZA_mega_last_battle_charge_update(
            self, dir1, dir2, dir3, dir4, see_r,
            endpicture="", end2picture="", active=True,
            search_seconds=3.5, near_move_seconds=1.35,
            dodge_seconds=3.0):
        """最終戦の溜め通知後、近い緑床またはY回避を選択する。"""
        if (not active
                or not getattr(self, "_za_mega_last_battle_mode", False)
                or not getattr(self, "_za_mega_z_guard_enabled", False)):
            if not active:
                self._za_mega_last_charge_state="IDLE"
                self._za_mega_last_charge_search_deadline=0.0
            return "none"

        now=time.monotonic()

        def block_red_attack_premove(reason, strong_light=False):
            phase=str(getattr(
                self, "_za_mega_testmode1_phase", ""))
            waiting_strong_light=bool(getattr(
                self,
                "_za_mega_testmode1_red_premove_waiting_strong_light",
                False))
            if (not getattr(self, "_za_mega_testmode1_enabled", False)
                    or (phase not in {
                        "MOVE_TO_COVER", "FACE_BLUE", "COVER_ATTACK",
                        "MOVE_TO_RED_COVER", "FACE_RED",
                        "RED_COVER_ATTACK"}
                        and not waiting_strong_light)):
                return
            settings_getter=getattr(
                self, "ZA_mega_mode5_testmode1_settings", None)
            settings=(settings_getter()
                      if callable(settings_getter) else {})
            block_seconds=max(0.0, float(settings.get(
                "RED_ATTACK_PREMOVE_BLOCK_SECONDS", 7.0)))
            if strong_light:
                # 強い光の表示中に再開しないよう、最後に確認した時点から
                # 指定秒数まで青側／赤側共通の攻撃前移動を止める。
                self._za_mega_testmode1_red_premove_waiting_strong_light=False
                self._za_mega_testmode1_red_premove_block_until=max(
                    float(getattr(
                        self,
                        "_za_mega_testmode1_red_premove_block_until", 0.0)),
                    time.monotonic() + block_seconds)
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_RED_PREMOVE_BLOCK",
                    "{}; keep blue/red 270deg pre-attack move stopped for {:.1f}s".format(
                        reason, block_seconds))
            else:
                # CHARGEとSTRONG_LIGHTの間が5秒を超えても再開しない。
                # STRONG_LIGHTを確認して初めて上の5秒タイマーへ切り替える。
                self._za_mega_testmode1_red_premove_waiting_strong_light=True
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_RED_PREMOVE_BLOCK",
                    "{}; stop blue/red 270deg pre-attack move until strong light + {:.1f}s".format(
                        reason, block_seconds))

        state=str(getattr(
            self, "_za_mega_last_charge_state", "IDLE"))
        if state == "SKIP_WAIT_CLEAR":
            if now < float(getattr(
                    self, "_za_mega_last_charge_check_retry_at", 0.0)):
                return "skip"
            charge_still_visible=self.image_check(
                "POKEMON_ZA_LAST_BATTLE_CHARGE")
            strong_light_still_visible=False
            if not charge_still_visible:
                strong_light_still_visible=self.image_check(
                    "POKEMON_ZA_LAST_BATTLE_STRONG_LIGHT")
            warning_still_visible=(
                charge_still_visible or strong_light_still_visible)
            self._za_mega_last_charge_check_retry_at=now + 0.5
            if warning_still_visible:
                # 同じ表示を複数回の予兆として数えない。
                warning_name=(
                    "STRONG_LIGHT" if strong_light_still_visible
                    else "CHARGE")
                self.ZA_mega_mode5_testmode1_warning_cycle_update(
                    warning_name)
                block_red_attack_premove(
                    ("strong light" if strong_light_still_visible
                     else "charge warning"),
                    strong_light=strong_light_still_visible)
                return "skip"
            self._za_mega_last_charge_state="IDLE"
            self.ZA_mega_mode5_testmode1_warning_cycle_update("CLEAR")
            return "none"
        if (getattr(
                self, "_za_mega_last_charge_attack_suspended", False)
                and state in {"IDLE", "COOLDOWN"}):
            # 受理した予兆の回避完了後も、FIELD再開処理が状態を
            # リセットするまでは通常攻撃とTESTMODE1ローリングへ戻さない。
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
            return "guard"
        if state == "COOLDOWN":
            if now < float(getattr(
                    self, "_za_mega_last_charge_cooldown_until", 0.0)):
                return "none"
            # 同じ通知が残る間は再発動しない。両通知が消えたことを
            # 確認してから次の即死攻撃予兆を受け付ける。
            if (self.image_check("POKEMON_ZA_LAST_BATTLE_CHARGE")
                    or self.image_check(
                        "POKEMON_ZA_LAST_BATTLE_STRONG_LIGHT")):
                self._za_mega_last_charge_cooldown_until=now + 1.0
                return "none"
            self._za_mega_last_charge_state="IDLE"
            state="IDLE"

        if state == "GREEN":
            if (getattr(self, "_za_mega_testmode1_enabled", False)
                    and not getattr(
                        self, "_za_mega_testmode1_legacy_until_reset", False)):
                # 予兆後の緑床処理中は、別経路でphaseが書き戻されても
                # 障害物用の定期Yローリングへ絶対に戻さない。
                self._za_mega_testmode1_existing_charge_latched=True
                self._za_mega_testmode1_phase="EXISTING_CHARGE"
            if self.ZA_mega_z_guard_update(
                    dir1,dir2,dir3,dir4,
                    hold_until_disappears=True):
                return "green"
            self._za_mega_last_charge_state="COOLDOWN"
            self._za_mega_last_charge_cooldown_until=now + 5.0
            self.ZA_mega_mode5_trace(
                "CHARGE_GREEN_COMPLETE",
                "green floor disappeared; resume battle",
                force=True)
            return "complete"

        if state == "IDLE":
            if now < float(getattr(
                    self, "_za_mega_last_charge_check_retry_at", 0.0)):
                return "none"
            charge_detected=self.image_check(
                "POKEMON_ZA_LAST_BATTLE_CHARGE")
            strong_light_detected=False
            if not charge_detected:
                # 最初の通知を取りこぼしても、発動通知から直接Y回避へ
                # 入れるようにする。
                strong_light_detected=self.image_check(
                    "POKEMON_ZA_LAST_BATTLE_STRONG_LIGHT")
            self._za_mega_last_charge_check_retry_at=(
                time.monotonic() + 0.5)
            if charge_detected or strong_light_detected:
                warning_name=(
                    "STRONG_LIGHT" if strong_light_detected else "CHARGE")
                self.ZA_mega_mode5_testmode1_warning_cycle_update(
                    warning_name)
                block_red_attack_premove(
                    "strong light" if strong_light_detected
                    else "charge warning",
                    strong_light=strong_light_detected)
                skip_limit=0
                if getattr(self, "_za_mega_testmode1_enabled", False):
                    settings_getter=getattr(
                        self, "ZA_mega_mode5_testmode1_settings", None)
                    if callable(settings_getter):
                        skip_limit=int(settings_getter().get(
                            "CHARGE_WARNING_SKIP_COUNT", -1))
                testmode1_phase=str(getattr(
                    self, "_za_mega_testmode1_phase", ""))
                if (skip_limit < 0
                        and testmode1_phase not in {
                            "FREE_RUN", "LEGACY_COMBAT"}):
                    # -1は予兆をTESTMODE1終了条件にしない。表示が残る間の
                    # 重複判定だけ抑止する。赤色の直接確認、または予兆
                    # セット間の青不在による赤側障害物移行を待つ。
                    self._za_mega_last_charge_state="SKIP_WAIT_CLEAR"
                    self.ZA_mega_mode5_trace(
                        "CHARGE_WARNING_RED_ONLY_WAIT",
                        "{} ignored; wait for red-only/warning fallback".format(
                            warning_name),
                        force=True)
                    return "skip"
                if skip_limit < 0:
                    # 赤のみ確認後は既存mode5なので、既存の予兆／緑床処理を
                    # 無効化せず、0回スキップとして扱う。
                    skip_limit=0
                skip_count=max(0, int(getattr(
                    self, "_za_mega_last_charge_skip_count", 0)))
                if skip_count < skip_limit:
                    skip_count+=1
                    self._za_mega_last_charge_skip_count=skip_count
                    self._za_mega_last_charge_state="SKIP_WAIT_CLEAR"
                    self.ZA_mega_mode5_trace(
                        "CHARGE_WARNING_SKIPPED",
                        "{} event skipped {}/{}; keep attack controls".format(
                            warning_name, skip_count, skip_limit),
                        force=True)
                    return "skip"
                # 3回目以降の予兆を受理した時点から、再開判定までは
                # 通常攻撃とTESTMODE1の定期Yローリングを停止する。
                self._za_mega_last_charge_attack_suspended=True
                if (getattr(self, "_za_mega_testmode1_enabled", False)
                        and not getattr(
                            self, "_za_mega_testmode1_legacy_until_reset",
                            False)):
                    phase_before_charge=str(getattr(
                        self, "_za_mega_testmode1_phase", "COVER_ATTACK"))
                    if phase_before_charge in {
                            "COVER_ATTACK", "RED_COVER_ATTACK", "FREE_RUN"}:
                        self._za_mega_testmode1_phase_before_charge=(
                            phase_before_charge)
                    self._za_mega_testmode1_existing_charge_latched=True
                    self._za_mega_testmode1_phase="EXISTING_CHARGE"
            if strong_light_detected:
                return self.ZA_mega_last_battle_charge_dodge(
                    dir1,dir2,dir3,dir4,see_r,
                    endpicture=endpicture, end2picture=end2picture,
                    seconds=dodge_seconds,
                    reason="strong_light_without_charge")
            if not charge_detected:
                return "none"

            self._za_mega_last_charge_state="SEARCH_GREEN"
            self._za_mega_last_charge_search_deadline=(
                time.monotonic() + max(0.1, float(search_seconds)))
            self._za_mega_z_guard_skip_current_floor=False
            self._za_mega_z_guard_skip_last_seen=0.0
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
            print(
                "[MEGA_CHARGE] charge warning detected; "
                "search nearby green floor for {:.1f}s".format(
                    search_seconds))
            self.ZA_mega_mode5_trace(
                "POKEMON_ZA_LAST_BATTLE_CHARGE",
                "stop attack/move; search nearby green floor",
                force=True)
            state="SEARCH_GREEN"

        if state != "SEARCH_GREEN":
            return "none"

        # 右視点を止めたfresh frameで床距離を調べる。近い床だけを
        # 通常の緑床処理へ渡し、遠い床へ走って間に合わない場合は
        # 強い光を待たずY回避へ切り替える。
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        on_green,direction,_=(self.ZA_mega_green_safe_floor_direction())
        move_seconds=max(0.0, float(getattr(
            self, "_za_mega_green_floor_move_seconds", 0.0)))
        if (on_green or (isinstance(direction, Direction)
                         and move_seconds <= float(near_move_seconds))):
            self._za_mega_z_guard_skip_current_floor=False
            self._za_mega_z_guard_skip_last_seen=0.0
            if self.ZA_mega_z_guard_update(
                    dir1,dir2,dir3,dir4,
                    hold_until_disappears=True):
                self._za_mega_last_charge_state="GREEN"
                self.ZA_mega_mode5_transition(
                    "GREEN_HOLD" if getattr(
                        self, "_za_mega_z_guard_holding", False)
                    else "GREEN_MOVE",
                    "charge warning; nearby green floor selected")
                self.ZA_mega_mode5_trace(
                    "CHARGE_NEAR_GREEN",
                    "move to green floor before strong light",
                    force=True)
                return "green"
        elif isinstance(direction, Direction):
            return self.ZA_mega_last_battle_charge_dodge(
                dir1,dir2,dir3,dir4,see_r,
                endpicture=endpicture, end2picture=end2picture,
                seconds=dodge_seconds, reason="green_too_far")

        strong_light_detected=self.image_check(
            "POKEMON_ZA_LAST_BATTLE_STRONG_LIGHT")
        if strong_light_detected:
            block_red_attack_premove(
                "strong light", strong_light=True)
        if (strong_light_detected
                or time.monotonic() >= float(getattr(
                    self, "_za_mega_last_charge_search_deadline", now))):
            return self.ZA_mega_last_battle_charge_dodge(
                dir1,dir2,dir3,dir4,see_r,
                endpicture=endpicture, end2picture=end2picture,
                seconds=dodge_seconds,
                reason=("strong_light" if strong_light_detected
                        else "green_search_timeout"))

        # すぐ見つからない場合は同じ方向への短い右視点パルスだけを
        # 行い、次周期の停止画面で再び床を探す。時間で左右反転しない。
        search_angle=float(getattr(
            self, "_za_mega_marker_search_direction", 180.0))
        if search_angle not in (0.0, 180.0):
            search_angle=180.0
        # 強い力の予兆中は通常探索より少し早く見渡す。
        # 判定は次周の視点停止後fresh frameで行うため、
        # 回転中のぶれを緑床として確定しない。
        search_strength=max(0.55, min(0.68, float(getattr(
            self, "_za_mega_marker_search_strength", 0.24)) * 2.4))
        self.press(
            Direction(Stick.RIGHT, search_angle, search_strength),
            duration=0.12, wait=0.1)
        self.ZA_mega_mode5_trace(
            "CHARGE_GREEN_MISSING",
            "right-stick scan angle={:.0f}; keep searching".format(
                search_angle))
        return "search"

    def ZA_mega_red_edge_dodge_if_needed(
            self, seconds, dir1, dir2, dir3, dir4, see_r,
            endpicture="", end2picture="", active=True,
            repeat_count=0, forced_roll_angle=-1.0,
            repeat_while_active=False, keep_view_rotating=False,
            relock_each_roll=False,
            relock_each_roll_view_seconds=0.0,
            relock_each_roll_view_strength=1.0):
        """赤端を確認し、ZL解除中にY回避してから戦闘入力を復帰する。"""
        if seconds <= 0.0 or not active:
            if not active:
                self._za_mega_red_edge_latched = False
            return "none"
        if not self.ZA_mega_red_screen_edge_check():
            self._za_mega_red_edge_latched = False
            return "none"
        if self.ZA_mega_field_attack_only_suppress_y_dodge():
            # 実際に赤端がある場合もFIELD復帰後の抑止区間を優先し、
            # ZLと攻撃処理を維持したままY回避だけを抑止する。
            self.ZA_mega_field_attack_only_update(
                dir1, dir2, dir3, dir4)
            return "attack_only"
        cover_guard=getattr(
            self, "ZA_mega_mode5_testmode1_controls_cover", None)
        testmode1_cover=bool(
            callable(cover_guard) and cover_guard())
        if (getattr(self, "_za_mega_last_battle_mode", False)
                and getattr(self, "_za_mega_z_guard_enabled", False)
                and not testmode1_cover
                and self.ZA_mega_z_guard_update(
                    dir1, dir2, dir3, dir4)):
            # 赤端と緑床が同時に見える場合は、ロックオン解除Yよりも
            # 安全床への移動／床上停止を優先する。赤ラッチは立てず、
            # 床処理終了後も赤端が残る場合だけ次周期で回避できる。
            print(
                "[MEGA_RED_EDGE] green floor has priority; skip Y dodge")
            trace=getattr(self, "ZA_mega_mode5_trace", None)
            if callable(trace):
                trace(
                    "RED_DAMAGE_AND_GREEN_FLOOR",
                    "continue green-floor action; skip non-lockon Y")
            return "green_priority"
        if (getattr(self, "_za_mega_red_edge_latched", False)
                and not repeat_while_active):
            return "latched"

        self._za_mega_red_edge_latched = True
        if relock_each_roll:
            # mode 10は「ZL解除→Y→短時間の視点回転→ZLパルス」を
            # 1セットとし、赤端時は指定秒数だけ反復する。
            deadline=time.monotonic() + max(0.0, float(seconds))
            view_seconds=max(
                0.0, float(relock_each_roll_view_seconds))
            view_strength=max(
                0.0, min(1.0, float(relock_each_roll_view_strength)))
            endpictures=tuple(
                picture for picture in (endpicture, end2picture) if picture)
            result="complete"
            self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
            print(
                "[MEGA_MODE10_RED_EDGE_ROLL] "
                "repeat unlock/Y/relock sets for {:.1f}s".format(seconds))
            while time.monotonic() < deadline:
                self.checkIfAlive()
                if any(self.image_check(picture)
                       for picture in endpictures):
                    result="endpicture"
                    break
                if self.ZA_mega_choice_input_guard():
                    result="guard"
                    break
                if self.ZA_mega_field_attack_only_suppress_y_dodge():
                    result="attack_only"
                    break
                self.ZA_ZL_ACTION("END")
                self.wait(0.04)
                self.press(Button.Y, duration=0.04, wait=0.0)
                if view_seconds > 0.0 and view_strength > 0.0:
                    self.ZA_MOVE_SEE(
                        action="", in_see_r=view_strength)
                    self.wait(view_seconds)
                    self.ZA_MOVE_SEE(
                        action="END", in_see_r=view_strength)
                self.wait(0.04)
                self.ZA_ZL_ACTION("")
                self.wait(0.1)
                self.ZA_ZL_ACTION("END")
            if result == "complete":
                self.ZA_mega_keep_left_moving(dir1,dir2,dir3,dir4)
                self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
            return result
        # Yローリング中に相手方向へ吸われないよう、入力前にZLを外す。
        self.ZA_ZL_ACTION("END")
        # mode 3/7はローリングを優先したまま通常の右視点回転を続ける。
        # その他のmodeは従来どおり視点を停止して回避する。
        self.ZA_MOVE_SEE(
            action=("" if keep_view_rotating else "END"),
            in_see_r=see_r)
        forced_roll_angle=float(forced_roll_angle)
        if forced_roll_angle >= 0.0:
            # mode 4は黄色HP回避と同じ20度・最大強度を維持する。
            self.ZA_MOVE_LStick(
                dir1,dir2,dir3,dir4,
                Direction(Stick.LEFT, forced_roll_angle, 1.0),
                "RELOAD", force_direction=True)
        elif testmode1_cover:
            # 障害物待機中の赤端回避は、非ロックオンYを障害物方向へ送る。
            self.ZA_MOVE_LStick(
                dir1,dir2,dir3,dir4,
                Direction(Stick.LEFT, 90.0, 1.0),
                "RELOAD", force_direction=True)
        if repeat_count:
            print(
                "[MEGA_RED_EDGE] unlock and Y rolling x{}".format(
                    int(repeat_count)))
        else:
            print(
                "[MEGA_RED_EDGE] unlock and Y rolling for {:.1f}s".format(
                    seconds))
        while True:
            result = self.ZA_mega_red_edge_y_renda(
                seconds, endpicture=endpicture, end2picture=end2picture,
                repeat_count=repeat_count,
                continuous_wait_seconds=0.0)
            if result != "complete" or not repeat_while_active:
                break
            if not self.ZA_mega_red_screen_edge_check():
                break
            # mode 2は赤端が残る間に攻撃へ復帰すると敗北につながるため、
            # 15秒単位の非ロックオンY回避を切れ目なく継続する。
            print(
                "[MEGA_RED_EDGE] red edge remains; continue Y rolling")
        if result == "attack_only":
            # FIELD復帰前に開始した長いY連打も、dir5移動開始時点で
            # 中断する。ロックオンを戻し、左移動の時刻制御は変えず攻撃へ戻る。
            self._za_mega_red_edge_latched=False
            self.ZA_mega_field_attack_only_update(
                dir1, dir2, dir3, dir4)
            self.ZA_ZL_ACTION("")
            self.ZA_MOVE_SEE(action="", in_see_r=see_r)
            return result
        if result == "complete":
            # 回避完了後はロックオン、保持移動、視点処理の順に復帰する。
            self.ZA_ZL_ACTION("")
            if testmode1_cover:
                self.ZA_MOVE_LStick(
                    dir1,dir2,dir3,dir4,1,"END")
                self._za_mega_testmode1_next_dodge_at=(
                    time.monotonic() + 2.4)
            else:
                self.ZA_mega_keep_left_moving(dir1,dir2,dir3,dir4)
            self.ZA_MOVE_SEE(
                action=("END" if getattr(
                    self, "_za_mega_movemode", 0) == 1 else ""),
                in_see_r=see_r)
        return result

    def ZA_mega_normal_choice_black_background_reset(self):
        """通常MEGA戦の黒背景確認状態を破棄する。"""
        self._za_mega_normal_choice_black_background_since=0.0
        self._za_mega_normal_choice_black_background_state="none"
        self._za_mega_normal_choice_black_background_retry_at=0.0
        self._za_mega_normal_choice_black_background_logged=False

    def ZA_mega_normal_choice_black_background_state(
            self, stable_seconds=5.0):
        """通常MEGA戦で黒背景を5秒確認してComment／SELECTを許可する。"""
        if not getattr(
                self, "_za_mega_normal_choice_black_background_required",
                False):
            return "disabled"

        now=time.monotonic()
        retry_at=float(getattr(
            self, "_za_mega_normal_choice_black_background_retry_at", 0.0))
        if now < retry_at:
            return str(getattr(
                self, "_za_mega_normal_choice_black_background_state",
                "none"))

        # mode 5と同じく、FIELD／戦闘UIが見える画面は敗北黒背景として
        # 引き継がない。5秒成立後もFIELD復帰で必ずラッチを解除する。
        ui_visible=any(self.image_check(picture) for picture in (
            "POKEMON_ZA_FIELD_W",
            "POKEMON_ZA_FIELD_BACK_W",
            "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK",
            "POKEMON_ZA_BATTLE_ACTIVE_LEVEL",
            "POKEMON_ZA_ESCAPE",
        ))
        if ui_visible:
            self.ZA_mega_normal_choice_black_background_reset()
            self._za_mega_normal_choice_black_background_retry_at=now + 0.10
            return "none"

        state=str(getattr(
            self, "_za_mega_normal_choice_black_background_state", "none"))
        if state == "ready":
            # SELECT描画で黒背景画像が変化しても、FIELDへ戻るまでは
            # 直前に成立した黒背景ラッチを維持する。
            self._za_mega_normal_choice_black_background_retry_at=now + 0.10
            return "ready"

        if not self.ZA_mega_mode5_defeat_background_confirmed(force=True):
            self._za_mega_normal_choice_black_background_since=0.0
            self._za_mega_normal_choice_black_background_state="none"
            self._za_mega_normal_choice_black_background_logged=False
            self._za_mega_normal_choice_black_background_retry_at=now + 0.10
            return "none"

        required_seconds=max(5.0, float(stable_seconds))
        since=float(getattr(
            self, "_za_mega_normal_choice_black_background_since", 0.0))
        if since <= 0.0:
            self._za_mega_normal_choice_black_background_since=now
            state="confirming"
        elif now - since >= required_seconds:
            state="ready"
            if not getattr(
                    self,
                    "_za_mega_normal_choice_black_background_logged", False):
                print(
                    "[MEGA_NORMAL_DEFEAT] black background stable "
                    "{:.1f}s; allow Comment/SELECT".format(
                        required_seconds))
                self._za_mega_normal_choice_black_background_logged=True
        else:
            state="confirming"
        self._za_mega_normal_choice_black_background_state=state
        self._za_mega_normal_choice_black_background_retry_at=now + 0.10
        return state

    def ZA_mega_choice_input_guard(self):
        # 最終戦モードでは通常の2体／3体選択を3体／4体選択へ読み替える。
        mode5=bool(getattr(self, "_za_mega_last_battle_mode", False))
        if mode5:
            # 黒背景だけではRETRY_SELECTIONへ入らない。5秒黒背景と
            # 黒Comment／敗戦SELECTのANDが成立した場合だけ入力を許可する。
            return self.ZA_mega_mode5_defeat_wait_update() == "defeat"
        select_pictures = (
            "POKEMON_ZA_2_SELECT", "POKEMON_ZA_3_SELECT")
        # FIELD表示中は選択肢テンプレートの残像／誤一致を無効化する。
        # 復帰直後にSELECT側へ入ると、緑床確認と上入力が数秒遅れる。
        if self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"):
            if getattr(
                    self, "_za_mega_normal_choice_black_background_required",
                    False):
                self.ZA_mega_normal_choice_black_background_reset()
            return False
        if getattr(
                self, "_za_mega_normal_choice_black_background_required",
                False):
            # mode 3では2/3 SELECTだけを黒背景5秒成立後に許可する。
            # 黒Commentは背景がなくても会話送りできるよう独立して止める。
            background_state=(
                self.ZA_mega_normal_choice_black_background_state())
            black_comment=self.image_check(
                "POKEMON_ZA_TEXT_BLACK_COMMENT")
            guarded=(
                background_state in {"confirming", "ready"}
                or black_comment)
            if guarded:
                self._za_mega_lockon_unchecked_a_pending=True
            return guarded
        select_check=self.image_check
        select_matched_picture=next((
            picture for picture in select_pictures
            if select_check(picture)), "")
        select_matched=bool(select_matched_picture)
        black_comment=(
            False if select_matched
            else self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"))
        if not select_matched and not black_comment:
            return False
        self._za_mega_mode5_color_field_until=0.0
        self._za_mega_lockon_unchecked_a_pending=True
        return True

    def ZA_mega_mode5_lockon_ready(self, refresh=False):
        """mode 5でZL保持と画像または戦闘状態によるロックオンを確認する。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or int(getattr(
                    self, "_za_mega_mode5_start_flag", 0)) != 4
                or getattr(self, "ZL_state", 0) != 1):
            return False
        now=time.monotonic()
        if now < float(getattr(
                self, "_za_mega_mode5_lockon_confirmed_until", 0.0)):
            return True
        # 最終戦ではC+／EYE画像が攻撃演出と白背景で大きく変化する。
        # FIELD_W/BACK_Wから戦闘開始済みで、こちらがZLを保持し、
        # 右スティック探索中でもない区間はゲーム状態による補助判定とする。
        # 選択画面・敗北画面ではbattle_activeを先に解除するためY回避にはならない。
        if (getattr(self, "_za_mega_mode5_battle_active", False)
                and not getattr(
                    self, "_za_mega_marker_search_view_holding", False)):
            self._za_mega_mode5_lockon_confirmed_until=now + 0.45
            if not getattr(
                    self, "_za_mega_mode5_state_lockon_logged", False):
                print(
                    "[MEGA_LOCKON] use active battle + ZL state fallback")
                self._za_mega_mode5_state_lockon_logged=True
            return True
        if not refresh:
            return False
        # EYE表示は既存のZLロックオン確認用画像。どちらも外れた場合だけ
        # 色補助ではない実ターゲットマーカーを再確認する。
        if (self.image_check("POKEMON_ZA_EYE_CHECK")
                or self.image_check("POKEMON_ZA_EYE_CHECK_HIGH")):
            self._za_mega_mode5_lockon_confirmed_until=now + 0.8
            self._za_mega_mode5_visual_lockon_until=now + 0.8
            self._za_mega_mode5_state_lockon_logged=False
            return True
        marker_direction=self.ZA_mega_target_marker_direction()
        if (isinstance(marker_direction, Direction)
                and not getattr(self, "_za_mega_target_from_color", False)):
            self._za_mega_mode5_lockon_confirmed_until=now + 0.8
            self._za_mega_mode5_visual_lockon_until=now + 0.8
            self._za_mega_mode5_state_lockon_logged=False
            return True
        return False

    def ZA_mega_mode5_a_attack_ready(self, choice_guard_checked=False):
        """mode 5でA攻撃を送ってよい戦闘画面だけを確認する。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or int(getattr(
                    self, "_za_mega_mode5_start_flag", 0)) != 4
                or not getattr(self, "_za_mega_mode5_battle_active", False)):
            self._za_mega_mode5_color_field_until=0.0
            return False

        # FIELDと同時に背景が残る場合があるため、選択肢・コメントを先に
        # 除外する。これらと暗転中は、AだけでなくC+用PLUSも送らない。
        blocked_pictures = [
            "POKEMON_ZA_TEXT_WHITE_COMMENT",
            "POKEMON_ZA_TEXT_GREEN_COMMENT",
        ]
        if any(self.image_check(picture) for picture in blocked_pictures):
            if not getattr(
                    self, "_za_mega_mode5_a_block_logged", False):
                print(
                    "[MEGA_A_ONLY] block A/PLUS on comment or selection")
                self._za_mega_mode5_a_block_logged=True
            self._za_mega_mode5_color_field_until=0.0
            return False
        defeat_blocker=""
        if not choice_guard_checked:
            defeat_select_check=getattr(
                self, "ZA_mega_mode5_defeat_select_check", self.image_check)
            defeat_blocker=(
                "POKEMON_ZA_TEXT_BLACK_COMMENT"
                if self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")
                else next((
                    picture for picture in (
                        "POKEMON_ZA_3_SELECT_TUTORIAL",
                        "POKEMON_ZA_3_SELECT",
                        "POKEMON_ZA_4_SELECT",
                    ) if defeat_select_check(picture)), ""))
            background_check=getattr(
                self, "ZA_mega_mode5_defeat_background_confirmed", None)
            if (defeat_blocker
                    and defeat_blocker != "POKEMON_ZA_TEXT_BLACK_COMMENT"
                    and callable(background_check)
                    and not background_check()):
                defeat_blocker=""
        if defeat_blocker:
            if not getattr(
                    self, "_za_mega_mode5_a_block_logged", False):
                print(
                    "[MEGA_A_ONLY] block A/PLUS on confirmed defeat screen")
                self._za_mega_mode5_a_block_logged=True
            self._za_mega_mode5_color_field_until=0.0
            return False

        field_pictures = (
            # 最新録画ではBATTLE=0.943でもFIELD_W/BACK_Wが0.8未満となり、
            # 実戦闘中のAが40秒中1回まで落ちていた。選択肢／Commentを
            # 上で除外済みなので、BATTLEも安全な攻撃画面として使用する。
            "POKEMON_ZA_BATTLE",
            "POKEMON_ZA_FIELD_W",
            "POKEMON_ZA_FIELD_BACK_W",
            "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK",
        )
        if not any(self.image_check(picture) for picture in field_pictures):
            if not getattr(
                    self, "_za_mega_mode5_a_block_logged", False):
                print("[MEGA_A_ONLY] block A/PLUS without FIELD")
                self._za_mega_mode5_a_block_logged=True
            self._za_mega_mode5_color_field_until=0.0
            return False
        self._za_mega_mode5_a_block_logged=False
        # 赤青補助はこのFIELD確認から1.5秒だけ許可する。画面が会話・
        # 暗転・演出へ変わった後に古い色追従を持ち越さない。
        self._za_mega_mode5_color_field_until=time.monotonic() + 1.5
        return True

    def ZA_mega_mode5_skill_attack_ready(self):
        """mode 5でB/X/Yを技として送れるC+表示を確認する。"""
        if (not getattr(self, "_za_mega_last_battle_mode", False)
                or int(getattr(
                    self, "_za_mega_mode5_start_flag", 0)) != 4
                or not getattr(self, "_za_mega_mode5_battle_active", False)
                or getattr(self, "ZL_state", 0) != 1):
            return False
        now=time.monotonic()
        if now < float(getattr(
                self, "_za_mega_mode5_skill_ready_until", 0.0)):
            return True
        if (self.image_check("POKEMON_ZA_C+")
                or self.image_check("POKEMON_ZA_C+_LOW")):
            self._za_mega_mode5_skill_ready_until=now + 0.25
            self._za_mega_mode5_lockon_confirmed_until=now + 0.5
            self._za_mega_mode5_visual_lockon_until=now + 0.5
            self.ZA_mega_mode5_trace(
                "POKEMON_ZA_C+/C+_LOW",
                "allow B/X/Y skill attack")
            return True
        return False

    def ZA_mega_attack_ready(self):
        # 最終戦の戦闘状態フォールバックはテンプレート照合より先に使う。
        # C+／C+_LOWを毎技2回ずつ確認する待ちをなくし、攻撃区間を増やす。
        # PLUS入力自体は各技の直前に従来どおり送信する。
        if self.ZA_mega_mode5_lockon_ready(refresh=False):
            if not getattr(
                    self, "_za_mega_mode5_attack_fallback_logged", False):
                print(
                    "[MEGA_ATTACK_READY] use active battle lockon state")
                self._za_mega_mode5_attack_fallback_logged=True
            return True
        # 通常閾値を優先し、取りこぼした場合だけ0.60のLOWを確認する。
        if (self.image_check("POKEMON_ZA_C+")
                or self.image_check("POKEMON_ZA_C+_LOW")):
            self._za_mega_mode5_attack_fallback_logged=False
            return True
        # mode 5だけはC+画像を一時的に外しても、ZL保持に加えて
        # 戦闘状態、EYEまたは実マーカーで攻撃可能状態を補完する。
        if self.ZA_mega_mode5_lockon_ready(refresh=True):
            if not getattr(
                    self, "_za_mega_mode5_attack_fallback_logged", False):
                print(
                    "[MEGA_ATTACK_READY] C+ missed; "
                    "use lockon fallback")
                self._za_mega_mode5_attack_fallback_logged=True
            return True
        self._za_mega_mode5_attack_fallback_logged=False
        return False

    def ZA_mega_a_attack_ready(self, choice_guard_checked=False):
        """C+画像を取れない時も、安全な戦闘FIELDならA攻撃を許可する。"""
        if getattr(self, "_za_mega_last_battle_mode", False):
            return self.ZA_mega_mode5_a_attack_ready(
                choice_guard_checked=choice_guard_checked)
        if self.ZA_mega_attack_ready():
            return True
        # 通常MEGA戦ではC+画像欠落時のフォールバックをAだけへ限定する。
        # B/X/YまでFIELDだけで送ると、非ロックオン時の回避入力になり得る。
        if (choice_guard_checked
                or not self.ZA_mega_choice_input_guard()):
            if self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"):
                print("[MEGA_A] C+ missed; use FIELD-confirmed A fallback")
                return True
        return False

    def ZA_mega_mode5_y_attack_ready(self):
        """mode 5のYを非ロックオン時のローリングにしない。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return True
        ready=self.ZA_mega_mode5_lockon_ready(refresh=True)
        if ready:
            self._za_mega_mode5_y_skip_logged=False
            return True
        if not getattr(self, "_za_mega_mode5_y_skip_logged", False):
            print("[MEGA_Y] skip Y; lockon not confirmed")
            self._za_mega_mode5_y_skip_logged=True
        return False

    def ZA_mega_mode5_field_w_up_retry(
            self, field_w_detected, field_back_w_detected,
            max_attempts=5, interval=0.3, before_recovery=None):
        """mode 5だけ、FIELD_BACK_Wになるまで上入力を間欠再送する。

        上入力を上限まで送ってもFIELD_Wが残る場合は、ポケモンを
        出せないゲーム側状態をXメニューの開閉で解除して再試行する。
        """
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return False
        if field_back_w_detected:
            attempts=int(getattr(
                self, "_za_mega_field_w_up_attempts", 0))
            if attempts:
                print(
                    "[MEGA_FIELD_W] FIELD_BACK_W detected; "
                    "stop up retry after {}/{}".format(
                        attempts, max(1, int(max_attempts))))
            self._za_mega_field_w_up_attempts=0
            self._za_mega_field_w_up_retry_at=0.0
            self._za_mega_field_w_up_latched=False
            return False
        if not field_w_detected:
            return False

        attempts=int(getattr(
            self, "_za_mega_field_w_up_attempts", 0))
        attempt_limit=max(1, int(max_attempts))
        now=time.monotonic()
        if now < float(getattr(
                self, "_za_mega_field_w_up_retry_at", 0.0)):
            return False
        if attempts >= attempt_limit:
            menu_open=self.image_check("POKEMON_ZA_X_MENU_OPEN")
            if not menu_open:
                # FIELDの背後へ選択肢が残る場合もあるため、共通guardの
                # FIELD優先短絡を使わず、危険画面を直接除外する。
                blocked_pictures=(
                    "POKEMON_ZA_TEXT_WHITE_COMMENT",
                    "POKEMON_ZA_TEXT_GREEN_COMMENT",
                    "POKEMON_ZA_TEXT_BLACK_COMMENT",
                    "POKEMON_ZA_3_SELECT_TUTORIAL",
                    "POKEMON_ZA_3_SELECT",
                    "POKEMON_ZA_4_SELECT",
                )
                if any(self.image_check(picture)
                       for picture in blocked_pictures):
                    print(
                        "[MEGA_FIELD_W_RECOVERY] blocked by comment/selection; "
                        "do not press X/B")
                    return False

            if callable(before_recovery):
                before_recovery()
            marker_stop=getattr(
                self, "ZA_mega_mode5_marker_search_view_stop", None)
            if callable(marker_stop):
                marker_stop(relock=False)
            view_stop=getattr(self, "ZA_MOVE_SEE", None)
            if callable(view_stop):
                view_stop(action="END")
            self.ZA_ZL_ACTION("END")

            if not menu_open:
                print(
                    "[MEGA_FIELD_W_RECOVERY] FIELD_W remained after "
                    "{}/{} up attempts; open X menu".format(
                        attempts, attempt_limit))
                self.pressRep(
                    Button.X, repeat=1, duration=0.15,
                    wait=0.5, interval=0.1)
                # 高負荷中のメニュー描画を待ち、表示を確認してからだけ
                # Bを送る。Xが欠落した場合に戦闘中のB入力へしない。
                for _ in range(10):
                    if self.image_check("POKEMON_ZA_X_MENU_OPEN"):
                        menu_open=True
                        break
                    alive_check=getattr(self, "checkIfAlive", None)
                    if callable(alive_check):
                        alive_check()
                    self.wait(0.1)

            if menu_open:
                # 共通のFIELD欠落復旧と同じ上限で閉じる。連続検知中に
                # outer loopから再び呼ばれても20回を超えてBを送らない。
                self._za_mega_mode5_x_menu_b_attempts=0
                self.ZA_mega_mode5_x_menu_b_recovery(
                    max_attempts=20, before_recovery=None)
                menu_open=self.image_check("POKEMON_ZA_X_MENU_OPEN")

            self._za_mega_field_w_up_attempts=0
            self._za_mega_field_w_up_retry_at=0.0
            self._za_mega_field_w_up_latched=False
            self._za_mega_mode5_battle_active=False
            self.ZA_mega_mode5_transition(
                "FIELD_W_INPUT",
                "FIELD_W stuck; X menu recovery complete")
            self.ZA_mega_mode5_set_start_flag(
                3, "FIELD_W_X_MENU_RECOVERY",
                "retry Lbutton_up after X menu open/close")
            if not menu_open:
                print(
                    "[MEGA_FIELD_W_RECOVERY] X menu {} ; "
                    "reset up retry".format("closed"))
            else:
                print(
                    "[MEGA_FIELD_W_RECOVERY] X menu still detected after "
                    "B x20; reset up retry without further B")
            trace=getattr(self, "ZA_mega_mode5_trace", None)
            if callable(trace):
                trace(
                    "FIELD_W_X_MENU_RECOVERY",
                    "X menu open/close; retry Lbutton_up",
                    force=True)
            return "menu_recovery"
        # 0.04秒では最終戦の高負荷中に方向入力を取りこぼす実録画がある。
        # 押下時間だけ0.10秒へ延ばし、再送間隔は従来どおり0.3秒以上にする。
        self.etc_sendCommand("Lbutton_up", wait=0.10)
        # 生コマンドの解放行で途切れたZL・左スティックを復元する。
        self.keys.input([])
        attempts+=1
        self._za_mega_field_w_up_attempts=attempts
        self._za_mega_field_w_up_retry_at=(
            now + max(0.1, float(interval)))
        self._za_mega_field_w_up_latched=True
        print(
            "[MEGA_FIELD_W] Lbutton_up retry {}/{}; "
            "restore held inputs".format(attempts, attempt_limit))
        trace=getattr(self, "ZA_mega_mode5_trace", None)
        if callable(trace):
            trace(
                "POKEMON_ZA_FIELD_W",
                "Lbutton_up retry {}/{}".format(attempts, attempt_limit))
        return True

    def ZA_mega_cplus_should_press(
            self, cp_mode=0, cplus_active=False):
        # POKEMON_ZA_C+は「技が使用可能」の表示であり、
        # PLUSでC+化済みかを示す表示ではない。
        # そのため、自分が送ったPLUS/技入力から有効状態を管理する。
        return cp_mode == 1 and not cplus_active

    def ZA_mega_cplus_after_skill_input(
            self, cplus_active=False):
        # C+化中はA/B/X/Yの技入力で解除される。
        if cplus_active:
            print("[MEGA_CPLUS] skill input: C+ activation consumed")
        if getattr(self, "_za_mega_last_battle_mode", False):
            self._za_mega_mode5_skill_ready_until=0.0
        return False

    def ZA_mega_keep_left_moving(self,dir1,dir2,dir3,dir4,fallback_dirnum=4):
        # 右スティックの視点回転中に左入力だけが消えないよう、
        # 現在の通常移動方向を再送する。マーカー補正は継続しない。
        state_directions = (
            ("Lstick_state", 1),
            ("Lstick_state2", 2),
            ("Lstick_state3", 3),
            ("Lstick_state4", 4),
        )
        if (time.monotonic() < getattr(
                self, "_za_mega_field_dir5_until", 0.0)
                and getattr(self, "_za_mega_dir5", -1) >= 0):
            dirnum = 5
        else:
            # dir5の専用時間が終わった後は通常方向へ戻し、継続しない。
            dirnum = fallback_dirnum
            for state_name, state_dirnum in state_directions:
                if getattr(self, state_name, 0) == 1:
                    dirnum = state_dirnum
                    break
        self.ZA_MOVE_LStick(
            dir1,dir2,dir3,dir4,dirnum,"RELOAD")
        return dirnum

    def ZA_mega_mode4_view_nudge(self):
        """mode 4専用で視点を右スティック90度へ0.1秒だけ動かす。"""
        self.press(
            Direction(Stick.RIGHT, 90),
            duration=0.1,
            wait=0.0)

    def ZA_mega_mode4_yellow_hp(self, frame=None):
        """mode 4の上部ボスHPバーが黄色ならTrueを返す。"""
        if frame is None:
            camera=getattr(self, "camera", None)
            if camera is None:
                return False
            frame=(camera.readFrame()
                   if hasattr(camera, "readFrame") else None)
        if frame is None or getattr(frame, "size", 0) == 0:
            return False

        height,width=frame.shape[:2]
        x0,x1=int(width * 0.30),int(width * 0.71)
        y0,y1=int(height * 0.105),int(height * 0.16)
        region=frame[y0:y1, x0:x1]
        if region.size == 0:
            return False
        hsv=cv2.cvtColor(region, cv2.COLOR_BGR2HSV)
        color_masks=(
            ("GREEN", cv2.inRange(
                hsv, (35, 90, 100), (100, 255, 255))),
            ("YELLOW", cv2.inRange(
                hsv, (18, 100, 140), (40, 255, 255))),
        )
        minimum_column_pixels=max(3, int(region.shape[0] * 0.08))
        best_color="NONE"
        best_start=-1
        best_end=-1
        best_width=0
        for color_name,color_mask in color_masks:
            columns=(color_mask > 0).sum(axis=0)
            run_start=-1
            for index,column_pixels in enumerate(columns):
                if int(column_pixels) >= minimum_column_pixels:
                    if run_start < 0:
                        run_start=index
                    continue
                if run_start >= 0:
                    if index - run_start > best_width:
                        best_color=color_name
                        best_start=run_start
                        best_end=index
                        best_width=index - run_start
                    run_start=-1
            if run_start >= 0 and len(columns) - run_start > best_width:
                best_color=color_name
                best_start=run_start
                best_end=len(columns)
                best_width=len(columns) - run_start
        if best_start < 0 or best_end <= best_start:
            return False

        global_start=x0 + best_start
        global_end=x0 + best_end - 1
        full_bar_width=max(1.0, float(width) * 0.345)
        fill_ratio=float(best_width) / full_bar_width
        matched=bool(
            best_color == "YELLOW"
            and float(width) * 0.31 <= global_start <= float(width) * 0.36
            and global_end <= float(width) * 0.71
            and 0.12 <= fill_ratio <= 1.10)
        self.last_image_detection={
            "name": "POKEMON_ZA_MODE4_YELLOW_HP",
            "matched": matched,
            "hp_color": best_color,
            "fill_ratio": fill_ratio,
            "yellow_run": [global_start, global_end],
            "position": (global_start, y0),
            "template_size": (best_width, y1 - y0),
        }
        return matched

    def ZA_mega_mode4_yellow_hp_roll_ready(
            self, wait_seconds=5.0, attack_sent=False,
            yellow_detected=None):
        """黄色HP確認後、X攻撃または待機期限で1度だけ回避を許可する。"""
        if getattr(self, "_za_mega_mode4_yellow_hp_roll_done", False):
            return False
        now=time.monotonic()
        if yellow_detected is None:
            yellow_detected=self.ZA_mega_mode4_yellow_hp()
        yellow_since=getattr(
            self, "_za_mega_mode4_yellow_hp_since", None)
        if yellow_detected and yellow_since is None:
            yellow_since=now
            self._za_mega_mode4_yellow_hp_since=yellow_since
            print(
                "[MEGA_MODE4_YELLOW_HP] yellow detected; "
                "wait up to {:.1f}s for X attack".format(
                    max(0.0, float(wait_seconds))))
        if yellow_since is None:
            return False
        wait_seconds=max(0.0, float(wait_seconds))
        if not attack_sent and now - yellow_since < wait_seconds:
            return False
        self._za_mega_mode4_yellow_hp_roll_done=True
        self._za_mega_mode4_yellow_hp_roll_trigger=(
            "X attack complete" if attack_sent
            else "{:.1f}s elapsed without X attack".format(wait_seconds))
        return True

    def ZA_mega_mode4_yellow_hp_roll_after_attack(
            self, seconds, dir1, dir2, dir3, dir4, see_r,
            endpicture="", end2picture="", trigger="X attack complete"):
        """黄色HP確定後、20度移動で非ロックオンY回避する。"""
        seconds=max(0.0, float(seconds))
        if seconds <= 0.0:
            return "none"
        self.ZA_ZL_ACTION("END")
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        self.ZA_MOVE_LStick(
            dir1,dir2,dir3,dir4,
            Direction(Stick.LEFT, 20.0, 1.0),
            "RELOAD", force_direction=True)
        print(
            "[MEGA_MODE4_YELLOW_HP] {}; "
            "unlock and Y rolling at 20deg for {:.1f}s".format(
                str(trigger or "yellow HP trigger"), seconds))
        result=self.ZA_mega_red_edge_y_renda(
            seconds, endpicture=endpicture, end2picture=end2picture)
        if result == "complete":
            self.ZA_ZL_ACTION("")
            self.ZA_mega_keep_left_moving(dir1,dir2,dir3,dir4)
            self.ZA_MOVE_SEE(action="", in_see_r=see_r)
        return result

    def ZA_mega_attack_unavailable_y_dodge(
            self, dir1, dir2, dir3, dir4, see_r,
            repeat=2, cooldown=0.75, post_l_view_nudge=0,
            include_upper_marker=0):
        """攻撃不能中だけZLを外してY回避し、短時間で再ロックする。"""
        now = time.monotonic()
        if self.ZA_mega_field_attack_only_suppress_y_dodge():
            self.ZA_mega_field_attack_only_update(
                dir1, dir2, dir3, dir4)
            return False
        if (now < getattr(
                self, "_za_mega_attack_unavailable_y_dodge_retry_at", 0.0)
                or self.ZA_mega_choice_input_guard()):
            return False

        # ロック中に見えているマーカーを、ZLを外す前に取得しておく。
        marker_direction = self.ZA_mega_target_marker_direction(
            include_upper=bool(include_upper_marker))
        resume_dirnum = self.ZA_mega_keep_left_moving(
            dir1, dir2, dir3, dir4)
        retry_at = now + max(0.1, float(cooldown))
        self._za_mega_attack_unavailable_y_dodge_retry_at = retry_at
        self._za_mega_relock_retry_at = retry_at

        if self.ZA_mega_field_attack_only_suppress_y_dodge():
            # marker確認中にdir5～攻撃専用区間へ入った場合も、
            # ZLを外す前に中止する。
            self.ZA_mega_field_attack_only_update(
                dir1, dir2, dir3, dir4)
            return False

        # YはZL解除後に送らないと技入力となり、ローリングにならない。
        self.ZA_ZL_ACTION("END")
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        roll_angles = {
            1: dir1,
            2: dir2,
            3: dir3,
            4: dir4,
            5: getattr(self, "_za_mega_dir5", dir4),
        }
        roll_angle = (
            float(roll_angles.get(resume_dirnum, dir4)) + 20.0) % 360.0
        self.ZA_MOVE_LStick(
            dir1, dir2, dir3, dir4,
            Direction(Stick.LEFT, roll_angle, 1.0), "RELOAD",
            force_direction=True)
        roll_see_r = min(1.0, max(0.0, float(see_r) * 2.0))
        self.ZA_MOVE_SEE(action="", in_see_r=roll_see_r)
        roll_interrupted=False
        roll_repeat=max(1, int(repeat))
        for roll_index in range(roll_repeat):
            # 区間直前に始まった2回ローリングも、期限を越えた次のYは送らない。
            if self.ZA_mega_field_attack_only_suppress_y_dodge():
                roll_interrupted=True
                break
            self.pressRep(
                Button.Y,
                repeat=1,
                duration=0.04,
                wait=0.0,
                interval=0.1)
            if roll_index + 1 < roll_repeat:
                self.wait(0.1)
        if roll_interrupted:
            self.ZA_MOVE_SEE(action="END", in_see_r=roll_see_r)
            self.ZA_mega_field_attack_only_update(
                dir1, dir2, dir3, dir4)
            self.ZA_ZL_ACTION("")
            self.ZA_MOVE_SEE(action="", in_see_r=see_r)
            return False
        # Yローリング後は高速視点回転だけを止め、L待機へ持ち越さない。
        self.ZA_MOVE_SEE(action="END", in_see_r=roll_see_r)
        # Lの再センターは1秒後のままでも、ZLはローリング直後に戻す。
        # これにより非ロックオンになるのはY入力中だけとなる。
        self.ZA_ZL_ACTION("")

        if marker_direction:
            self.ZA_MOVE_LStick(
                dir1, dir2, dir3, dir4, marker_direction, "RELOAD")
            # 2回目のローリング完了から1秒以内にはLを送らない。
            self.wait(1.1)
            self.pressRep(
                Button.L,
                repeat=1,
                duration=0.04,
                wait=0.0,
                interval=0.1)
            if post_l_view_nudge:
                self.ZA_mega_mode4_view_nudge()

        self.ZA_MOVE_LStick(
            dir1, dir2, dir3, dir4, resume_dirnum, "RELOAD")
        self.ZA_MOVE_SEE(
            action=("END" if getattr(
                self, "_za_mega_movemode", 0) == 1 else ""),
            in_see_r=see_r)
        # L待機時間を延ばしても、復帰直後に次の回避を開始しない。
        retry_at = time.monotonic() + max(0.1, float(cooldown))
        self._za_mega_attack_unavailable_y_dodge_retry_at = retry_at
        self._za_mega_relock_retry_at = retry_at
        print(
            "[MEGA_NO_ATTACK_DODGE] unlock -> Y x{} -> relock".format(
                max(1, int(repeat))))
        return True

    def _ZA_mega_field_position_matches(self, usenum):
        """開始直後／復帰時の選択位置が使用番号と一致するか返す。"""
        if usenum==1:
            return (self.image_check("POKEMON_ZA_FIELD1")
                    or self.image_check("POKEMON_ZA_FIELD_BACK1"))
        if usenum==2:
            return (self.image_check("POKEMON_ZA_FIELD2")
                    or self.image_check("POKEMON_ZA_FIELD_BACK2"))
        if usenum==3:
            return (self.image_check("POKEMON_ZA_FIELD3")
                    or self.image_check("POKEMON_ZA_FIELD_BACK3"))
        if usenum==4:
            return (self.image_check("POKEMON_ZA_FIELD4")
                    or self.image_check("POKEMON_ZA_FIELD_BACK4"))
        if usenum==5:
            return (self.image_check("POKEMON_ZA_FIELD5")
                    or self.image_check("POKEMON_ZA_FIELD_BACK5"))
        if usenum==6:
            return (self.image_check("POKEMON_ZA_FIELD6")
                    or self.image_check("POKEMON_ZA_FIELD_BACK6"))
        return False

    def ZA_mega_mode5_detect_screen_state(self, nofiled):
        """mode 5画面を固有4技→HARD/Escape→黒背景の順で判定する。"""
        # 固有4技はすべてのFIELD系誤一致より先に確定する。
        event_attack_picture=self.ZA_mega_mode5_event_attack_picture()
        field_w_detected=self.image_check("POKEMON_ZA_FIELD_W")
        field_back_w_detected=self.image_check("POKEMON_ZA_FIELD_BACK_W")
        # FIELD_W/BACK_Wが見えていてもHARD FIELDを必ず独立照合する。
        field_hard_detected=bool(self.image_check(
            "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"))
        escape_detected=bool(self.image_check("POKEMON_ZA_ESCAPE"))
        field_screen_detected=bool(
            field_w_detected or field_back_w_detected
            or field_hard_detected)
        retry_resume_detected=bool(
            not event_attack_picture
            and (field_hard_detected or escape_detected))
        start_flag=int(getattr(
            self, "_za_mega_mode5_start_flag", 0))
        # 固有4技もFIELD／Escapeもない時だけ敗戦候補を監視する。
        # 黒背景単独は入力を止めて確認するが、黒Comment／SELECTとの
        # ANDが成立するまでRETRY_SELECTIONへは移さない。
        defeat_state=(
            self.ZA_mega_mode5_defeat_wait_update()
            if (not event_attack_picture
                and not retry_resume_detected
                and not field_screen_detected) else "none")
        defeat_background_prompt_detected=(defeat_state != "none")
        defeat_waiting=(defeat_state == "confirming")
        defeat_confirmed=(defeat_state == "defeat")
        normal_comment_check=getattr(
            self, "ZA_mega_mode5_normal_black_comment_confirmed", None)
        normal_black_comment_detected=bool(
            not event_attack_picture
            and not retry_resume_detected
            and not field_screen_detected
            and not defeat_background_prompt_detected
            and callable(normal_comment_check)
            and normal_comment_check())

        green_resume_detected=False
        if (nofiled==1 and not event_attack_picture
                and not retry_resume_detected
                and not field_screen_detected
                and not defeat_background_prompt_detected
                and self._za_mega_z_guard_enabled):
            on_green,green_direction,_=(
                self.ZA_mega_green_safe_floor_direction())
            green_resume_detected=bool(
                on_green or isinstance(green_direction, Direction))

        battle_screen_detected=bool(
            (nofiled==1 or start_flag < 4)
            and not retry_resume_detected
            and not defeat_background_prompt_detected
            and not normal_black_comment_detected
            and not green_resume_detected
            and (event_attack_picture
                 or self.image_check("POKEMON_ZA_BATTLE")))
        resume_screen_detected=bool(
            retry_resume_detected
            or event_attack_picture
            or field_screen_detected
            or green_resume_detected
            or battle_screen_detected)
        choice_input_guard=bool(defeat_confirmed)
        if event_attack_picture:
            resume_reason="event-attack-ui"
        elif field_hard_detected:
            resume_reason="hard-field"
        elif escape_detected:
            resume_reason="escape"
        elif field_w_detected or field_back_w_detected:
            resume_reason="field-indicator"
        elif green_resume_detected:
            resume_reason="green-floor"
        elif battle_screen_detected:
            resume_reason="battle"
        elif defeat_confirmed:
            resume_reason="defeat-black-and-choice"
        elif defeat_waiting:
            resume_reason="defeat-black-confirming"
        elif normal_black_comment_detected:
            resume_reason="normal-black-comment"
        else:
            resume_reason="none"
        return {
            "field_w": field_w_detected,
            "field_back_w": field_back_w_detected,
            "field_hard": field_hard_detected,
            "field_screen": field_screen_detected,
            "escape": escape_detected,
            "green_resume": green_resume_detected,
            "battle_screen": battle_screen_detected,
            "event_attack_picture": event_attack_picture,
            "resume_screen": resume_screen_detected,
            "retry_resume": retry_resume_detected,
            "choice_guard": choice_input_guard,
            "defeat_background_prompt": defeat_background_prompt_detected,
            "defeat_waiting": defeat_waiting,
            "defeat_confirmed": defeat_confirmed,
            "normal_black_comment": normal_black_comment_detected,
            "resume_reason": resume_reason,
        }

    def ZA_mega_mode5_low_yellow_hp(self, frame=None):
        """最終戦の黄色HPバーがおよそ1/4まで減った再開画面を返す。"""
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return False
        if frame is None:
            camera=getattr(self, "camera", None)
            if camera is None:
                return False
            if hasattr(camera, "readFreshFrame"):
                frame=camera.readFreshFrame(timeout=0.75)
            else:
                frame=(camera.readFrame()
                       if hasattr(camera, "readFrame") else None)
        if frame is None or getattr(frame, "size", 0) == 0:
            return False

        height,width=frame.shape[:2]
        # Switch No2録画ではボスHPの全幅は画面幅の約34.5%、開始位置は
        # x=0.33付近。上部の名前や演出色を避け、バー本体だけを見る。
        x0,x1=int(width * 0.30),int(width * 0.71)
        y0,y1=int(height * 0.105),int(height * 0.16)
        region=frame[y0:y1, x0:x1]
        if region.size == 0:
            return False
        hsv=cv2.cvtColor(region, cv2.COLOR_BGR2HSV)
        yellow_mask=cv2.inRange(
            hsv, (18, 100, 140), (40, 255, 255))
        minimum_column_pixels=max(3, int(region.shape[0] * 0.08))
        yellow_columns=(yellow_mask > 0).sum(axis=0)

        longest_start=-1
        longest_end=-1
        run_start=-1
        for index,column_pixels in enumerate(yellow_columns):
            if int(column_pixels) >= minimum_column_pixels:
                if run_start < 0:
                    run_start=index
                continue
            if run_start >= 0:
                if index - run_start > longest_end - longest_start:
                    longest_start=run_start
                    longest_end=index
                run_start=-1
        if run_start >= 0:
            end=len(yellow_columns)
            if end - run_start > longest_end - longest_start:
                longest_start=run_start
                longest_end=end
        if longest_start < 0 or longest_end <= longest_start:
            return False

        run_width=longest_end - longest_start
        global_start=x0 + longest_start
        global_end=x0 + longest_end - 1
        full_bar_width=max(1.0, float(width) * 0.345)
        fill_ratio=float(run_width) / full_bar_width
        matched=bool(
            float(width) * 0.31 <= global_start <= float(width) * 0.36
            and global_end <= float(width) * 0.52
            and 0.20 <= fill_ratio <= 0.42)
        self._za_mega_mode5_yellow_hp_fill_ratio=fill_ratio
        self.last_image_detection={
            "name": "POKEMON_ZA_LAST_BATTLE_YELLOW_LOW_HP",
            "matched": matched,
            "fill_ratio": fill_ratio,
            "yellow_run": [global_start, global_end],
            "position": (global_start, y0),
            "template_size": (run_width, y1 - y0),
        }
        return matched

    def ZA_mega_mode5_hp_resume_mode(self, frame=None):
        """testmode1用に再開時HPをHP75／OTHER／UNKNOWNへ分類する。"""
        self._za_mega_testmode1_hp_fill_ratio=0.0
        self._za_mega_testmode1_hp_color="NONE"
        self._za_mega_testmode1_hp_frame=None
        if not getattr(self, "_za_mega_last_battle_mode", False):
            return "UNKNOWN"
        if frame is None:
            camera=getattr(self, "camera", None)
            if camera is None:
                return "UNKNOWN"
            if hasattr(camera, "readFreshFrame"):
                frame=camera.readFreshFrame(timeout=0.75)
            else:
                frame=(camera.readFrame()
                       if hasattr(camera, "readFrame") else None)
        if frame is None or getattr(frame, "size", 0) == 0:
            return "UNKNOWN"
        self._za_mega_testmode1_hp_frame=frame

        height,width=frame.shape[:2]
        x0,x1=int(width * 0.30),int(width * 0.71)
        y0,y1=int(height * 0.105),int(height * 0.16)
        region=frame[y0:y1, x0:x1]
        if region.size == 0:
            return "UNKNOWN"
        hsv=cv2.cvtColor(region, cv2.COLOR_BGR2HSV)
        color_masks=(
            ("GREEN", cv2.inRange(
                hsv, (35, 90, 100), (100, 255, 255))),
            ("YELLOW", cv2.inRange(
                hsv, (18, 100, 140), (40, 255, 255))),
        )
        minimum_column_pixels=max(3, int(region.shape[0] * 0.08))
        best_color="NONE"
        best_start=-1
        best_end=-1
        best_width=0
        for color_name,color_mask in color_masks:
            columns=(color_mask > 0).sum(axis=0)
            run_start=-1
            for index,column_pixels in enumerate(columns):
                if int(column_pixels) >= minimum_column_pixels:
                    if run_start < 0:
                        run_start=index
                    continue
                if run_start >= 0:
                    if index - run_start > best_width:
                        best_color=color_name
                        best_start=run_start
                        best_end=index
                        best_width=index - run_start
                    run_start=-1
            if run_start >= 0 and len(columns) - run_start > best_width:
                best_color=color_name
                best_start=run_start
                best_end=len(columns)
                best_width=len(columns) - run_start
        if best_start < 0 or best_end <= best_start:
            return "UNKNOWN"

        global_start=x0 + best_start
        global_end=x0 + best_end - 1
        full_bar_width=max(1.0, float(width) * 0.345)
        fill_ratio=float(best_width) / full_bar_width
        bar_position_valid=bool(
            float(width) * 0.31 <= global_start <= float(width) * 0.36
            and global_end <= float(width) * 0.71
            and 0.12 <= fill_ratio <= 1.10)
        if not bar_position_valid:
            return "UNKNOWN"
        resume_mode=(
            "HP75"
            if best_color == "GREEN" and 0.55 <= fill_ratio <= 0.80
            else "OTHER")
        self._za_mega_testmode1_hp_fill_ratio=fill_ratio
        self._za_mega_testmode1_hp_color=best_color
        self.last_image_detection={
            "name": "POKEMON_ZA_LAST_BATTLE_TESTMODE1_HP",
            "matched": True,
            "resume_mode": resume_mode,
            "hp_color": best_color,
            "fill_ratio": fill_ratio,
            "yellow_run": [global_start, global_end],
            "position": (global_start, y0),
            "template_size": (best_width, y1 - y0),
        }
        return resume_mode

    def ZA_mega_mode5_testmode1_settings(self):
        """TESTMODE1の開始直後の手動調整値を1か所で返す。"""
        # [MEGA_MODE5_TESTMODE1_MANUAL_SETTINGS]
        # 手動調整はこのreturn内だけを変更する。
        # 順序: 緑床確認 -> 緑床なし初期移動 -> 待機 -> 障害物移動
        #       -> 青へ向き直し/L -> 障害物内攻撃・定期回避
        return {
            # 1. FIELD判定直後の緑床確認。現在の0は確認せず移動開始。
            #    有効化した場合もHP75だけがこの初期確認を使用する。
            "INITIAL_GREEN_CHECK_COUNT": 0,
            "INITIAL_GREEN_CHECK_SECONDS": 0.0,
            "INITIAL_GREEN_WAIT_SECONDS": 0.0,
            "HP75_INITIAL_GREEN_MOVE_ANGLE": 90.0,
            # 2. 緑床がない場合: 固定方向へ移動してから待機する。
            "INITIAL_NO_GREEN_MOVE_ANGLE": 90.0,
            "INITIAL_NO_GREEN_MOVE_SECONDS": 3.0,
            "INITIAL_POST_MOVE_WAIT_SECONDS": 4.5,
            # 3. HP75: 緑床位置から青側障害物へ入り、青側へ向く。
            "HP75_COVER_MOVE_ANGLE": 185.0,
            # 障害物の端ではなく少し内側へ入るため+0.5秒。
            "HP75_COVER_MOVE_SECONDS": 5.0,
            "HP75_FACE_ANGLE": 30.0,
            # 4. HP75以外: 緑床用90度移動を経由せず、再開地点から
            #    青側障害物へ直接移動する。HP75経路の
            #    90度3.0秒 + 185度4.5秒を1本に合成し、そこから
            #    障害物の内側へ入る分0.5秒を追加した値。
            "OTHER_COVER_MOVE_ANGLE": 150.0,
            "OTHER_COVER_MOVE_SECONDS": 5.7,
            "OTHER_FACE_ANGLE": 30.0,
            # 5. 障害物到達後: 向き直し、定期的にY回避する。
            "FACE_DIRECTION_SECONDS": 1.0,
            "COVER_DODGE_INTERVAL_SECONDS": 2.4,
            "COVER_DODGE_ANGLE": 90.0,
            "COVER_DODGE_REPEAT": 2,
            # 青側障害物から赤側へ移る直前だけ、障害物に
            # Yを3回当てて赤側移動の開始地点を固定する。
            "BLUE_TO_RED_ANCHOR_DODGE_ANGLE": 90.0,
            "BLUE_TO_RED_ANCHOR_DODGE_REPEAT": 3,
            # 青側で深く入ってロックオンが外れても、攻撃前に
            # 赤側と同じ270度へ移動して射線を戻す。
            "BLUE_ATTACK_PREMOVE_STAY_SECONDS": 1.0,
            "BLUE_ATTACK_PREMOVE_ANGLE": 270.0,
            "BLUE_ATTACK_PREMOVE_ANGLE_SECONDS": 0.8,
            
            "BLUE_ATTACK_PREMOVE_ANGLE2": 90.0,
            "BLUE_ATTACK_PREMOVE_ANGLE_SECONDS2": 0.2,
            
            "BLUE_ATTACK_PREMOVE_STAY_SECONDS2": 0.5,
            # 6. 予兆を無視する回数。-1は既存の予兆回避へ移行せず、
            #    7の赤のみ判定または予兆セット間の青不在で赤側へ移る。
            "CHARGE_WARNING_SKIP_COUNT": -1,
            # 敗北黒背景は5秒連続確認できた場合だけComment／SELECTを扱う。
            "DEFEAT_BLACK_STABLE_SECONDS": 5.0,
            # FIELD系／Escapeを一度も確認できない待機がこの時間続いた時だけ、
            # 最終戦名をイベント判定として初めて照合する。
            "FIELD_WAIT_EVENT_TIMEOUT_SECONDS": 180.0,
            # FIELD系とEscapeがなく、最終戦名がこの時間連続表示された時だけ
            # ZLを入れて固有4技UIを再確認する。
            "LAST_BATTLE_NAME_LOCKON_SECONDS": 5.0,
            # 青／赤側の移行判定は、強い光の表示→消失を1セットとし、
            # 2セット、または同じ側で5分経過した後に既存の5秒待機、
            # 各側角度のY2回、3秒待機を行う。
            "SIDE_TRANSITION_STRONG_LIGHT_SETS": 2,
            "SIDE_TRANSITION_TIMEOUT_SECONDS": 300.0,
            "SIDE_TRANSITION_STRONG_LIGHT_CLEAR_SECONDS": 0.5,
            "SIDE_TRANSITION_WAIT_SECONDS": 5.0,
            "SIDE_TRANSITION_POST_DODGE_WAIT_SECONDS": 3.0,
            "SIDE_TRANSITION_DODGE_REPEAT": 2,
            "BLUE_SIDE_TRANSITION_DODGE_ANGLE": 90.0,
            "RED_SIDE_TRANSITION_DODGE_ANGLE": 100.0,
            # 予兆1組目の終了から次の予兆開始まで青敵を確認できなければ、
            # 赤色を直接取れなくても青撃破・赤敵ありとして扱う。
            "WARNING_BLUE_FALLBACK_ENABLED": False,
            # 2組目の強い光が消えてから、青側でポケモンを
            # 戻す判定と赤側障害物への移動を始めるまでの待機。
            "WARNING_RED_COVER_DELAY_SECONDS": 5.0,
            # 7. 既存の確定赤継続判定。
            "RED_ONLY_FALLBACK_SECONDS": 3.0,
            "RED_ONLY_CHECK_INTERVAL_SECONDS": 0.30,
            "RED_ONLY_GAP_TOLERANCE_SECONDS": 10.0,
            "RED_ONLY_MIN_CONFIRMATIONS": 3,
            "BLUE_BURROW_GRACE_SECONDS": 12.0,
            # 既存判定が成立しない場合の保険。青側で青敵を最後に
            # 確認してから60秒検知できなければ赤側へ移る。
            "BLUE_ABSENCE_FALLBACK_SECONDS": 60.0,
            "BLUE_ABSENCE_CHECK_INTERVAL_SECONDS": 0.30,
            # 8. 青撃破後: 青側障害物から赤側障害物へ固定移動する試案値。
            "RED_COVER_MOVE_ANGLE": 60.0,#30.0,
            # 青側の深さを0.5秒増やした分、赤側経路も延長。
            "RED_COVER_MOVE_SECONDS": 7.2,
            "RED_FACE_ANGLE": 170.0,#160.0,#140.0,
            # 赤側へ到着し、160度移動とL視点合わせを行った後の短い移動。
            # 赤側攻撃ループのANGLE2とは独立。
            "BLUE_TO_RED_ARRIVAL_MOVE_ANGLE": 90.0,
            "BLUE_TO_RED_ARRIVAL_MOVE_SECONDS": 0.2,
            "BLUE_TO_RED_ARRIVAL_MOVE_REPEAT": 2,
            # 9. 赤側障害物から攻撃する直前の時間指定移動。
            #    力をためた～強い光の最終検知後7秒は入力しない。
            
            "RED_ATTACK_PREMOVE_STAY_SECONDS": 1.0,
            "RED_ATTACK_PREMOVE_ANGLE": 270.0,
            "RED_ATTACK_PREMOVE_ANGLE_SECONDS": 0.8,#0.5,
            "RED_ATTACK_PREMOVE_BLOCK_SECONDS": 7.0,
            
            "RED_ATTACK_PREMOVE_ANGLE2": 100.0,
            "RED_ATTACK_PREMOVE_ANGLE_SECONDS2": 0.2,
            # RPush演出からFIELDへ戻った時だけ使う短い敵側移動。
            # 0～30度の向き直し、L入力、障害物初期化は再実行しない。
            "RPUSH_FIELD_BLUE_MOVE_ANGLE": 90.0,
            "RPUSH_FIELD_RED_MOVE_ANGLE": 100.0,
            "RPUSH_FIELD_MOVE_SECONDS": 0.2,
            
            "RED_ATTACK_PREMOVE_STAY_SECONDS2": 0.5,
            # 10. 赤側障害物で青を再確認した場合は通常mode5へ戻す。
            #     赤と青は同時に存在し得るため、途中の赤検知では青確認を
            #     取り消さず、確定青を複数回確認してから復帰する。
            "BLUE_RETURN_TO_LEGACY_ENABLED": False,
            "BLUE_RETURN_SECONDS": 1.0,
            "BLUE_RETURN_CHECK_INTERVAL_SECONDS": 0.30,
            "BLUE_RETURN_GAP_TOLERANCE_SECONDS": 10.0,
            "BLUE_RETURN_MIN_CONFIRMATIONS": 3,
            # 11. 赤側障害物で赤青とも長時間見えない場合の保険。
            #     障害物による一時遮蔽では戻さず、通常mode5へ戻して
            #     次のBLACK_COMMENT／SELECT後にTESTMODE1を再試行する。
            "RED_COVER_NO_ENEMY_RETURN_SECONDS": 60.0,
            "RED_COVER_NO_ENEMY_MIN_CONFIRMATIONS": 5,
        }

    def ZA_mega_mode5_testmode1_warning_cycle_update(self, event):
        """連続する予兆セット間の青敵有無から赤側遷移を判定する。"""
        settings=self.ZA_mega_mode5_testmode1_settings()
        phase=str(getattr(
            self, "_za_mega_testmode1_phase", "DISABLED"))
        if (not getattr(self, "_za_mega_testmode1_enabled", False)
                or phase != "COVER_ATTACK"
                or not bool(settings.get(
                    "WARNING_BLUE_FALLBACK_ENABLED", True))
                or int(settings.get("CHARGE_WARNING_SKIP_COUNT", -1)) >= 0):
            return False

        event=str(event or "").upper()
        if event == "BLUE":
            if getattr(
                    self,
                    "_za_mega_testmode1_warning_interval_active", False):
                if not getattr(
                        self,
                        "_za_mega_testmode1_warning_interval_blue_seen",
                        False):
                    self.ZA_mega_mode5_trace(
                        "TESTMODE1_WARNING_BLUE_SEEN",
                        "blue confirmed between warning sets; keep blue cover",
                        force=True)
                self._za_mega_testmode1_warning_interval_blue_seen=True
            return False

        if event in {"CHARGE", "STRONG_LIGHT"}:
            cycle_active=bool(getattr(
                self, "_za_mega_testmode1_warning_cycle_active", False))
            if not cycle_active:
                self._za_mega_testmode1_warning_cycle_active=True
                self._za_mega_testmode1_warning_cycle_saw_strong=(
                    event == "STRONG_LIGHT")
                if getattr(
                        self,
                        "_za_mega_testmode1_warning_interval_active", False):
                    blue_seen=bool(getattr(
                        self,
                        "_za_mega_testmode1_warning_interval_blue_seen",
                        False))
                    self._za_mega_testmode1_warning_interval_active=False
                    self._za_mega_testmode1_warning_interval_blue_seen=False
                    self._za_mega_testmode1_warning_red_pending=(
                        not blue_seen)
                    self.ZA_mega_mode5_trace(
                        ("TESTMODE1_WARNING_BLUE_CONFIRMED"
                         if blue_seen else
                         "TESTMODE1_WARNING_RED_PENDING"),
                        ("blue was visible before next warning; keep blue cover"
                         if blue_seen else
                         "blue was absent until next warning; wait for strong "
                         "light to clear before red cover"),
                        force=True)
            elif event == "STRONG_LIGHT":
                self._za_mega_testmode1_warning_cycle_saw_strong=True
            return False

        if event != "CLEAR":
            return False
        if not getattr(
                self, "_za_mega_testmode1_warning_cycle_active", False):
            return False
        # 「力をためた」と「強い光」の間に通知が一時的に消えても、
        # 1組を2回と数えない。強い光が消えた時点だけをセット終了とする。
        if not getattr(
                self, "_za_mega_testmode1_warning_cycle_saw_strong", False):
            return False

        self._za_mega_testmode1_warning_cycle_active=False
        self._za_mega_testmode1_warning_cycle_saw_strong=False
        if getattr(
                self, "_za_mega_testmode1_warning_red_pending", False):
            self._za_mega_testmode1_warning_red_pending=False
            self._za_mega_testmode1_warning_interval_active=False
            self._za_mega_testmode1_warning_interval_blue_seen=False
            delay_seconds=max(0.0, float(settings.get(
                "WARNING_RED_COVER_DELAY_SECONDS", 5.0)))
            self._za_mega_testmode1_phase="WAIT_RED_COVER_DELAY"
            self._za_mega_testmode1_red_cover_move_not_before=(
                time.monotonic() + delay_seconds)
            self._za_mega_testmode1_red_only_since=0.0
            self._za_mega_testmode1_red_only_last_seen=0.0
            self._za_mega_testmode1_red_only_confirmations=0
            self._za_mega_testmode1_blue_last_seen_at=0.0
            self._za_mega_testmode1_enemy_check_retry_at=0.0
            self.ZA_mega_mode5_trace(
                "TESTMODE1_WARNING_RED_COVER_DELAY",
                "second strong light cleared; no blue in warning interval; "
                "wait {:.1f}s before red cover".format(delay_seconds),
                force=True)
            return True

        self._za_mega_testmode1_warning_interval_active=True
        self._za_mega_testmode1_warning_interval_blue_seen=False
        self.ZA_mega_mode5_trace(
            "TESTMODE1_WARNING_BLUE_WINDOW_START",
            "warning set complete; watch blue until next warning",
            force=True)
        return False

    def ZA_mega_mode5_testmode1_side_cycle_reset(self, phase=""):
        """青／赤側遷移用の強い光セットと3分時計を初期化する。"""
        self._za_mega_testmode1_side_cycle_phase=str(phase or "")
        self._za_mega_testmode1_side_strong_visible=False
        self._za_mega_testmode1_side_strong_clear_since=0.0
        self._za_mega_testmode1_side_strong_sets=0
        self._za_mega_testmode1_side_decision_not_before=0.0
        self._za_mega_testmode1_side_timeout_started_at=-1.0

    def ZA_mega_mode5_testmode1_enter_free_run(self, reason):
        """青／赤確認の結果から明示的に実フリーランへ入る。"""
        self.ZA_mega_mode5_attack_watchdog_reset()
        now=time.monotonic()
        self._za_mega_mode5_free_run_active=True
        self._za_mega_mode5_free_run_started_at=now
        self._za_mega_mode5_free_run_next_attack_at=0.0
        self._za_mega_mode5_free_run_move_angle=None
        self._za_mega_mode5_battle_active=True
        legacy_latched=bool(getattr(
            self, "_za_mega_testmode1_legacy_until_reset", False))
        self._za_mega_testmode1_phase=(
            "LEGACY_COMBAT" if legacy_latched else "FREE_RUN")
        if self._za_mega_testmode1_phase == "FREE_RUN":
            self._za_mega_mode5_recent_combat_phase="FREE_RUN"
        self._za_mega_testmode1_legacy_until_reset=False
        self._za_mega_testmode1_existing_charge_latched=False
        self._za_mega_testmode1_returned_to_blue=False
        self.ZA_mega_mode5_testmode1_side_cycle_reset("FREE_RUN")
        self.ZA_mega_mode5_transition("FREE_RUN", str(reason))
        self.ZA_mega_mode5_trace(
            "TESTMODE1_FREE_RUN",
            "{}; enable move/view/attack and free-run strong-light action".format(
                reason),
            force=True)
        return True

    def ZA_mega_mode5_resume_free_run_after_charge(self, charge_result):
        """FREE_RUN中の緑床／回避完了後もFIELD待機へ戻さず継続する。"""
        if charge_result not in {"dodge", "complete"}:
            return False
        saved_phase=str(getattr(
            self, "_za_mega_testmode1_phase_before_charge", ""))
        current_phase=str(getattr(
            self, "_za_mega_testmode1_phase", ""))
        if (not getattr(
                self, "_za_mega_mode5_free_run_active", False)
                or (saved_phase != "FREE_RUN"
                    and current_phase != "EXISTING_CHARGE")):
            return False
        self._za_mega_testmode1_phase="FREE_RUN"
        self._za_mega_mode5_free_run_active=True
        self._za_mega_mode5_battle_active=True
        self._za_mega_last_charge_attack_suspended=False
        self._za_mega_testmode1_existing_charge_latched=False
        self._za_mega_testmode1_phase_before_charge=""
        self._za_mega_mode5_no_attack_since=time.monotonic()
        self.ZA_mega_mode5_trace(
            "FREE_RUN_CHARGE_COMPLETE",
            "{}; resume rotating view, movement and attack".format(
                charge_result),
            force=True)
        return True

    def ZA_mega_mode5_testmode1_side_transition_update(
            self, dir1, dir2, dir3, dir4, see_r):
        """強い光2セットまたは3分後、通常C+不在と敵色を確認する。"""
        phase=str(getattr(
            self, "_za_mega_testmode1_phase", "DISABLED"))
        tracked_phases={
            "COVER_ATTACK": "BLUE",
            "RED_COVER_ATTACK": "RED",
            "BLUE_CHASE_ATTACK": "BLUE_RETURN",
        }
        if (not getattr(self, "_za_mega_testmode1_enabled", False)
                or phase not in tracked_phases):
            return "none"

        settings=self.ZA_mega_mode5_testmode1_settings()
        required=max(1, int(settings.get(
            "SIDE_TRANSITION_STRONG_LIGHT_SETS", 2)))
        timeout_seconds=max(180.0, float(settings.get(
            "SIDE_TRANSITION_TIMEOUT_SECONDS", 180.0)))
        if str(getattr(
                self, "_za_mega_testmode1_side_cycle_phase", "")) != phase:
            self.ZA_mega_mode5_testmode1_side_cycle_reset(phase)

        now=time.monotonic()
        decision_not_before=float(getattr(
            self, "_za_mega_testmode1_side_decision_not_before", 0.0))
        if decision_not_before <= 0.0:
            timeout_started_at=float(getattr(
                self, "_za_mega_testmode1_side_timeout_started_at", -1.0))
            if timeout_started_at < 0.0:
                timeout_started_at=now
                self._za_mega_testmode1_side_timeout_started_at=now
            if now - timeout_started_at >= timeout_seconds:
                # HP最大などでCHARGEだけが見え、STRONG_LIGHTが出ない場合も
                # 180秒判定後へ「強い光待ち」を持ち越して攻撃を止めない。
                self._za_mega_testmode1_red_premove_waiting_strong_light=(
                    False)
                self._za_mega_testmode1_red_premove_block_until=0.0
                wait_seconds=max(0.0, float(settings.get(
                    "SIDE_TRANSITION_WAIT_SECONDS", 5.0)))
                decision_not_before=now + wait_seconds
                self._za_mega_testmode1_side_decision_not_before=(
                    decision_not_before)
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_SIDE_TIMEOUT_DECISION_WAIT",
                    "{} side {:.1f}s elapsed before {} sets; "
                    "wait {:.1f}s".format(
                        tracked_phases[phase], timeout_seconds, required,
                        wait_seconds),
                    force=True)
        if decision_not_before <= 0.0:
            charge_visible=self.image_check(
                "POKEMON_ZA_LAST_BATTLE_CHARGE")
            strong_visible=self.image_check(
                "POKEMON_ZA_LAST_BATTLE_STRONG_LIGHT")
            if phase in {"COVER_ATTACK", "RED_COVER_ATTACK"}:
                warning_started=False
                if charge_visible and not strong_visible:
                    warning_started=not bool(getattr(
                        self,
                        "_za_mega_testmode1_red_premove_waiting_strong_light",
                        False))
                    self._za_mega_testmode1_red_premove_waiting_strong_light=(
                        True)
                if strong_visible:
                    warning_started=bool(
                        not getattr(
                            self,
                            "_za_mega_testmode1_side_strong_visible", False)
                        or getattr(
                            self,
                            "_za_mega_testmode1_red_premove_waiting_strong_light",
                            False))
                    self._za_mega_testmode1_red_premove_waiting_strong_light=(
                        False)
                    block_seconds=max(0.0, float(settings.get(
                        "RED_ATTACK_PREMOVE_BLOCK_SECONDS", 7.0)))
                    self._za_mega_testmode1_red_premove_block_until=max(
                        float(getattr(
                            self,
                            "_za_mega_testmode1_red_premove_block_until", 0.0)),
                        now + block_seconds)
                if warning_started:
                    # 既存の障害物内仕様を維持する。フリーラン用の緑床探索や
                    # 遠距離回避には入らず、通常攻撃／攻撃前移動を止めて
                    # 障害物方向の定期Y×2を直ちに開始する。
                    self._za_mega_testmode1_next_dodge_at=now
                    self.ZA_mega_mode5_trace(
                        "TESTMODE1_SIDE_WARNING_ROLL_ONLY",
                        "{}; hold normal attack/premove and keep cover Y rolls".format(
                            "strong light" if strong_visible
                            else "charge warning"),
                        force=True)
            if strong_visible:
                if not getattr(
                        self, "_za_mega_testmode1_side_strong_visible", False):
                    self._za_mega_testmode1_side_strong_visible=True
                    self.ZA_mega_mode5_trace(
                        "TESTMODE1_SIDE_STRONG_LIGHT",
                        "{} side set started; count only, no dodge/green action".format(
                            tracked_phases[phase]),
                        force=True)
                self._za_mega_testmode1_side_strong_clear_since=0.0
                return "none"
            if not getattr(
                    self, "_za_mega_testmode1_side_strong_visible", False):
                return "none"
            clear_since=float(getattr(
                self, "_za_mega_testmode1_side_strong_clear_since", 0.0))
            if clear_since <= 0.0:
                self._za_mega_testmode1_side_strong_clear_since=now
                clear_since=now
            clear_seconds=max(0.0, float(settings.get(
                "SIDE_TRANSITION_STRONG_LIGHT_CLEAR_SECONDS", 0.5)))
            if now - clear_since < clear_seconds:
                return "none"
            self._za_mega_testmode1_side_strong_visible=False
            self._za_mega_testmode1_side_strong_clear_since=0.0
            completed=int(getattr(
                self, "_za_mega_testmode1_side_strong_sets", 0)) + 1
            self._za_mega_testmode1_side_strong_sets=completed
            self.ZA_mega_mode5_trace(
                "TESTMODE1_SIDE_STRONG_LIGHT_SET_COMPLETE",
                "{} side set {}/{} complete".format(
                    tracked_phases[phase], completed, required),
                force=True)
            if completed < required:
                return "none"
            wait_seconds=max(0.0, float(settings.get(
                "SIDE_TRANSITION_WAIT_SECONDS", 5.0)))
            decision_not_before=now + wait_seconds
            self._za_mega_testmode1_side_decision_not_before=(
                decision_not_before)
            self.ZA_mega_mode5_trace(
                "TESTMODE1_SIDE_DECISION_WAIT",
                "{} side two sets complete; wait {:.1f}s".format(
                    tracked_phases[phase], wait_seconds),
                force=True)

        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_ZL_ACTION("END")
        now=time.monotonic()
        if now < decision_not_before:
            self.ZA_mega_mode5_trace(
                "TESTMODE1_SIDE_DECISION_WAIT",
                "{} side {:.1f}s remaining".format(
                    tracked_phases[phase],
                    max(0.0, decision_not_before - now)))
            return "handled"

        angle_key=(
            "RED_SIDE_TRANSITION_DODGE_ANGLE"
            if phase == "RED_COVER_ATTACK" else
            "BLUE_SIDE_TRANSITION_DODGE_ANGLE")
        dodge_angle=float(settings.get(angle_key, 90.0))
        dodge_repeat=max(1, int(settings.get(
            "SIDE_TRANSITION_DODGE_REPEAT", 2)))
        self.ZA_MOVE_LStick(
            dir1,dir2,dir3,dir4,
            Direction(Stick.LEFT, dodge_angle, 1.0),
            "RELOAD", force_direction=True)
        self.pressRep(
            Button.Y, repeat=dodge_repeat, duration=0.04,
            wait=0.0, interval=0.12)
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_ZL_ACTION("")
        post_wait=max(0.0, float(settings.get(
            "SIDE_TRANSITION_POST_DODGE_WAIT_SECONDS", 3.0)))
        self.wait(post_wait)

        direction=self.ZA_mega_mode5_colored_enemy_direction(
            allow_resume=True, refresh_frame=True)
        stable_color=(str(getattr(
            self, "_za_mega_colored_enemy_color", "") or "").lower()
            if isinstance(direction, Direction) else "")
        observed_color=str(getattr(
            self, "_za_mega_colored_enemy_observed_color", "") or "").lower()
        blue_visible=(
            stable_color == "blue" or observed_color == "blue")
        red_visible=(
            stable_color == "red" or observed_color == "red")
        # 固有4技ではなく、通常技のC+／C+_LOWだけを遷移確認に使う。
        skill_ready=self.ZA_mega_mode5_skill_attack_ready()
        completed_sets=int(getattr(
            self, "_za_mega_testmode1_side_strong_sets", 0))
        transition_trigger=(
            "{} strong-light sets".format(required)
            if completed_sets >= required else
            "{:.0f}s side timeout".format(timeout_seconds))
        self.ZA_mega_mode5_trace(
            "TESTMODE1_SIDE_DECISION_CHECK",
            "{}; {} side roll {:.0f}deg x{}; wait {:.1f}s; "
            "blue={} red={} normal_skill={}".format(
                transition_trigger, tracked_phases[phase],
                dodge_angle, dodge_repeat, post_wait,
                blue_visible, red_visible, skill_ready),
            force=True)

        if phase == "COVER_ATTACK" and not skill_ready and not blue_visible:
            self._za_mega_testmode1_phase="MOVE_TO_RED_COVER"
            self._za_mega_testmode1_returned_to_blue=False
            self._za_mega_testmode1_premove_due=False
            self.ZA_mega_mode5_testmode1_side_cycle_reset(
                "MOVE_TO_RED_COVER")
            self.ZA_mega_mode5_trace(
                "TESTMODE1_BLUE_TO_RED_READY",
                "{}; blue absent and normal C+ absent".format(
                    transition_trigger),
                force=True)
            return "handled"

        if phase == "RED_COVER_ATTACK" and not skill_ready and not red_visible:
            if blue_visible:
                self._za_mega_testmode1_phase="BLUE_CHASE_ATTACK"
                self._za_mega_testmode1_returned_to_blue=True
                self._za_mega_testmode1_premove_due=False
                self.ZA_mega_mode5_testmode1_side_cycle_reset(
                    "BLUE_CHASE_ATTACK")
                self.ZA_mega_mode5_attack_watchdog_reset()
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_RED_TO_BLUE_CHASE",
                    "red absent, blue visible and normal C+ absent; "
                    "resume view/move/attack",
                    force=True)
                return "handled"
            self.ZA_mega_mode5_testmode1_enter_free_run(
                "red absent, blue absent and normal C+ absent after "
                "{}".format(transition_trigger))
            return "handled"

        if phase == "BLUE_CHASE_ATTACK" and not blue_visible:
            self.ZA_mega_mode5_testmode1_enter_free_run(
                "returned blue absent after {}".format(
                    transition_trigger))
            return "handled"

        self.ZA_mega_mode5_testmode1_enter_free_run(
            "{} side condition not met after {}".format(
                phase, transition_trigger))
        return "handled"

    def ZA_mega_mode5_testmode1_enter_legacy(self, reason):
        """通常mode5をBLACK_COMMENT／SELECTまで維持する。"""
        if not getattr(self, "_za_mega_testmode1_enabled", False):
            return False
        resume_free_run_after_charge=bool(
            getattr(self, "_za_mega_mode5_free_run_active", False)
            and str(getattr(
                self, "_za_mega_testmode1_phase_before_charge", ""))
            == "FREE_RUN")
        already_latched=bool(getattr(
            self, "_za_mega_testmode1_legacy_until_reset", False))
        self._za_mega_testmode1_legacy_until_reset=True
        self._za_mega_testmode1_reinitialize_pending=False
        self._za_mega_testmode1_phase="LEGACY_COMBAT"
        self._za_mega_testmode1_resume_hp="LEGACY"
        self._za_mega_testmode1_enemy_check_retry_at=0.0
        self._za_mega_testmode1_red_only_since=0.0
        self._za_mega_testmode1_red_only_last_seen=0.0
        self._za_mega_testmode1_red_only_confirmations=0
        self._za_mega_testmode1_blue_last_seen_at=0.0
        self._za_mega_testmode1_red_premove_block_until=0.0
        self._za_mega_testmode1_red_premove_waiting_strong_light=False
        self._za_mega_testmode1_blue_return_since=0.0
        self._za_mega_testmode1_blue_return_last_seen=0.0
        self._za_mega_testmode1_blue_return_confirmations=0
        self._za_mega_testmode1_red_cover_no_enemy_since=0.0
        self._za_mega_testmode1_red_cover_no_enemy_confirmations=0
        self._za_mega_testmode1_existing_charge_latched=False
        if not resume_free_run_after_charge:
            self._za_mega_testmode1_phase_before_charge=""
        self._za_mega_testmode1_warning_cycle_active=False
        self._za_mega_testmode1_warning_cycle_saw_strong=False
        self._za_mega_testmode1_warning_interval_active=False
        self._za_mega_testmode1_warning_interval_blue_seen=False
        self._za_mega_testmode1_warning_red_pending=False
        self._za_mega_testmode1_red_cover_move_not_before=0.0
        self.ZA_mega_mode5_testmode1_side_cycle_reset("LEGACY_COMBAT")
        if not already_latched:
            self.ZA_mega_mode5_trace(
                "TESTMODE1_LEGACY_LATCH",
                "{}; use existing mode5 until BLACK_COMMENT/SELECT".format(
                    reason),
                force=True)
        return True

    def ZA_mega_mode5_testmode1_reset_for_selection(self, reason):
        """敗北Comment／選択肢で次ターゲット用TESTMODE1を再準備する。"""
        remember_phase=getattr(
            self, "ZA_mega_mode5_remember_recent_combat_phase", None)
        if callable(remember_phase):
            remember_phase()
        watchdog_reset=getattr(
            self, "ZA_mega_mode5_attack_watchdog_reset", None)
        if callable(watchdog_reset):
            watchdog_reset()
        self.ZA_mega_mode5_field_wait_reset()
        self._za_mega_mode5_event_attack_wait_field=False
        self._za_mega_mode5_event_attack_pending_from_name_lockon=False
        self._za_mega_mode5_event_name_ui_missing_latched=False
        self._za_mega_mode5_event_name_ui_missing_clear_since=0.0
        self._za_mega_mode5_x_menu_b_attempts=0
        if not getattr(self, "_za_mega_testmode1_enabled", False):
            return False
        # 再戦選択へ入った時だけ、FREE_RUNと緑床／予兆の途中状態を
        # 完全に破棄する。次のFIELD復帰で新しい戦闘として初期化する。
        self._za_mega_mode5_free_run_active=False
        self._za_mega_last_charge_state="IDLE"
        self._za_mega_last_charge_check_retry_at=0.0
        self._za_mega_last_charge_search_deadline=0.0
        self._za_mega_last_charge_cooldown_until=0.0
        self._za_mega_last_charge_skip_count=0
        self._za_mega_last_charge_attack_suspended=False
        self._za_mega_z_guard_active=False
        self._za_mega_z_guard_holding=False
        self._za_mega_z_guard_hold_until=0.0
        self._za_mega_z_guard_hold_until_disappears=False
        self._za_mega_z_guard_normal_hold_completed=False
        self._za_mega_z_guard_on_green_count=0
        self._za_mega_z_guard_skip_current_floor=False
        self._za_mega_z_guard_skip_last_seen=0.0
        self._za_mega_z_guard_direction=None
        self._za_mega_z_guard_direction_until=0.0
        self._za_mega_testmode1_legacy_until_reset=False
        self._za_mega_testmode1_reinitialize_pending=True
        self._za_mega_testmode1_resume_hp="PENDING"
        self._za_mega_testmode1_phase="WAIT_RESUME"
        self._za_mega_testmode1_premove_due=False
        self._za_mega_testmode1_hp_fill_ratio=0.0
        self._za_mega_testmode1_hp_color="NONE"
        self._za_mega_testmode1_hp_frame=None
        self._za_mega_testmode1_enemy_check_retry_at=0.0
        self._za_mega_testmode1_red_only_since=0.0
        self._za_mega_testmode1_red_only_last_seen=0.0
        self._za_mega_testmode1_red_only_confirmations=0
        self._za_mega_testmode1_blue_last_seen_at=0.0
        self._za_mega_testmode1_red_premove_block_until=0.0
        self._za_mega_testmode1_red_premove_waiting_strong_light=False
        self._za_mega_testmode1_blue_return_since=0.0
        self._za_mega_testmode1_blue_return_last_seen=0.0
        self._za_mega_testmode1_blue_return_confirmations=0
        self._za_mega_testmode1_red_cover_no_enemy_since=0.0
        self._za_mega_testmode1_red_cover_no_enemy_confirmations=0
        self._za_mega_testmode1_existing_charge_latched=False
        self._za_mega_testmode1_phase_before_charge=""
        self._za_mega_testmode1_warning_cycle_active=False
        self._za_mega_testmode1_warning_cycle_saw_strong=False
        self._za_mega_testmode1_warning_interval_active=False
        self._za_mega_testmode1_warning_interval_blue_seen=False
        self._za_mega_testmode1_warning_red_pending=False
        self._za_mega_testmode1_red_cover_move_not_before=0.0
        self._za_mega_testmode1_returned_to_blue=False
        side_cycle_reset=getattr(
            self, "ZA_mega_mode5_testmode1_side_cycle_reset", None)
        if callable(side_cycle_reset):
            side_cycle_reset("WAIT_RESUME")
        self.ZA_mega_mode5_trace(
            "TESTMODE1_SELECTION_RESET",
            "{}; next FIELD may initialize TESTMODE1".format(reason),
            force=True)
        return True

    def ZA_mega_mode5_testmode1_controls_cover(self):
        """試案の障害物待機が通常movemodeを置き換える区間を返す。"""
        return bool(
            getattr(self, "_za_mega_testmode1_enabled", False)
            and not getattr(
                self, "_za_mega_testmode1_legacy_until_reset", False)
            and not getattr(
                self, "_za_mega_testmode1_existing_charge_latched", False)
            and getattr(
                self, "_za_mega_testmode1_phase", "")
            in {"WAIT_RESUME", "FACE_BLUE", "COVER_ATTACK",
                "WAIT_RED_COVER_DELAY",
                "MOVE_TO_RED_COVER",
                "FACE_RED", "RED_COVER_ATTACK"})

    def ZA_mega_mode5_testmode1_red_only_fallback_update(self):
        """青を60秒検知できない時、赤側障害物移動へ進む。"""
        phase=str(getattr(
            self, "_za_mega_testmode1_phase", "DISABLED"))
        if (not getattr(self, "_za_mega_testmode1_enabled", False)
                or phase != "COVER_ATTACK"):
            self._za_mega_testmode1_red_only_since=0.0
            self._za_mega_testmode1_red_only_last_seen=0.0
            self._za_mega_testmode1_red_only_confirmations=0
            self._za_mega_testmode1_blue_last_seen_at=0.0
            return False

        settings=self.ZA_mega_mode5_testmode1_settings()
        now=time.monotonic()
        if now < float(getattr(
                self, "_za_mega_testmode1_enemy_check_retry_at", 0.0)):
            return False
        self._za_mega_testmode1_enemy_check_retry_at=(
            now + max(0.10, float(settings.get(
                "BLUE_ABSENCE_CHECK_INTERVAL_SECONDS", 0.30))))

        # refresh_frame=Trueで毎回新しいCameraフレームを取得する。
        # 赤や無色は青検知には含めず、青だけで60秒タイマーを戻す。
        direction=self.ZA_mega_mode5_colored_enemy_direction(
            allow_resume=True, refresh_frame=True)
        stable_color=(str(getattr(
            self, "_za_mega_colored_enemy_color", "") or "").lower()
            if isinstance(direction, Direction) else "")
        # 安定青だけでなく生の青候補も生存確認に使用する。
        observed_color=str(getattr(
            self, "_za_mega_colored_enemy_observed_color", "") or "").lower()
        if not stable_color and not observed_color:
            self.ZA_mega_mode5_trace(
                "TESTMODE1_ENEMY_OCCLUDED",
                "no red/blue in fresh frame; continue blue absence timer")
        if stable_color == "blue" or observed_color == "blue":
            previous_seen=float(getattr(
                self, "_za_mega_testmode1_blue_last_seen_at", 0.0))
            self._za_mega_testmode1_blue_last_seen_at=now
            self.ZA_mega_mode5_testmode1_warning_cycle_update("BLUE")
            had_red=bool(getattr(
                self, "_za_mega_testmode1_red_only_confirmations", 0))
            self._za_mega_testmode1_red_only_since=0.0
            self._za_mega_testmode1_red_only_last_seen=0.0
            self._za_mega_testmode1_red_only_confirmations=0
            self.ZA_mega_mode5_trace(
                "TESTMODE1_BLUE_ABSENCE_RESET",
                "blue enemy confirmed; reset absence timer after {:.1f}s".format(
                    max(0.0, now - previous_seen)
                    if previous_seen > 0.0 else 0.0))
            if had_red:
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_RED_ONLY_RESET",
                    "blue enemy confirmed; reset red-only timer",
                    force=True)
            return False

        blue_last_seen=float(getattr(
            self, "_za_mega_testmode1_blue_last_seen_at", 0.0))
        if blue_last_seen <= 0.0:
            blue_last_seen=now
            self._za_mega_testmode1_blue_last_seen_at=now
        required_seconds=max(0.0, float(settings.get(
            "BLUE_ABSENCE_FALLBACK_SECONDS", 60.0)))
        elapsed=max(0.0, now - blue_last_seen)
        self.ZA_mega_mode5_trace(
            "TESTMODE1_BLUE_ABSENCE_WAIT",
            "blue not detected {:.1f}/{:.1f}s; keep blue cover".format(
                elapsed, required_seconds))
        if elapsed >= required_seconds:
            # 既存2判定が成立しない場合も、60秒青が見えなければ
            # 赤色の成否に依存せず赤側の固定障害物経路へ移る。
            self._za_mega_testmode1_phase="MOVE_TO_RED_COVER"
            self._za_mega_testmode1_red_only_since=0.0
            self._za_mega_testmode1_red_only_last_seen=0.0
            self._za_mega_testmode1_red_only_confirmations=0
            self._za_mega_testmode1_blue_last_seen_at=0.0
            self._za_mega_testmode1_enemy_check_retry_at=0.0
            self._za_mega_testmode1_warning_cycle_active=False
            self._za_mega_testmode1_warning_cycle_saw_strong=False
            self._za_mega_testmode1_warning_interval_active=False
            self._za_mega_testmode1_warning_interval_blue_seen=False
            self._za_mega_testmode1_warning_red_pending=False
            self._za_mega_testmode1_red_cover_move_not_before=0.0
            self.ZA_mega_mode5_trace(
                "TESTMODE1_BLUE_ABSENCE_TIMEOUT",
                "blue not detected for {:.1f}s; move to red-side cover".format(
                    elapsed),
                force=True)
            return True

        color=stable_color
        burrow_grace=max(0.0, float(settings.get(
            "BLUE_BURROW_GRACE_SECONDS", 12.0)))
        if now - blue_last_seen < burrow_grace:
            self._za_mega_testmode1_red_only_since=0.0
            self._za_mega_testmode1_red_only_last_seen=0.0
            self._za_mega_testmode1_red_only_confirmations=0
            if color == "red":
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_BLUE_BURROW_GRACE",
                    "blue hidden {:.1f}/{:.1f}s; keep blue-side cover".format(
                        max(0.0, now - blue_last_seen), burrow_grace))
            return False

        last_seen=float(getattr(
            self, "_za_mega_testmode1_red_only_last_seen", 0.0))
        gap_limit=max(0.0, float(settings.get(
            "RED_ONLY_GAP_TOLERANCE_SECONDS", 10.0)))
        if color != "red":
            if last_seen <= 0.0 or now - last_seen > gap_limit:
                had_red=bool(getattr(
                    self, "_za_mega_testmode1_red_only_confirmations", 0))
                self._za_mega_testmode1_red_only_since=0.0
                self._za_mega_testmode1_red_only_last_seen=0.0
                self._za_mega_testmode1_red_only_confirmations=0
                if had_red:
                    self.ZA_mega_mode5_trace(
                        "TESTMODE1_RED_ONLY_RESET",
                        "red enemy missing for {:.1f}s; reset timer".format(
                            max(0.0, now - last_seen)),
                        force=True)
            return False

        red_since=float(getattr(
            self, "_za_mega_testmode1_red_only_since", 0.0))
        confirmations=int(getattr(
            self, "_za_mega_testmode1_red_only_confirmations", 0))
        if red_since <= 0.0 or last_seen <= 0.0 or now - last_seen > gap_limit:
            red_since=now
            confirmations=1
            self.ZA_mega_mode5_trace(
                "TESTMODE1_RED_ONLY_CHECK",
                "red enemy confirmed without blue; begin fallback timer",
                force=True)
        else:
            confirmations+=1
        self._za_mega_testmode1_red_only_since=red_since
        self._za_mega_testmode1_red_only_last_seen=now
        self._za_mega_testmode1_red_only_confirmations=confirmations

        red_required_seconds=max(0.0, float(settings.get(
            "RED_ONLY_FALLBACK_SECONDS", 3.0)))
        required_confirmations=max(1, int(settings.get(
            "RED_ONLY_MIN_CONFIRMATIONS", 3)))
        red_elapsed=max(0.0, now - red_since)
        self.ZA_mega_mode5_trace(
            "TESTMODE1_RED_ONLY_CHECK",
            "red only {:.1f}s; confirmation {}/{}".format(
                red_elapsed, confirmations, required_confirmations))
        if (red_elapsed < red_required_seconds
                or confirmations < required_confirmations):
            return False

        self._za_mega_testmode1_phase="MOVE_TO_RED_COVER"
        self._za_mega_testmode1_red_only_since=0.0
        self._za_mega_testmode1_red_only_last_seen=0.0
        self._za_mega_testmode1_red_only_confirmations=0
        self._za_mega_testmode1_blue_last_seen_at=0.0
        self._za_mega_testmode1_enemy_check_retry_at=0.0
        self._za_mega_testmode1_warning_cycle_active=False
        self._za_mega_testmode1_warning_cycle_saw_strong=False
        self._za_mega_testmode1_warning_interval_active=False
        self._za_mega_testmode1_warning_interval_blue_seen=False
        self._za_mega_testmode1_warning_red_pending=False
        self._za_mega_testmode1_red_cover_move_not_before=0.0
        self.ZA_mega_mode5_trace(
            "TESTMODE1_RED_COVER_READY",
            "red only {:.1f}s ({} checks); move to red-side cover".format(
                red_elapsed, confirmations),
            force=True)
        return True

    def ZA_mega_mode5_testmode1_blue_return_update(self):
        """赤側で青の再出現または長時間の敵不在を確認して通常へ戻す。"""
        phase=str(getattr(
            self, "_za_mega_testmode1_phase", "DISABLED"))
        if (not getattr(self, "_za_mega_testmode1_enabled", False)
                or phase != "RED_COVER_ATTACK"):
            self._za_mega_testmode1_blue_return_since=0.0
            self._za_mega_testmode1_blue_return_last_seen=0.0
            self._za_mega_testmode1_blue_return_confirmations=0
            self._za_mega_testmode1_red_cover_no_enemy_since=0.0
            self._za_mega_testmode1_red_cover_no_enemy_confirmations=0
            return False

        settings=self.ZA_mega_mode5_testmode1_settings()
        if not bool(settings.get(
                "BLUE_RETURN_TO_LEGACY_ENABLED", False)):
            self._za_mega_testmode1_blue_return_since=0.0
            self._za_mega_testmode1_blue_return_last_seen=0.0
            self._za_mega_testmode1_blue_return_confirmations=0
            self._za_mega_testmode1_red_cover_no_enemy_since=0.0
            self._za_mega_testmode1_red_cover_no_enemy_confirmations=0
            return False
        now=time.monotonic()
        if now < float(getattr(
                self, "_za_mega_testmode1_enemy_check_retry_at", 0.0)):
            return False
        self._za_mega_testmode1_enemy_check_retry_at=(
            now + max(0.10, float(settings.get(
                "BLUE_RETURN_CHECK_INTERVAL_SECONDS", 0.30))))
        direction=self.ZA_mega_mode5_colored_enemy_direction(
            allow_resume=True, refresh_frame=True)
        stable_color=(str(getattr(
            self, "_za_mega_colored_enemy_color", "") or "").lower()
            if isinstance(direction, Direction) else "")
        observed_color=str(getattr(
            self, "_za_mega_colored_enemy_observed_color", "") or "").lower()
        # 生の青候補1回ではなく、色helperが位置・面積を連続確認した
        # 確定青だけを通常mode5への復帰条件に使用する。
        color=stable_color
        last_seen=float(getattr(
            self, "_za_mega_testmode1_blue_return_last_seen", 0.0))
        gap_limit=max(0.0, float(settings.get(
            "BLUE_RETURN_GAP_TOLERANCE_SECONDS", 10.0)))
        if color == "blue":
            # 赤と青は同時に存在するため、途中に確定赤が挟まっても
            # 青確認は取り消さない。最後の確定青からの時間だけを見る。
            blue_since=float(getattr(
                self, "_za_mega_testmode1_blue_return_since", 0.0))
            confirmations=int(getattr(
                self, "_za_mega_testmode1_blue_return_confirmations", 0))
            if (blue_since <= 0.0 or last_seen <= 0.0
                    or now - last_seen > gap_limit):
                blue_since=now
                confirmations=1
            else:
                confirmations+=1
            self._za_mega_testmode1_blue_return_since=blue_since
            self._za_mega_testmode1_blue_return_last_seen=now
            self._za_mega_testmode1_blue_return_confirmations=confirmations
            self._za_mega_testmode1_red_cover_no_enemy_since=0.0
            self._za_mega_testmode1_red_cover_no_enemy_confirmations=0
            required_seconds=max(0.0, float(settings.get(
                "BLUE_RETURN_SECONDS", 1.0)))
            required_confirmations=max(1, int(settings.get(
                "BLUE_RETURN_MIN_CONFIRMATIONS", 3)))
            elapsed=max(0.0, now - blue_since)
            self.ZA_mega_mode5_trace(
                "TESTMODE1_BLUE_RETURN_CHECK",
                "blue {:.1f}s; confirmation {}/{}".format(
                    elapsed, confirmations, required_confirmations))
            if (elapsed >= required_seconds
                    and confirmations >= required_confirmations):
                self.ZA_mega_mode5_testmode1_enter_legacy(
                    "BLUE_REAPPEARED")
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_BLUE_RETURN_LEGACY",
                    "blue {:.1f}s ({} checks); resume existing mode5".format(
                        elapsed, confirmations),
                    force=True)
                return True
            return False

        # 生候補を含めて赤か青が見えていれば、障害物による完全遮蔽では
        # ないので「両方見えない」保険だけを初期化する。確定赤は青の
        # 不在証明ではないため、上の青確認回数はここでは破棄しない。
        any_enemy_visible=(
            color in {"red", "blue"}
            or observed_color in {"red", "blue"})
        if any_enemy_visible:
            self._za_mega_testmode1_red_cover_no_enemy_since=0.0
            self._za_mega_testmode1_red_cover_no_enemy_confirmations=0
        else:
            no_enemy_since=float(getattr(
                self, "_za_mega_testmode1_red_cover_no_enemy_since", 0.0))
            no_enemy_confirmations=int(getattr(
                self,
                "_za_mega_testmode1_red_cover_no_enemy_confirmations", 0))
            if no_enemy_since <= 0.0:
                no_enemy_since=now
                no_enemy_confirmations=1
            else:
                no_enemy_confirmations+=1
            self._za_mega_testmode1_red_cover_no_enemy_since=no_enemy_since
            self._za_mega_testmode1_red_cover_no_enemy_confirmations=(
                no_enemy_confirmations)
            no_enemy_seconds=max(0.0, float(settings.get(
                "RED_COVER_NO_ENEMY_RETURN_SECONDS", 60.0)))
            no_enemy_min=max(1, int(settings.get(
                "RED_COVER_NO_ENEMY_MIN_CONFIRMATIONS", 5)))
            no_enemy_elapsed=max(0.0, now - no_enemy_since)
            self.ZA_mega_mode5_trace(
                "TESTMODE1_RED_COVER_NO_ENEMY_CHECK",
                "no red/blue {:.1f}s; confirmation {}/{}".format(
                    no_enemy_elapsed, no_enemy_confirmations, no_enemy_min))
            if (no_enemy_elapsed >= no_enemy_seconds
                    and no_enemy_confirmations >= no_enemy_min):
                self.ZA_mega_mode5_testmode1_enter_legacy(
                    "RED_COVER_NO_ENEMY")
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_RED_COVER_NO_ENEMY_LEGACY",
                    "no red/blue {:.1f}s ({} checks); retry existing mode5".format(
                        no_enemy_elapsed, no_enemy_confirmations),
                    force=True)
                return True

        if last_seen <= 0.0 or now - last_seen > gap_limit:
            self._za_mega_testmode1_blue_return_since=0.0
            self._za_mega_testmode1_blue_return_last_seen=0.0
            self._za_mega_testmode1_blue_return_confirmations=0
        return False

    def ZA_mega_mode5_testmode1_resume_update(
            self, dir1, dir2, dir3, dir4, see_r):
        """再開経路の準備完了後、青敵側の障害物へ移動する試案。"""
        if not getattr(self, "_za_mega_testmode1_enabled", False):
            return None
        settings=self.ZA_mega_mode5_testmode1_settings()
        phase=str(getattr(
            self, "_za_mega_testmode1_phase", "DISABLED"))
        if phase == "HP75_EXISTING":
            return None
        now=time.monotonic()
        if phase == "CLASSIFY_HP":
            if now < float(getattr(
                    self, "_za_mega_testmode1_hp_retry_at", 0.0)):
                self.wait(0.1)
                return True
            resume_hp=self.ZA_mega_mode5_hp_resume_mode()
            remaining=max(0, int(getattr(
                self, "_za_mega_testmode1_hp_checks_remaining", 0)) - 1)
            self._za_mega_testmode1_hp_checks_remaining=remaining
            self._za_mega_testmode1_hp_retry_at=now + 0.25
            if resume_hp == "UNKNOWN" and remaining > 0:
                self.ZA_mega_mode5_trace(
                    "HP_UNKNOWN",
                    "testmode1 wait for visible HP bar ({}/4)".format(
                        4 - remaining))
                self.wait(0.1)
                return True
            if resume_hp == "UNKNOWN":
                # 判定不能のまま棒立ちにせず、試案側のOTHERとして進める。
                resume_hp="OTHER"
            self._za_mega_testmode1_resume_hp=resume_hp
            if resume_hp == "HP75":
                self._za_mega_testmode1_phase="HP75_EXISTING"
                self._za_mega_mode5_green_priority_checks_remaining=(
                    max(0, int(settings["INITIAL_GREEN_CHECK_COUNT"]))
                    if self._za_mega_z_guard_enabled else 0)
                self.ZA_mega_mode5_trace(
                    "HP75",
                    "testmode1 start fixed 90deg resume without green check",
                    force=True)
                return None
            self._za_mega_testmode1_phase="MOVE_TO_COVER"
            self.ZA_mega_mode5_trace(
                "HP_OTHER",
                "testmode1 skip green/90deg leg; direct fixed cover route",
                force=True)
            phase="MOVE_TO_COVER"

        if phase != "MOVE_TO_COVER":
            return True
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_ZL_ACTION("END")
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        resume_hp=str(getattr(
            self, "_za_mega_testmode1_resume_hp", "OTHER"))
        if resume_hp == "HP75":
            # HP75は先に90度の固定初期移動を行うため、その終了位置から
            # 手動設定の固定角度で青側障害物へ回る。
            # 移動後も手動設定角度へ向き、障害物を挟んで攻撃を開始する。
            blue_direction=0
            blue_found=False
            cover_angle=float(settings["HP75_COVER_MOVE_ANGLE"])
            face_angle=float(settings["HP75_FACE_ANGLE"])
            cover_seconds=float(settings["HP75_COVER_MOVE_SECONDS"])
            cover_detection="HP75_BLUE_COVER_FIXED"
        else:
            # HP75以外も青色の画面位置では角度を変えない。再開地点から
            # 青側障害物へ到達するための固定経路をそのまま実行する。
            cover_angle=float(settings["OTHER_COVER_MOVE_ANGLE"])
            face_angle=float(settings["OTHER_FACE_ANGLE"])
            cover_seconds=float(settings["OTHER_COVER_MOVE_SECONDS"])
            cover_detection="OTHER_BLUE_COVER_FIXED"

        self._za_mega_testmode1_cover_angle=cover_angle
        self._za_mega_testmode1_face_angle=face_angle
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        self.press(
            Direction(Stick.LEFT, cover_angle, 1.0),
            duration=cover_seconds, wait=0.0)
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self._za_mega_mode5_initial_phase_active=False
        self._za_mega_mode5_green_priority_checks_remaining=0
        self._za_mega_testmode1_phase="FACE_BLUE"
        self.ZA_mega_mode5_set_start_flag(
            3,
            cover_detection,
            "testmode1 cover move angle={:.0f} {:.1f}s; "
            "face={:.0f}; FIELD input next".format(
                cover_angle, cover_seconds, face_angle))
        return True

    def ZA_mega_mode5_testmode1_combat_update(
            self, dir1, dir2, dir3, dir4, see_r):
        """障害物から青敵へL正面化し、攻撃間に非ロックオンYを行う。"""
        settings=self.ZA_mega_mode5_testmode1_settings()
        phase=str(getattr(
            self, "_za_mega_testmode1_phase", "FACE_BLUE"))
        side_transition_action=(
            self.ZA_mega_mode5_testmode1_side_transition_update(
                dir1,dir2,dir3,dir4,see_r))
        if side_transition_action == "handled":
            return "handled"
        if not self.ZA_mega_mode5_testmode1_controls_cover():
            if (getattr(self, "_za_mega_testmode1_enabled", False)
                    and getattr(
                        self, "_za_mega_testmode1_phase", "")
                    == "EXISTING_GREEN"):
                if self.ZA_mega_z_guard_update(dir1,dir2,dir3,dir4):
                    self.ZA_mega_mode5_trace(
                        "GREEN_FLOOR",
                        "testmode1 temporarily use existing green action")
                    return "handled"
                self._za_mega_testmode1_phase="WAIT_RESUME"
                self._za_mega_testmode1_resume_hp="PENDING"
                self.ZA_mega_mode5_set_start_flag(
                    0, "GREEN_FLOOR_COMPLETE",
                    "testmode1 restart from HP classification",
                )
                return "restart"
            return "none"

        now=time.monotonic()
        if phase == "WAIT_RESUME":
            # RETRY_SELECTION後のFIELD安定確認中は、通常movemodeへ
            # フォールスルーして最後の左右方向へ移動し続けない。
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_ZL_ACTION("END")
            self.ZA_mega_mode5_trace(
                "WAIT_RESUME_HOLD",
                "stop movement while stable FIELD resumes TESTMODE1")
            return "handled"
        if phase == "WAIT_RED_COVER_DELAY":
            # 2組目の強い光が消えても5秒は青側障害物に留まる。
            # 期限後は追加の上下入力を行わず、赤側障害物へ移動する。
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_ZL_ACTION("END")
            move_not_before=float(getattr(
                self, "_za_mega_testmode1_red_cover_move_not_before", 0.0))
            if now < move_not_before:
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_WARNING_RED_COVER_WAIT",
                    "wait {:.1f}s at blue cover".format(
                        max(0.0, move_not_before - now)))
                return "handled"
            self._za_mega_testmode1_red_cover_move_not_before=0.0
            self._za_mega_testmode1_phase="MOVE_TO_RED_COVER"
            phase="MOVE_TO_RED_COVER"
            self.ZA_mega_mode5_trace(
                "TESTMODE1_WARNING_RED_COVER_READY",
                "5.0s delay complete; begin fixed red-cover move",
                force=True)
        if phase == "MOVE_TO_RED_COVER":
            # 強い光2セット後の判定用Y×2＋3秒待機とは別に、
            # 従来の赤側固定経路の開始点調整を保つ。青側障害物へ
            # Yを3回当てて位置を揃えた後、赤側障害物へ固定移動する。
            cover_angle=float(settings["RED_COVER_MOVE_ANGLE"])
            cover_seconds=float(settings["RED_COVER_MOVE_SECONDS"])
            face_angle=float(settings["RED_FACE_ANGLE"])
            anchor_angle=float(settings[
                "BLUE_TO_RED_ANCHOR_DODGE_ANGLE"])
            anchor_repeat=max(1, int(settings[
                "BLUE_TO_RED_ANCHOR_DODGE_REPEAT"]))
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_ZL_ACTION("END")
            self.ZA_MOVE_LStick(
                dir1,dir2,dir3,dir4,
                Direction(Stick.LEFT, anchor_angle, 1.0),
                "RELOAD", force_direction=True)
            self.pressRep(
                Button.Y, repeat=anchor_repeat, duration=0.04,
                wait=0.0, interval=0.12)
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_mega_mode5_trace(
                "TESTMODE1_BLUE_COVER_ANCHOR",
                "unlock; Y x{} at {:.0f}deg to fix red-route start".format(
                    anchor_repeat, anchor_angle),
                force=True)
            self.press(
                Direction(Stick.LEFT, cover_angle, 1.0),
                duration=cover_seconds, wait=0.0)
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self._za_mega_testmode1_cover_angle=cover_angle
            self._za_mega_testmode1_face_angle=face_angle
            self._za_mega_testmode1_phase="FACE_RED"
            self.ZA_mega_mode5_trace(
                "TESTMODE1_RED_COVER_MOVE",
                "fixed move {:.0f}deg {:.1f}s; next face red {:.0f}deg "
                "then L and arrival adjustment".format(
                    cover_angle, cover_seconds, face_angle),
                force=True)
            return "handled"

        if phase in {"FACE_BLUE", "FACE_RED"}:
            # 障害物へ入った後も一時的な色位置で固定角度を上書きせず、
            # 青側／赤側それぞれの保存角度へ向いてからLを入力する。
            resume_hp=str(getattr(
                self, "_za_mega_testmode1_resume_hp", "OTHER"))
            face_angle=float(getattr(
                self, "_za_mega_testmode1_face_angle", 90.0))
            self._za_mega_testmode1_face_angle=face_angle
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            self.ZA_ZL_ACTION("END")
            self.ZA_MOVE_LStick(
                dir1,dir2,dir3,dir4,
                Direction(Stick.LEFT, face_angle, 1.0),
                "RELOAD", force_direction=True)
            self.wait(max(
                0.0, float(settings["FACE_DIRECTION_SECONDS"])))
            self.pressRep(
                Button.L, repeat=1, duration=0.04,
                wait=0.0, interval=0.1)
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            red_cover=phase == "FACE_RED"
            if red_cover:
                # 赤側を160度へ向いてLで視点を合わせた後、その視点を
                # 基準に到着位置の90度短距離移動を2回行う。
                arrival_angle=float(settings[
                    "BLUE_TO_RED_ARRIVAL_MOVE_ANGLE"])
                arrival_seconds=max(0.0, float(settings[
                    "BLUE_TO_RED_ARRIVAL_MOVE_SECONDS"]))
                arrival_repeat=max(0, int(settings[
                    "BLUE_TO_RED_ARRIVAL_MOVE_REPEAT"]))
                for _ in range(arrival_repeat):
                    self.press(
                        Direction(Stick.LEFT, arrival_angle, 1.0),
                        duration=arrival_seconds, wait=0.5)
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_RED_COVER_ARRIVAL",
                    "after L: move {:.0f}deg {:.1f}s x{}".format(
                        arrival_angle, arrival_seconds, arrival_repeat),
                    force=True)
            self.ZA_ZL_ACTION("")
            self._za_mega_testmode1_phase=(
                "RED_COVER_ATTACK" if red_cover else "COVER_ATTACK")
            # 画像検知に2.4秒以上かかっても、障害物到着後の最初の
            # 攻撃では270度の攻撃前移動をY回避より先に必ず通す。
            self._za_mega_testmode1_premove_due=True
            if not red_cover:
                # 青側へ向いてLを入れた時点を潜行猶予の起点にする。
                # 色が最初の数周で取れなくても即赤側へ切り替えない。
                self._za_mega_testmode1_blue_last_seen_at=time.monotonic()
            self._za_mega_testmode1_next_dodge_at=(
                time.monotonic()
                + max(0.0, float(
                    settings["COVER_DODGE_INTERVAL_SECONDS"])))
            self.ZA_mega_mode5_trace(
                ("RED_FIXED_FACE" if red_cover
                 else "HP75_FIXED_FACE" if resume_hp == "HP75"
                 else "OTHER_FIXED_FACE"),
                "testmode1 move {:.0f}deg then Button.L; lockon attack".format(
                    face_angle),
                force=True)
            return "handled"

        # 障害物位置から通常movemodeへ戻ると敵へ接近して遮蔽物を離れる。
        # 通常は障害物内から攻撃し、2.4秒ごとに前方90度へ
        # Yを2回送って再ロックオンする。「力をためている」から
        # 強い光後7秒の間は通常攻撃／攻撃前移動も止め、このY×2だけを
        # 継続する。緑床探索・遠距離回避は実フリーランだけで行う。
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        premove_due=bool(getattr(
            self, "_za_mega_testmode1_premove_due", False))
        before_dodge=bool(now < float(getattr(
            self, "_za_mega_testmode1_next_dodge_at", 0.0)))
        if before_dodge or premove_due:
            block_until=float(getattr(
                self,
                "_za_mega_testmode1_red_premove_block_until", 0.0))
            waiting_strong_light=bool(getattr(
                self,
                "_za_mega_testmode1_red_premove_waiting_strong_light",
                False))
            premove_blocked=(
                phase in {"COVER_ATTACK", "RED_COVER_ATTACK"}
                and (waiting_strong_light or now < block_until))
            if premove_blocked:
                self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
                self.ZA_mega_mode5_trace(
                    ("TESTMODE1_RED_ATTACK_PREMOVE_SKIP"
                     if phase == "RED_COVER_ATTACK" else
                     "TESTMODE1_BLUE_ATTACK_PREMOVE_SKIP"),
                    ("wait for strong light before 7s cooldown"
                     if waiting_strong_light else
                     "strong-light cooldown {:.1f}s remaining".format(
                         max(0.0, block_until - now))))
                # 回避期限を過ぎている場合は、予兆中の270度移動だけを
                # 保留して下のY回避へ進む。予兆解除後もdueを保持する。
                if not before_dodge:
                    pass
                else:
                    if getattr(self, "ZL_state", 0) == 0:
                        self.ZA_ZL_ACTION("")
                    # 「力をためている」から強い光後の猶予までは、通常攻撃へ
                    # 戻さず障害物方向の定期Yローリングだけを待つ。
                    return "handled"
            elif phase == "RED_COVER_ATTACK":
                self.wait(settings["RED_ATTACK_PREMOVE_STAY_SECONDS"])
                move_angle=float(settings[
                    "RED_ATTACK_PREMOVE_ANGLE"])
                move_angle_seconds=float(settings[
                    "RED_ATTACK_PREMOVE_ANGLE_SECONDS"])
                self.press(
                    Direction(Stick.LEFT, move_angle, 1.0),
                    duration=move_angle_seconds, wait=0.5)
                self._za_mega_testmode1_premove_due=False
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_RED_ATTACK_PREMOVE",
                    "move {:.0f}deg for {:.1f}s before attack".format(
                        move_angle, move_angle_seconds))
                self.wait(settings["RED_ATTACK_PREMOVE_STAY_SECONDS2"])
                #TODO 方向を向くだけの調整 
                move_angle=float(settings[
                    "RED_ATTACK_PREMOVE_ANGLE2"])
                move_angle_seconds=float(settings[
                    "RED_ATTACK_PREMOVE_ANGLE_SECONDS2"])
                
                #技表示を確認せず、他動作に影響しないA→Bで攻撃
                self.ZA_ZL_ACTION("")
                self.wait(0.2)
                self.press(Button.A, wait=0.1)
                self.press(Button.B, wait=0.1)
                note_attack=getattr(
                    self, "ZA_mega_mode5_note_attack_input", None)
                if callable(note_attack):
                    # Unconfirmed cover A/B must not reset the no-attack timer.
                    pass
                self.ZA_ZL_ACTION("END")
                
                self.press(
                    Direction(Stick.LEFT, move_angle, 1.0),
                    duration=move_angle_seconds, wait=0.5)
                
            elif phase == "COVER_ATTACK":
                self.wait(settings["BLUE_ATTACK_PREMOVE_STAY_SECONDS"])
                move_angle=float(settings[
                    "BLUE_ATTACK_PREMOVE_ANGLE"])
                move_angle_seconds=float(settings[
                    "BLUE_ATTACK_PREMOVE_ANGLE_SECONDS"])
                self.press(
                    Direction(Stick.LEFT, move_angle, 1.0),
                    duration=move_angle_seconds, wait=0.5)
                self._za_mega_testmode1_premove_due=False
                self.ZA_mega_mode5_trace(
                    "TESTMODE1_BLUE_ATTACK_PREMOVE",
                    "move {:.0f}deg for {:.1f}s before attack".format(
                        move_angle, move_angle_seconds))
                self.wait(settings["BLUE_ATTACK_PREMOVE_STAY_SECONDS2"])
                #TODO 方向を向くだけの調整 
                move_angle=float(settings[
                    "BLUE_ATTACK_PREMOVE_ANGLE2"])
                move_angle_seconds=float(settings[
                    "BLUE_ATTACK_PREMOVE_ANGLE_SECONDS2"])
                
                #技表示を確認せず、他動作に影響しないA→Bで攻撃
                self.ZA_ZL_ACTION("")
                self.wait(0.2)
                self.press(Button.A, wait=0.1)
                self.press(Button.B, wait=0.1)
                note_attack=getattr(
                    self, "ZA_mega_mode5_note_attack_input", None)
                if callable(note_attack):
                    # Unconfirmed cover A/B must not reset the no-attack timer.
                    pass
                self.ZA_ZL_ACTION("END")
                
                self.press(
                    Direction(Stick.LEFT, move_angle, 1.0),
                    duration=move_angle_seconds, wait=0.5)

            else:
                self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            if not premove_blocked:
                if getattr(self, "ZL_state", 0) == 0:
                    self.ZA_ZL_ACTION("")
                return "attack"

        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_ZL_ACTION("END")
        self.ZA_MOVE_LStick(
            dir1,dir2,dir3,dir4,
            Direction(
                Stick.LEFT,
                float(settings["COVER_DODGE_ANGLE"]), 1.0),
            "RELOAD", force_direction=True)
        self.pressRep(
            Button.Y,
            repeat=max(1, int(settings["COVER_DODGE_REPEAT"])),
            duration=0.04,
            wait=0.0, interval=0.12)
        self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
        self.ZA_ZL_ACTION("")
        self._za_mega_testmode1_next_dodge_at=(
            time.monotonic()
            + max(0.0, float(
                settings["COVER_DODGE_INTERVAL_SECONDS"])))
        self._za_mega_testmode1_premove_due=True
        self.ZA_mega_mode5_trace(
            ("TESTMODE1_RED_COVER" if phase == "RED_COVER_ATTACK"
             else "TESTMODE1_BLUE_COVER"),
            "unlock; Y x{} toward obstacle; relock".format(
                max(1, int(settings["COVER_DODGE_REPEAT"]))),
            force=True)
        return "handled"

    def ZA_mega_mode5_testmode1_finish_hp75_initial(self, detection):
        """HP75専用の初期回避後、青側障害物経路へ合流する。"""
        if not (getattr(self, "_za_mega_testmode1_enabled", False)
                and not getattr(
                    self, "_za_mega_testmode1_legacy_until_reset", False)
                and getattr(
                    self, "_za_mega_testmode1_resume_hp", "") == "HP75"):
            return False
        self._za_mega_testmode1_phase="MOVE_TO_COVER"
        self._za_mega_testmode1_blue_scan_attempts=0
        self._za_mega_mode5_initial_phase_active=False
        self._za_mega_mode5_green_priority_checks_remaining=0
        self._za_mega_mode5_post_move_wait_until=0.0
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        cover_angle=float(self.ZA_mega_mode5_testmode1_settings()[
            "HP75_COVER_MOVE_ANGLE"])
        self.ZA_mega_mode5_transition(
            "BLUE_COVER_SEARCH",
            "HP75 90deg initial movement complete; "
            "fixed {:.0f}deg cover route".format(cover_angle))
        self.ZA_mega_mode5_trace(
            detection,
            "HP75 initial movement complete; "
            "move {:.0f}deg to blue-side cover".format(cover_angle),
            force=True)
        return True

    def ZA_mega_mode5_begin_resume(
            self, z_guard_enabled, initial_approach_seconds, see_r,
            resume_reason):
        """戦闘再開時に前ターゲット状態を破棄し、HP別開始経路へ遷移する。"""
        # 固有4技後の専用待機は、実FIELD再開を確認したここでだけ解除する。
        self._za_mega_mode5_event_attack_wait_field=False
        self._za_mega_mode5_event_attack_pending_from_name_lockon=False
        self._za_mega_mode5_event_name_ui_missing_latched=False
        self._za_mega_mode5_event_name_ui_missing_clear_since=0.0
        self.ZA_mega_mode5_marker_search_view_stop(relock=False)
        self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
        # HARD FIELD／Escapeで再戦開始を確定した時点で、直前の敗北画面と
        # 強い光2セットの途中状態を次戦へ持ち越さない。
        self._za_mega_mode5_defeat_sequence_active=False
        self._za_mega_mode5_defeat_background_since=0.0
        self._za_mega_mode5_defeat_prompt_logged=False
        self._za_mega_mode5_defeat_prompt_a_retry_at=0.0
        self._za_mega_mode5_defeat_candidate_picture=""
        self._za_mega_mode5_x_menu_b_attempts=0
        self.ZA_mega_mode5_field_wait_reset()
        side_cycle_reset=getattr(
            self, "ZA_mega_mode5_testmode1_side_cycle_reset", None)
        if callable(side_cycle_reset):
            side_cycle_reset("WAIT_RESUME")
        self._za_mega_testmode1_returned_to_blue=False
        testmode1_configured=bool(getattr(
            self, "_za_mega_testmode1_enabled", False))
        legacy_latched=bool(getattr(
            self, "_za_mega_testmode1_legacy_until_reset", False))
        reinitialize_pending=bool(getattr(
            self, "_za_mega_testmode1_reinitialize_pending", True))
        testmode1_enabled=bool(
            testmode1_configured and reinitialize_pending
            and not legacy_latched)
        retained_testmode=bool(
            testmode1_configured and not reinitialize_pending
            and not legacy_latched)
        retained_phase=str(getattr(
            self, "_za_mega_testmode1_phase", "COVER_ATTACK"))
        if retained_phase in {"WAIT_RESUME", "EXISTING_CHARGE"}:
            retained_phase=str(getattr(
                self, "_za_mega_testmode1_phase_before_charge",
                "COVER_ATTACK"))
        if retained_phase not in {
                "MOVE_TO_COVER", "FACE_BLUE", "COVER_ATTACK",
                "WAIT_RED_COVER_DELAY", "MOVE_TO_RED_COVER",
                "FACE_RED", "RED_COVER_ATTACK"}:
            retained_phase="COVER_ATTACK"
        settings=(self.ZA_mega_mode5_testmode1_settings()
                  if testmode1_enabled else None)
        resume_hp=(
            self.ZA_mega_mode5_hp_resume_mode()
            if testmode1_enabled else
            str(getattr(self, "_za_mega_testmode1_resume_hp", "OTHER"))
            if retained_testmode else "LEGACY")
        hp_frame=getattr(self, "_za_mega_testmode1_hp_frame", None)
        yellow_low_hp=self.ZA_mega_mode5_low_yellow_hp(frame=hp_frame)
        self._za_mega_mode5_low_yellow_hp_active=bool(yellow_low_hp)
        # 再開検知の瞬間は暗転や選択肢からの切替中で、
        # HPバーがまだ出ていない場合がある。初回失敗だけで
        # 通常HPに固定せず、初期移動後の待機中まで再確認する。
        self._za_mega_mode5_low_yellow_hp_checks_remaining=(
            0 if yellow_low_hp else 4)
        self._za_mega_mode5_low_yellow_hp_retry_at=(
            time.monotonic() + 0.25)
        self._za_mega_mode5_low_yellow_hp_lock_seen=False
        self._za_mega_mode5_lockon_retreating=False
        self._za_mega_testmode1_resume_hp=resume_hp
        self._za_mega_testmode1_hp_checks_remaining=(
            4 if resume_hp == "UNKNOWN" else 0)
        self._za_mega_testmode1_hp_retry_at=time.monotonic() + 0.25
        self._za_mega_testmode1_blue_scan_attempts=0
        self._za_mega_testmode1_face_attempts=0
        self._za_mega_testmode1_next_dodge_at=0.0
        self._za_mega_testmode1_premove_due=False
        self._za_mega_testmode1_enemy_check_retry_at=0.0
        self._za_mega_testmode1_red_only_since=0.0
        self._za_mega_testmode1_red_only_last_seen=0.0
        self._za_mega_testmode1_red_only_confirmations=0
        self._za_mega_testmode1_blue_last_seen_at=0.0
        self._za_mega_testmode1_red_premove_block_until=0.0
        self._za_mega_testmode1_red_premove_waiting_strong_light=False
        self._za_mega_testmode1_blue_return_since=0.0
        self._za_mega_testmode1_blue_return_last_seen=0.0
        self._za_mega_testmode1_blue_return_confirmations=0
        self._za_mega_testmode1_red_cover_no_enemy_since=0.0
        self._za_mega_testmode1_red_cover_no_enemy_confirmations=0
        self._za_mega_testmode1_existing_charge_latched=False
        self._za_mega_testmode1_warning_cycle_active=False
        self._za_mega_testmode1_warning_cycle_saw_strong=False
        self._za_mega_testmode1_warning_interval_active=False
        self._za_mega_testmode1_warning_interval_blue_seen=False
        self._za_mega_testmode1_warning_red_pending=False
        self._za_mega_testmode1_red_cover_move_not_before=0.0
        self._za_mega_testmode1_side_cycle_phase=""
        self._za_mega_testmode1_side_strong_visible=False
        self._za_mega_testmode1_side_strong_clear_since=0.0
        self._za_mega_testmode1_side_strong_sets=0
        self._za_mega_testmode1_side_decision_not_before=0.0
        self._za_mega_testmode1_side_timeout_started_at=-1.0
        self._za_mega_testmode1_returned_to_blue=False
        if testmode1_enabled:
            # TESTMODE1の固定移動はBLACK_COMMENT／SELECTの後の
            # 最初のFIELDでだけ1度初期化する。
            self._za_mega_testmode1_reinitialize_pending=False
        if not testmode1_configured:
            self._za_mega_testmode1_phase="DISABLED"
        elif legacy_latched:
            self._za_mega_testmode1_phase="LEGACY_COMBAT"
            self._za_mega_testmode1_resume_hp="LEGACY"
        elif retained_testmode:
            self._za_mega_testmode1_phase=retained_phase
            if retained_phase == "COVER_ATTACK":
                # FIELD再開で試案を初期化し直さないが、青が再び出た
                # 直後として潜行猶予だけは取り直す。
                self._za_mega_testmode1_blue_last_seen_at=time.monotonic()
        elif resume_hp == "HP75":
            self._za_mega_testmode1_phase="HP75_EXISTING"
        elif resume_hp == "OTHER":
            self._za_mega_testmode1_phase="MOVE_TO_COVER"
        else:
            self._za_mega_testmode1_phase="CLASSIFY_HP"
        # 黄色HPは初期移動角度ではなく、ロックオン後の距離維持へ使う。
        self._za_mega_mode5_initial_approach_angle=90
        if yellow_low_hp:
            print(
                "[MEGA_MODE5_HP] yellow low HP detected ratio={:.3f}; "
                "enable lockon standoff; initial move remains 90deg".format(
                    float(getattr(
                        self, "_za_mega_mode5_yellow_hp_fill_ratio", 0.0))))
        self._za_mega_mode5_view_search_block_until=0.0
        self._za_mega_mode5_view_search_block_logged=False
        use_existing_resume=bool(
            not testmode1_configured
            or (testmode1_enabled and resume_hp == "HP75"))
        self._za_mega_mode5_green_priority_checks_remaining=(
            (max(0, int(settings["INITIAL_GREEN_CHECK_COUNT"]))
             if settings is not None else 8)
            if z_guard_enabled and use_existing_resume else 0)
        direct_other_cover=bool(
            testmode1_enabled and resume_hp == "OTHER")
        self._za_mega_mode5_initial_phase_active=bool(
            (not testmode1_configured or testmode1_enabled)
            and not direct_other_cover)
        self._za_mega_mode5_initial_green_handled=False
        # OTHERは専用のMOVE_TO_COVERだけで進める。汎用の
        # 緑床判定／90度初期移動へのフォールスルーを防ぐ。
        self._za_mega_mode5_initial_approach_started=direct_other_cover
        self._za_mega_mode5_initial_approach_seconds=max(
            0.0, float(
                settings["INITIAL_NO_GREEN_MOVE_SECONDS"]
                if settings is not None else initial_approach_seconds))
        self._za_mega_mode5_initial_approach_angle=float(
            settings["INITIAL_NO_GREEN_MOVE_ANGLE"]
            if settings is not None else 90.0)
        self._za_mega_mode5_post_move_wait_until=0.0
        self._za_mega_mode5_lockon_confirmed_until=0.0
        self._za_mega_mode5_visual_lockon_until=0.0
        self._za_mega_mode5_color_field_until=0.0
        self._za_mega_colored_enemy_track_position=None
        self._za_mega_colored_enemy_track_seen_at=0.0
        self._za_mega_colored_enemy_candidate_position=None
        self._za_mega_colored_enemy_candidate_color=None
        self._za_mega_colored_enemy_candidate_pixels=0.0
        self._za_mega_colored_enemy_candidate_seen_at=0.0
        self._za_mega_colored_enemy_candidate_hits=0
        self._za_mega_mode5_battle_active=True
        self._za_mega_last_charge_state="IDLE"
        self._za_mega_last_charge_check_retry_at=0.0
        self._za_mega_last_charge_search_deadline=0.0
        self._za_mega_last_charge_cooldown_until=0.0
        self._za_mega_last_charge_skip_count=0
        self._za_mega_last_charge_attack_suspended=False

        self._za_mega_movemode_direction=None
        self._za_mega_movemode_direction_until=0.0
        self._za_mega_movemode_orbit_sign=1
        self._za_mega_movemode_orbit_until=0.0
        self._za_mega_movemode_searching=False
        self._za_mega_movemode_missing_move_retry_at=0.0
        self._za_mega_z_guard_active=False
        self._za_mega_z_guard_holding=False
        self._za_mega_z_guard_last_seen=0.0
        self._za_mega_z_guard_hold_until=0.0
        self._za_mega_z_guard_hold_until_disappears=False
        self._za_mega_z_guard_normal_hold_completed=False
        self._za_mega_z_guard_on_green_count=0
        self._za_mega_z_guard_skip_current_floor=False
        self._za_mega_z_guard_skip_last_seen=0.0
        self._za_mega_z_guard_direction=None
        self._za_mega_z_guard_direction_until=0.0
        if testmode1_configured and not testmode1_enabled:
            # FIELD再開だけでTESTMODE1の固定障害物移動を
            # やり直さない。緑床後は通常mode5、それ以外は
            # 直前の青／赤障害物phaseを維持する。
            resume_action=(
                "green-floor legacy latch; wait for BLACK_COMMENT/SELECT"
                if legacy_latched else
                "retain testmode1 phase without fixed cover replay")
            self.ZA_mega_mode5_transition(
                "FIELD_W_INPUT",
                "{} detected; {}".format(resume_reason, resume_action))
            self.ZA_mega_mode5_set_start_flag(
                3, resume_reason,
                "phase={}; {}".format(
                    self._za_mega_testmode1_phase, resume_action))
            return
        if testmode1_enabled and resume_hp == "HP75":
            resume_phase="INITIAL_APPROACH"
            resume_action=(
                "FIELD resume; skip green check; move {:.0f}deg for {:.1f}s, "
                "then cover".format(
                    self._za_mega_mode5_initial_approach_angle,
                    self._za_mega_mode5_initial_approach_seconds))
        elif testmode1_enabled and resume_hp == "OTHER":
            resume_phase="BLUE_COVER_SEARCH"
            resume_action=(
                "FIELD resume; skip green/initial 90deg; move directly "
                "{:.0f}deg for {:.1f}s to cover".format(
                    float(settings["OTHER_COVER_MOVE_ANGLE"]),
                    float(settings["OTHER_COVER_MOVE_SECONDS"])))
        elif testmode1_enabled:
            resume_phase="HP_CLASSIFY"
            resume_action="FIELD resume; classify HP before fixed movement"
        else:
            resume_phase="GREEN_PRIORITY"
            resume_action="FIELD resume; existing green/fixed movement"
        self.ZA_mega_mode5_transition(
            resume_phase,
            "{} detected; testmode1 HP={} ratio={:.3f}".format(
                resume_reason, resume_hp, float(getattr(
                    self, "_za_mega_testmode1_hp_fill_ratio", 0.0))))
        self.ZA_mega_mode5_set_start_flag(
            2, resume_reason, "resume HP={}; test phase={}; {}".format(
                resume_hp, self._za_mega_testmode1_phase, resume_action))

    def ZA_mega_mode5_begin_post_move_wait(
            self, detection, wait_seconds=2.0):
        """開始移動後の待機を開始する。HP75試案中は視点も止める。"""
        now=time.monotonic()
        if float(getattr(
                self, "_za_mega_mode5_post_move_wait_until", 0.0)) <= 0.0:
            self._za_mega_mode5_post_move_wait_until=(
                now + max(0.0, float(wait_seconds)))
            self.ZA_mega_mode5_transition(
                "POST_MOVE_WAIT",
                "{}; wait {:.1f}s before FIELD_W input".format(
                    detection, max(0.0, float(wait_seconds))))
            testmode1_hp75=bool(
                getattr(self, "_za_mega_testmode1_enabled", False)
                and getattr(
                    self, "_za_mega_testmode1_resume_hp", "") == "HP75")
            self.ZA_mega_mode5_trace(
                detection,
                "wait after movement; {}".format(
                    "testmode1 view stopped" if testmode1_hp75
                    else "view rotation allowed"),
                force=True)

    def ZA_mega_mode5_green_and_initial_update(
            self, dir1, dir2, dir3, dir4, see_r,
            field_resume_dir5_seconds):
        """緑床優先と、床がない場合の初期接近を処理する。

        Trueはこの周回を終了して画面を取り直す、Falseは攻撃へ進める状態。
        """
        testmode1_enabled=bool(getattr(
            self, "_za_mega_testmode1_enabled", False))
        settings=(self.ZA_mega_mode5_testmode1_settings()
                  if testmode1_enabled else None)
        green_wait_seconds=float(
            settings["INITIAL_GREEN_WAIT_SECONDS"]
            if settings is not None else 2.5)
        green_check_seconds=float(
            settings["INITIAL_GREEN_CHECK_SECONDS"]
            if settings is not None else 1.0)
        post_move_wait_seconds=float(
            settings["INITIAL_POST_MOVE_WAIT_SECONDS"]
            if settings is not None else 2.0)
        if testmode1_enabled:
            testmode1_result=self.ZA_mega_mode5_testmode1_resume_update(
                dir1,dir2,dir3,dir4,see_r)
            if testmode1_result is not None:
                return bool(testmode1_result)

        post_move_wait_until=float(getattr(
            self, "_za_mega_mode5_post_move_wait_until", 0.0))
        yellow_retry_phase=bool(
            getattr(self, "_za_mega_mode5_initial_phase_active", False)
            or post_move_wait_until > 0.0)
        yellow_retry_remaining=int(getattr(
            self, "_za_mega_mode5_low_yellow_hp_checks_remaining", 0))
        if (yellow_retry_phase
                and not getattr(
                    self, "_za_mega_mode5_low_yellow_hp_active", False)
                and yellow_retry_remaining > 0
                and time.monotonic() >= float(getattr(
                    self, "_za_mega_mode5_low_yellow_hp_retry_at", 0.0))):
            yellow_retry_remaining-=1
            self._za_mega_mode5_low_yellow_hp_checks_remaining=(
                yellow_retry_remaining)
            yellow_low_hp=self.ZA_mega_mode5_low_yellow_hp()
            self._za_mega_mode5_low_yellow_hp_retry_at=(
                time.monotonic() + 0.25)
            if yellow_low_hp:
                self._za_mega_mode5_low_yellow_hp_active=True
                self._za_mega_mode5_low_yellow_hp_checks_remaining=0
                self._za_mega_mode5_low_yellow_hp_lock_seen=False
                self._za_mega_mode5_lockon_retreating=False
                print(
                    "[MEGA_MODE5_HP] yellow low HP detected on retry "
                    "ratio={:.3f}; enable lockon standoff".format(
                        float(getattr(
                            self,
                            "_za_mega_mode5_yellow_hp_fill_ratio",
                            0.0))))
            elif yellow_retry_remaining == 0:
                print(
                    "[MEGA_MODE5_HP] yellow low HP not detected after "
                    "resume retries; use normal movement")
        if post_move_wait_until > 0.0:
            now=time.monotonic()
            if now < post_move_wait_until:
                # 左スティックは初期移動の終了位置で止める。HP75の
                # TESTMODE1は青側障害物へ移るまで右視点も停止する。
                self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
                testmode1_hp75=bool(
                    getattr(self, "_za_mega_testmode1_enabled", False)
                    and getattr(
                        self, "_za_mega_testmode1_resume_hp", "") == "HP75")
                if testmode1_hp75:
                    self.ZA_mega_mode5_marker_search_view_stop(relock=False)
                    self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
                else:
                    self.ZA_mega_mode5_marker_search_view()
                self.wait(0.1)
                return True
            self._za_mega_mode5_post_move_wait_until=0.0
            self.ZA_mega_mode5_marker_search_view_stop(relock=False)
            finish_hp75=getattr(
                self, "ZA_mega_mode5_testmode1_finish_hp75_initial", None)
            if (callable(finish_hp75) and finish_hp75(
                    "HP75_POST_MOVE_WAIT_COMPLETE")):
                return True
            self.ZA_mega_mode5_transition(
                "FIELD_W_INPUT", "post-movement wait complete")
            self.ZA_mega_mode5_set_start_flag(
                3, "POST_MOVE_WAIT_COMPLETE", "check FIELD_W and press up")
            return False

        z_guard_active=False
        initial_green_checks=max(0, int(getattr(
            self,
            "_za_mega_mode5_green_priority_checks_remaining",
            0)))
        if self._za_mega_z_guard_enabled and initial_green_checks > 0:
            # 1回の画像判定が重い環境で8回を一括実行すると、
            # 再開直後に数秒間棒立ちになる。緑床優先は維持しつつ、
            # この周回の初期確認は実時間1秒までにする。
            green_check_deadline=(
                time.monotonic() + max(0.0, green_check_seconds))
            for green_check_index in range(initial_green_checks):
                z_guard_active=self.ZA_mega_z_guard_update(
                    dir1,dir2,dir3,dir4,
                    wait_seconds=green_wait_seconds)
                remaining=int(getattr(
                    self,
                    "_za_mega_mode5_green_priority_checks_remaining",
                    0))
                if remaining > 0:
                    remaining=max(0, remaining - 1)
                    self._za_mega_mode5_green_priority_checks_remaining=(
                        remaining)
                    if remaining == 0:
                        print(
                            "[MEGA_GREEN_PRIORITY] checks complete; "
                            "allow target search")
                if z_guard_active:
                    self.ZA_mega_mode5_trace(
                        "GREEN_FLOOR",
                        "hold" if getattr(
                            self, "_za_mega_z_guard_holding", False)
                        else "move to green floor")
                    self.ZA_mega_mode5_transition(
                        "GREEN_HOLD" if getattr(
                            self, "_za_mega_z_guard_holding", False)
                        else "GREEN_MOVE",
                        "green floor controls movement")
                    break
                if time.monotonic() >= green_check_deadline:
                    self._za_mega_mode5_green_priority_checks_remaining=0
                    print(
                        "[MEGA_GREEN_PRIORITY] {:.1f}s check budget complete; "
                        "start initial movement".format(
                            max(0.0, green_check_seconds)))
                    break
                if green_check_index + 1 < initial_green_checks:
                    self.wait(0.1)

            if getattr(
                    self, "_za_mega_mode5_initial_phase_active", False):
                green_processed=bool(
                    z_guard_active
                    or getattr(self, "_za_mega_z_guard_holding", False)
                    or getattr(
                        self, "_za_mega_z_guard_skip_current_floor", False))
                if green_processed:
                    self._za_mega_mode5_initial_green_handled=True
                    self._za_mega_field_dir5_until=0.0
                    self._za_mega_mode5_view_search_block_until=0.0
                if (getattr(
                        self, "_za_mega_mode5_initial_green_handled", False)
                        and not z_guard_active):
                    self._za_mega_mode5_initial_phase_active=False
                    self._za_mega_mode5_green_priority_checks_remaining=0
                    if getattr(
                            self,
                            "_za_mega_z_guard_normal_hold_completed",
                            False):
                        # 緑床移動後は設定時間だけZ_Guard内で待機済み。
                        # さらに移動後待機を足さず、FIELD_W確認へ進む。
                        finish_hp75=getattr(
                            self,
                            "ZA_mega_mode5_testmode1_finish_hp75_initial",
                            None)
                        if (callable(finish_hp75) and finish_hp75(
                                "HP75_GREEN_FLOOR_WAIT_COMPLETE")):
                            return True
                        else:
                            self.ZA_mega_mode5_transition(
                                "FIELD_W_INPUT",
                                "green-floor {:.1f}s wait complete".format(
                                    green_wait_seconds))
                            self.ZA_mega_mode5_set_start_flag(
                                3, "GREEN_FLOOR_WAIT_COMPLETE",
                                "check FIELD_W and press up")
                    else:
                        self.ZA_mega_mode5_begin_post_move_wait(
                            "GREEN_FLOOR_COMPLETE",
                            wait_seconds=post_move_wait_seconds)
            if z_guard_active:
                self.wait(0.1)
                return True
            if float(getattr(
                    self, "_za_mega_mode5_post_move_wait_until", 0.0)) > 0.0:
                return True

        if (getattr(self, "_za_mega_mode5_initial_phase_active", False)
                and not getattr(
                    self, "_za_mega_mode5_initial_green_handled", False)
                and not getattr(
                    self, "_za_mega_mode5_initial_approach_started", False)):
            approach_seconds=max(0.0, float(getattr(
                self,
                "_za_mega_mode5_initial_approach_seconds",
                field_resume_dir5_seconds)))
            approach_angle=float(getattr(
                self, "_za_mega_mode5_initial_approach_angle",
                getattr(self, "_za_mega_dir5", 90)))
            self._za_mega_mode5_initial_approach_started=True
            self._za_mega_field_dir5_until=(
                time.monotonic() + approach_seconds)
            self._za_mega_mode5_view_search_block_until=(
                self._za_mega_field_dir5_until)
            self.ZA_mega_mode5_transition(
                "INITIAL_APPROACH",
                "no green floor; move {:.0f}deg for {:.1f}s".format(
                    approach_angle, approach_seconds))
            # 有限入力として完了させ、重い画像判定中に壁へ押し続けない。
            self.ZA_MOVE_LStick(dir1,dir2,dir3,dir4,1,"END")
            self.ZA_MOVE_SEE(action="END", in_see_r=see_r)
            # 初期接近はロックオン横移動で減速させず、最大強度で進む。
            self.ZA_ZL_ACTION("END")
            self.press(
                Direction(
                    Stick.LEFT,
                    approach_angle,
                    1.0),
                duration=approach_seconds,
                wait=0.0)
            self._za_mega_field_dir5_until=0.0
            self._za_mega_mode5_initial_phase_active=False
            self._za_mega_mode5_green_priority_checks_remaining=0
            self._za_mega_mode5_view_search_block_until=0.0
            self.ZA_mega_mode5_begin_post_move_wait(
                "FIXED_{:.0f}DEG_MOVE_COMPLETE".format(
                    approach_angle),
                wait_seconds=post_move_wait_seconds)
            return True
        elif (not getattr(
                self, "_za_mega_mode5_initial_phase_active", False)
                and getattr(self, "_za_mega_mode5_phase", "")
                in {"GREEN_MOVE", "GREEN_HOLD"}):
            self.ZA_mega_mode5_begin_post_move_wait(
                "GREEN_FLOOR_COMPLETE",
                wait_seconds=post_move_wait_seconds)
            return True
        return False

