    # 2026-08-28: フィールド確認・endpicture対応前の旧共通関数を保持する。
    ZA_story_Template_battle_after_backup_20260824 = ZA_story_Template_battle_after_backup_20260828

    def ZA_story_Template_battle_after(
            self, bkprg_ret, prg_ret,
            selected_pic="POKEMON_ZA_FALSE_RETURN", selected_target=0,
            mode=0, sleeptime=0.5,
            endpicture="", endpicture2="", endpicture3=""):
        """戦闘後コメントを抜け、フィールドまたは指定画像で次へ進む。"""
        del mode  # 呼び出し互換用。終了時は共通の非戦闘フィールドを確認する。
        false_pictures = {
            None, "", "RETURN_FALSE", "RETURN FALSE",
            "POKEMON_ZA_FALSE_RETURN",
        }
        endpictures = tuple(
            picture for picture in (endpicture, endpicture2, endpicture3)
            if picture not in false_pictures)
        selected_picture_enabled = selected_pic not in false_pictures
        a_pictures = (
            "POKEMON_ZA_TEXT_BLACK_COMMENT",
            "POKEMON_ZA_CHAT_MARKER",
            "POKEMON_ZA_COIN_ICON",
            "POKEMON_ZA_1_SELECT",
            "POKEMON_ZA_2_SELECT",
            "POKEMON_ZA_3_SELECT",
            "POKEMON_ZA_4_SELECT",
            "POKEMON_ZA_HELP_MARKER",
            "POKEMON_ZA_MORNING",
            "POKEMON_ZA_NIGHT",
        )
        b_pictures = (
            "POKEMON_ZA_X_MENU_OPEN",
            "POKEMON_ZA_TEXT_WHITE_COMMENT",
            "POKEMON_ZA_TEXT_GREEN_COMMENT",
            "POKEMON_ZA_COMMENT_MARKER",
        )

        while True:
            self.checkIfAlive()

            # 明示された終了画像は、戦闘表示と同時に見えても優先する。
            if any(self.image_check(picture) for picture in endpictures):
                return prg_ret

            # BATTLE_BALL_CHECKは状態異常で閾値が変わるため使用しない。
            if (self.image_check("POKEMON_ZA_BATTLE_ACTIVE_LEVEL")
                    or self.image_check("POKEMON_ZA_ESCAPE")):
                return bkprg_ret

            # コメントや演出が完全に消え、フィールドが見えてから次へ進む。
            if self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"):
                return prg_ret

            if (selected_picture_enabled
                    and self.image_check(selected_pic)):
                self.wait(1.0)
                for _ in range(selected_target):
                    self.etc_sendCommand("Lbutton_down")
                    self.wait(0.5)
                self.pressRep(
                    Button.A, repeat=1, duration=0.15,
                    wait=0.0, interval=0.1)
            elif any(self.image_check(picture) for picture in a_pictures):
                self.pressRep(
                    Button.A, repeat=1, duration=0.04,
                    wait=0.0, interval=0.1)
            elif any(self.image_check(picture) for picture in b_pictures):
                self.pressRep(
                    Button.B, repeat=1, duration=0.04,
                    wait=0.0, interval=0.1)
            else:
                # 遷移中の無検知画面では操作せず、次の画像を待つ。
                self.wait(max(0.1, sleeptime))
                continue
            self.wait(max(0.1, sleeptime))

    def _ZA_story_battle_flow_state(self, battle_flow_key):
        flows = getattr(self, "_za_story_battle_flows", None)
        if flows is None:
            flows = {}
            self._za_story_battle_flows = flows
        return flows.setdefault(battle_flow_key, {
            "phase": "WAIT_ENTRY",
            "active_seen": False,
            "result_seen": False,
            "field_result_count": 0,
            "field_result_since": None,
        })

    def _ZA_story_battle_flow_mark(self, battle_flow_key, phase, reason):
        state = self._ZA_story_battle_flow_state(battle_flow_key)
        if state["phase"] != phase:
            print(
                "[BATTLE_FLOW] {}: {} -> {} ({})".format(
                    battle_flow_key, state["phase"], phase, reason))
            state["phase"] = phase
        return state

    def _ZA_story_battle_flow_reset(self, battle_flow_key, reason):
        flows = getattr(self, "_za_story_battle_flows", None)
        if flows is not None and battle_flow_key in flows:
            print("[BATTLE_FLOW] {}: reset ({})".format(
                battle_flow_key, reason))
            del flows[battle_flow_key]
        marker_missing_counts = getattr(
            self, "_za_story_event_marker_missing_counts", None)
        if isinstance(marker_missing_counts, dict):
            marker_missing_counts.pop(str(battle_flow_key), None)

    def _ZA_story_guri_select_defeat_reset(self, reason):
        """GURI_114／116で共有する敗戦選択肢の累計を破棄する。"""
        previous_count = int(getattr(
            self, "_za_story_guri_select_defeat_count", 0))
        self._za_story_guri_select_defeat_count = 0
        if previous_count:
            print(
                "[GURI_SELECT_DEFEAT_RECOVERY] count {} -> 0 ({})".format(
                    previous_count, reason))

    def _ZA_story_guri_defeat_recovery_reserve(
            self, current_state, reason):
        """GURI_114／116の敗戦復旧を既存FURADARI経路へ予約する。"""
        recovery_target = getattr(
            self, "ZA_STORY_GURI_SELECT_DEFEAT_TARGET",
            "7_STORY_GURI_108")
        self._ZA_story_guri_select_defeat_reset(reason)
        self._ZA_story_battle_flow_reset(
            "7_STORY_GURI_115", "guri_defeat_recovery_{}".format(reason))

        # 黒Comment90秒成立時は既に敗北Commentを確認済み。SELECT累計は
        # 誤一致の可能性があるため、黒Comment／FIELD／戦闘表示を確認して
        # からB→FIELD→FURADARI_MAP経路へ入る。
        black_comment_confirmed = reason == "black_comment_90s"
        self._za_furadari_black_recovery = {
            "recovery_target": recovery_target,
            "holding_state": current_state,
            "origin_state": current_state,
            "reason": reason,
            "dark_comment": False,
            "field_return_without_goto": False,
            "close_button": Button.B,
            "close_count": 0,
            "black_comment_confirmed": black_comment_confirmed,
            "black_comment_a_fallback": True,
            "black_comment_a_count": 0,
            "limit_logged": False,
            "phase": (
                "CLOSE_COMMENT"
                if black_comment_confirmed else "WAIT_GURI_OUTCOME"),
            "outcome_wait_started": time.monotonic(),
            "map_state": "COMMON_MAP_OPEN",
        }
        self._za_furadari_black_candidate_state = None
        self._za_furadari_black_candidate_started = None
        self._za_furadari_black_candidate_eyes_dark = False
        # 同じ外側Step周回の末尾で周辺暗転復旧が割り込まないよう、既存の
        # 専用復旧ロックを共有する。敗戦復旧完了時に既存処理が解除する。
        self._za_furadari_eyes_dark_recovery_lock_state = current_state
        self._za_furadari_section_dark_candidate_state = None
        self._za_furadari_section_dark_candidate_started = None
        self._za_furadari_section_recovery_state = None
        self._za_furadari_section_recovery_b_count = 0
        self._za_furadari_section_recovery_limit_logged = False
        self._za_furadari_section_recovery_no_frame_logged = False
        self.Common_current_state = "COMMON_START"
        self.map_cursor_reset = 0
        print(
            "[GURI_DEFEAT_RECOVERY] reason={} reserved {} -> {}".format(
                reason, current_state, recovery_target))
        return current_state

    def _ZA_story_guri_select_defeat_observe(
            self, current_state, detected_picture):
        """2～4択を累計し、3回目に既存FURADARI敗戦復旧を予約する。"""
        tracked_pictures = getattr(
            self, "ZA_STORY_GURI_SELECT_DEFEAT_PICTURES", ())
        if detected_picture not in tracked_pictures:
            return None

        # 呼出元のSELECT確認にもFIELD／Lv除外があるが、累計直前でも
        # 再確認する。特に114では黒Comment画面のSELECT誤一致を数えない。
        blocker_picture = next((
            picture for picture in (
                "POKEMON_ZA_TEXT_BLACK_COMMENT",
                "POKEMON_ZA_FIELD_W",
                "POKEMON_ZA_FIELD_BACK_W",
                "POKEMON_ZA_BATTLE_ACTIVE_LEVEL",
            ) if self.image_check(picture)
        ), None)
        if blocker_picture is not None:
            print(
                "[GURI_SELECT_DEFEAT_RECOVERY] ignore {} at {}: "
                "blocker={}".format(
                    detected_picture, current_state, blocker_picture))
            return current_state

        limit = max(1, int(getattr(
            self, "ZA_STORY_GURI_SELECT_DEFEAT_LIMIT", 3)))
        count = int(getattr(
            self, "_za_story_guri_select_defeat_count", 0)) + 1
        self._za_story_guri_select_defeat_count = count
        print(
            "[GURI_SELECT_DEFEAT_RECOVERY] state={} picture={} "
            "total={}/{}".format(
                current_state, detected_picture, count, limit))
        if count < limit:
            # 不一致の周回を挟んでもリセットせず、114／116間で共有する。
            return current_state

        # 3回目のSELECTに対するAは呼出元が送り、この予約は次のStep周回
        # から通常Stepを止めて敗戦復旧だけを進める。
        print(
            "[GURI_SELECT_DEFEAT_RECOVERY] total={} reached; "
            "reserve FURADARI defeat recovery from {}".format(
                limit, current_state))
        return self._ZA_story_guri_defeat_recovery_reserve(
            current_state, "select_total_{}".format(limit))

    def ZA_story_Template_battle_before_active_level(
            self, noprg_ret, prg_ret, battle_flow_key=None,
            green_check=0, no_filed=0, sleeptime=0.5,
            black_comment_is_defeat=False, event_move_duration=0.05):
        """戦闘前を進め、実戦闘または非戦闘の結果候補を次へ渡す。"""
        if not battle_flow_key:
            # 旧呼び出しからの移行時もbefore／battle／afterで同じキーに
            # なるよう、battle Step名（beforeの遷移先）を既定値にする。
            battle_flow_key = prg_ret
        state = self._ZA_story_battle_flow_state(battle_flow_key)
        retry_entry = state["phase"] == "RETRY_ENTRY"
        event_reacquire_allowed = (
            state["phase"] not in {"RESULT_CANDIDATE", "RESULT_SEEN"}
            and not state["result_seen"])
        if self.image_check("POKEMON_ZA_BATTLE_ACTIVE_LEVEL"):
            state["active_seen"] = True
            state["field_result_count"] = 0
            state["field_result_since"] = None
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "ACTIVE_SEEN", "active_level")
            return prg_ret

        # 戦闘前イベントは1周につき1入力だけ送り、Lv.表示を待つ。
        if self.image_check("POKEMON_ZA_X_MENU_OPEN"):
            self.pressRep(
                Button.B, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
        elif self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"):
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            if black_comment_is_defeat:
                state["active_seen"] = False
                state["result_seen"] = False
                state["field_result_count"] = 0
                state["field_result_since"] = None
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "RETRY_ENTRY",
                    "black_comment_defeat_before")
            return noprg_ret
        elif (self.image_check("POKEMON_ZA_HELP_MARKER")
                or self.image_check("POKEMON_ZA_1_SELECT")
                or self.image_check("POKEMON_ZA_2_SELECT")
                or self.image_check("POKEMON_ZA_3_SELECT")
                or self.image_check("POKEMON_ZA_4_SELECT")):
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
        elif (self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT")
                or self.image_check("POKEMON_ZA_COMMENT_MARKER")
                or (green_check == 1 and self.image_check(
                    "POKEMON_ZA_TEXT_GREEN_COMMENT"))):
            if retry_entry or not state["active_seen"]:
                # 敗北後または実戦闘前の会話は、別の人物へ話しかけた
                # 可能性がある。会話を閉じてbeforeに留まり、次周の
                # フィールド画面でEVENTを探し直す。
                self.pressRep(
                    Button.B, repeat=1, duration=0.15,
                    wait=0.5, interval=0.1)
                if not retry_entry:
                    state["active_seen"] = False
                    state["result_seen"] = False
                    state["field_result_count"] = 0
                    state["field_result_since"] = None
                    self._ZA_story_battle_flow_mark(
                        battle_flow_key, "WAIT_ENTRY",
                        "comment_closed_reacquire_event")
            else:
                # 実戦闘を一度確認済みの場合だけ結果候補として渡す。
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "RESULT_CANDIDATE",
                    "entry_result_after_active")
                return prg_ret
        elif self.image_check("POKEMON_ZA_COIN_ICON"):
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_CANDIDATE", "entry_coin")
            return prg_ret
        elif (self.image_check("POKEMON_ZA_MISSION_COMPLETE")
                or self.image_check("POKEMON_ZA_IN_ICON")):
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_CANDIDATE", "entry_completion")
            return prg_ret
        elif self.image_check("POKEMON_ZA_CHAT_MARKER"):
            # A「話しかける」が見えていても、先にEVENTマーカーを
            # 画面中央へ合わせる。after到達後のフローでは探索しない。
            if not event_reacquire_allowed:
                self.pressRep(
                    Button.A, repeat=1, duration=0.15,
                    wait=0.5, interval=0.1)
            elif self.ZA_markerdir("EVENT", 1, nofiled=True):
                # 中央化できてもその場から話しかけず、EVENT側へ小さく
                # 接近してから、話しかけ表示が残っている場合だけAを送る。
                self.press(
                    Direction(Stick.LEFT, 90),
                    duration=max(0.02, float(event_move_duration)), wait=0.2)
                if self.image_check("POKEMON_ZA_CHAT_MARKER"):
                    self.pressRep(
                        Button.A, repeat=1, duration=0.15,
                        wait=0.5, interval=0.1)
            else:
                self.wait(max(0.1, sleeptime))
        elif self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"):
            # 連戦の合間にフィールドへ戻った場合は、次の相手へ近づく。
            # RESULT_SEEN（after到達後）ではEVENT探索・移動を行わない。
            if (event_reacquire_allowed
                    and (self.ZA_markerdir("EVENT", 1)
                         or self.ZA_markerdir("SIDE_MARKER"))):
                self.press(
                    Direction(Stick.LEFT, 90),
                    duration=max(0.02, float(event_move_duration)), wait=0.5)
        else:
            self.wait(max(0.1, sleeptime))
        return noprg_ret

    def _ZA_story_battle_white_comment_continues(
            self, attempts=3, interval=0.35):
        """白CommentをBで送り、単発か連続ページかを短時間で判定する。"""
        attempts = max(1, int(attempts))
        interval = max(0.1, float(interval))
        saw_hidden = False
        comment_visible = True
        for attempt in range(1, attempts + 1):
            self.checkIfAlive()
            if comment_visible:
                self.pressRep(
                    Button.B, repeat=1, duration=0.15,
                    wait=interval, interval=0.1)
            else:
                self.wait(interval)
            comment_visible = (
                self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT")
                or self.image_check("POKEMON_ZA_COMMENT_MARKER"))
            if comment_visible and saw_hidden:
                print(
                    "[BATTLE_WHITE_COMMENT] reappeared after close "
                    f"attempt={attempt}/{attempts}")
                return True
            if not comment_visible:
                saw_hidden = True
        if comment_visible and not saw_hidden:
            # 3回Bを送っても白Commentが続く場合は、1枚だけの戦闘中
            # Commentではなく複数ページの結果会話として扱う。
            print(
                "[BATTLE_WHITE_COMMENT] remained across close attempts "
                f"attempts={attempts}")
            return True
        print(
            "[BATTLE_WHITE_COMMENT] closed without reappearance "
            f"attempts={attempts}")
        return False

    def ZA_story_Template_battle_function_active_level(
            self, bkprg_ret, prg_ret, noprg_ret, battle_flow_key=None,
            Xaction=0, Aaction=0, Yaction=0, Baction=0,
            lockon_endskip=0, get_chanceicon4=0, noCp=0,
            markertype=0, battle_mode=0, move=0, sleeptime=0.5,
            rebattle_move_fast=0.1, lockon_attack_wait=0.0,
            lockon_attack_checks=1,
            result_picture="POKEMON_ZA_FALSE_RETURN",
            black_comment_is_defeat=False,
            green_comment_is_victory=False, rebattle=1,
            white_comment_result_retries=0, usenum=1):
        """左下Lv.を戦闘中の唯一の基準として戦闘結果まで進める。"""
        if not battle_flow_key:
            # battle関数の現在Step名。beforeのprg_ret、afterのbkprg_retと
            # 同じ値になるため、明示キーなしでも3関数で状態を共有できる。
            battle_flow_key = noprg_ret
        state = self._ZA_story_battle_flow_state(battle_flow_key)

        if self.image_check("POKEMON_ZA_HELP_MARKER"):
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            return noprg_ret

        active_level_visible = self.image_check(
            "POKEMON_ZA_BATTLE_ACTIVE_LEVEL")
        hard_field_visible = self.image_check(
            "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")
        selection_picture = next((
            picture for picture in (
                "POKEMON_ZA_1_SELECT",
                "POKEMON_ZA_2_SELECT",
                "POKEMON_ZA_3_SELECT",
                "POKEMON_ZA_4_SELECT",
            ) if self.image_check(picture)
        ), None)
        if (selection_picture is not None
                and not active_level_visible
                and not hard_field_visible):
            # SELECTはFIELDでも戦闘Lv.表示中でもない画面だけ採用する。
            # KARASUBA_40等で戦闘HUDを2_SELECTと誤検知してもAを押さない。
            print(
                f"[BATTLE_SELECT] {selection_picture} detected -> press A")
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            return noprg_ret
        if self.image_check("POKEMON_ZA_X_MENU_OPEN"):
            self.pressRep(
                Button.B, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            return noprg_ret

        if active_level_visible:
            state["active_seen"] = True
            state["result_seen"] = False
            state["field_result_count"] = 0
            state["field_result_since"] = None
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "ACTIVE_SEEN", "active_level")
            field_w_up_handled = False
            if (noCp == 1 and battle_mode == 1
                    and self.image_check("POKEMON_ZA_FIELD_W")):
                self.etc_sendCommand("Lbutton_up")
                field_w_up_handled = True
            if noCp == 0:
                if move == 0:
                    self.ZA_battle_Cp_loop(
                        Xaction=Xaction, Aaction=Aaction,
                        Yaction=Yaction, Baction=Baction,
                        get_chanceicon4=get_chanceicon4,
                        battle_mode=battle_mode,
                        lockon_attack_wait=lockon_attack_wait,
                        lockon_attack_checks=lockon_attack_checks,
                        usenum=usenum)
                else:
                    self.ZA_battle_Cp_loop_move(
                        Xaction=Xaction, Aaction=Aaction,
                        Yaction=Yaction, Baction=Baction,
                        get_chanceicon4=get_chanceicon4,
                        battle_mode=battle_mode, usenum=usenum)
            else:
                if (get_chanceicon4 == 1
                        and self.image_check("POKEMON_ZA_GETCHANCE_ICON4")):
                    self.ZA_get_pokemon()
                self.ZA_battle_coCp_noloop(
                    Xaction=Xaction, Aaction=Aaction,
                    Yaction=Yaction, Baction=Baction,
                    battle_mode=battle_mode,
                    selection_up_handled=field_w_up_handled)
            return noprg_ret

        # FIELD背景を選択肢として誤検知する場合があるため、戦闘前の
        # 安全連打と同様にHARD_FIELD表示中は1～4_SELECTを無効化する。
        if (result_picture != "POKEMON_ZA_FALSE_RETURN"
                and self.image_check(result_picture)):
            state["result_seen"] = True
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_SEEN", result_picture)
            return prg_ret

        if self.image_check("POKEMON_ZA_COIN_ICON"):
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            state["result_seen"] = True
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_SEEN", "coin")
            return prg_ret

        if self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"):
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            if rebattle == 0:
                # 再戦しないバトルの敗北コメントはbeforeへ戻さない。
                # after側でコメントを抜け、フィールド表示まで待機する。
                state["active_seen"] = False
                state["result_seen"] = True
                state["field_result_count"] = 0
                state["field_result_since"] = None
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "RESULT_SEEN",
                    "black_comment_without_rebattle")
                return prg_ret
            if black_comment_is_defeat:
                state["active_seen"] = False
                state["result_seen"] = False
                state["field_result_count"] = 0
                state["field_result_since"] = None
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "RETRY_ENTRY",
                    "black_comment_defeat")
                return bkprg_ret
            # 黒コメントを敗戦に使わない戦闘は従来動作を維持する。
            if state["active_seen"]:
                return noprg_ret
            state["result_seen"] = False
            state["field_result_count"] = 0
            state["field_result_since"] = None
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "WAIT_ENTRY",
                "black_comment_without_active")
            return bkprg_ret

        green_comment_visible = self.image_check(
            "POKEMON_ZA_TEXT_GREEN_COMMENT")
        white_comment_visible = self.image_check(
            "POKEMON_ZA_TEXT_WHITE_COMMENT")
        if (green_comment_visible
                or white_comment_visible
                or self.image_check("POKEMON_ZA_COMMENT_MARKER")):
            if not state["active_seen"]:
                # 戦闘を一度も確認していないCommentは、別の人物との
                # 会話として閉じ、beforeでEVENTを探し直す。
                self.pressRep(
                    Button.B, repeat=1, duration=0.15,
                    wait=0.5, interval=0.1)
                state["result_seen"] = False
                state["field_result_count"] = 0
                state["field_result_since"] = None
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "WAIT_ENTRY",
                    "comment_without_active")
                return bkprg_ret
            if green_comment_is_victory and green_comment_visible:
                # Wランク戦では実戦闘を一度確認した後の緑Commentを勝利とする。
                # 戦闘前の別人会話は上のactive_seen判定でbeforeへ戻す。
                state["result_seen"] = True
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "RESULT_SEEN",
                    "green_comment_victory")
                return prg_ret
            if (white_comment_visible
                    and int(white_comment_result_retries) > 0):
                if self._ZA_story_battle_white_comment_continues(
                        attempts=white_comment_result_retries):
                    state["result_seen"] = True
                    self._ZA_story_battle_flow_mark(
                        battle_flow_key, "RESULT_SEEN",
                        "repeated_white_comment_after_active")
                    return prg_ret
                # 1枚だけの戦闘途中Comment。閉じた後もbattle Stepを
                # 維持し、左下Lv.の再表示またはCOMPLETEを待つ。
                state["field_result_count"] = 0
                state["field_result_since"] = None
                return noprg_ret
            if result_picture != "POKEMON_ZA_FALSE_RETURN":
                # 専用勝利画像がある戦闘では、白／緑コメントや
                # COMMENT_MARKERだけで敗北・勝利を決めない。会話を送り、
                # functionに留まって専用画像またはBLACK_COMMENTを待つ。
                self.pressRep(
                    Button.B, repeat=1, duration=0.15,
                    wait=0.5, interval=0.1)
                state["field_result_count"] = 0
                state["field_result_since"] = None
                return noprg_ret
            state["result_seen"] = True
            reason = (
                "result_comment_after_active"
                if state["active_seen"] else "no_battle_result_comment")
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_SEEN", reason)
            return prg_ret

        if self.image_check("POKEMON_ZA_CHAT_MARKER"):
            if not state["active_seen"]:
                # ここでは話しかけずbeforeへ戻す。before側がEVENTを
                # 中央へ合わせてからAを送る。
                state["result_seen"] = False
                state["field_result_count"] = 0
                state["field_result_since"] = None
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "WAIT_ENTRY",
                    "chat_marker_without_active")
                return bkprg_ret
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            return noprg_ret

        if (self.image_check("POKEMON_ZA_MISSION_COMPLETE")
                or self.image_check("POKEMON_ZA_IN_ICON")):
            state["result_seen"] = True
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_SEEN", "completion_icon")
            return prg_ret

        if hard_field_visible:
            if not state["active_seen"]:
                if black_comment_is_defeat:
                    self.wait(max(0.1, sleeptime))
                    return noprg_ret
                if rebattle == 0:
                    state["result_seen"] = True
                    self._ZA_story_battle_flow_mark(
                        battle_flow_key, "RESULT_SEEN",
                        "field_without_rebattle")
                    return prg_ret
                return bkprg_ret
            now = time.monotonic()
            if state["field_result_since"] is None:
                state["field_result_since"] = now
                state["field_result_count"] = 1
            else:
                state["field_result_count"] += 1
            if (state["field_result_count"] >= 2
                    and now - state["field_result_since"] >= 0.5):
                if black_comment_is_defeat:
                    # W戦はFIELDだけで再戦へ戻さない。勝利専用画像または
                    # BLACK_COMMENTの確定までbattle_functionを維持する。
                    self.wait(max(0.1, sleeptime))
                    return noprg_ret
                if rebattle == 0:
                    state["result_seen"] = True
                    self._ZA_story_battle_flow_mark(
                        battle_flow_key, "RESULT_SEEN",
                        "stable_field_without_rebattle")
                    return prg_ret
                # 白／緑・コイン・完了表示を見ないままフィールドへ
                # 戻った場合は、勝利確定にせず再試行する。
                state["active_seen"] = False
                state["result_seen"] = False
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "WAIT_ENTRY",
                    "stable_field_without_result")
                return bkprg_ret
            self.wait(max(0.1, sleeptime))
            return noprg_ret

        state["field_result_count"] = 0
        state["field_result_since"] = None
        self.wait(max(0.1, sleeptime))
        if state["active_seen"]:
            # 技演出中にLv.が一時的に消えても、入力や終了判定を行わない。
            return noprg_ret
        if black_comment_is_defeat:
            # 敗北をBLACK_COMMENTで判定する戦闘は、無検知だけでbeforeへ
            # 戻さず、勝敗画像を引き続き確認する。
            return noprg_ret
        return bkprg_ret

    def ZA_story_Template_battle_after_active_level(
            self, bkprg_ret, prg_ret, battle_flow_key=None,
            selected_pic="POKEMON_ZA_FALSE_RETURN", selected_target=0,
            mode=0, sleeptime=0.5,
            black_comment_is_defeat=False,
            endpicture="", endpicture2="", endpicture3=""):
        """勝利後会話を進め、Lv.再表示だけを戦闘復帰として扱う。"""
        del mode  # 呼び出し互換用。
        if not battle_flow_key:
            # afterの戻り先がbattle Stepなので、before／battleと同じキー。
            battle_flow_key = bkprg_ret
        false_pictures = {
            None, "", "RETURN_FALSE", "RETURN FALSE",
            "POKEMON_ZA_FALSE_RETURN",
        }
        endpictures = tuple(
            picture for picture in (endpicture, endpicture2, endpicture3)
            if picture not in false_pictures)
        selected_picture_enabled = selected_pic not in false_pictures
        state = self._ZA_story_battle_flow_state(battle_flow_key)
        if (black_comment_is_defeat
                and self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")):
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            state["active_seen"] = False
            state["result_seen"] = False
            state["field_result_count"] = 0
            state["field_result_since"] = None
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RETRY_ENTRY",
                "black_comment_defeat_after")
            return bkprg_ret
        if not state["result_seen"]:
            state["result_seen"] = True
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_SEEN", "entered_after")

        field_count = 0
        while True:
            self.checkIfAlive()
            # 明示された終了画像は、Lv.表示と同時でも終了を優先する。
            if any(self.image_check(picture) for picture in endpictures):
                self._ZA_story_battle_flow_reset(
                    battle_flow_key, "endpicture")
                return prg_ret
            if self.image_check("POKEMON_ZA_BATTLE_ACTIVE_LEVEL"):
                state["active_seen"] = True
                state["result_seen"] = False
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "ACTIVE_SEEN", "active_level_returned")
                return bkprg_ret
            if self.image_check("POKEMON_ZA_MISSION_COMPLETE"):
                # COMPLETEは終了確定にせず、Aで閉じてフィールドを待つ。
                field_count = 0
                self.pressRep(
                    Button.A, repeat=1, duration=0.15,
                    wait=0.5, interval=0.1)
                continue
            if self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"):
                field_count += 1
                if field_count >= 2:
                    self._ZA_story_battle_flow_reset(
                        battle_flow_key, "stable_field")
                    return prg_ret
                self.wait(max(0.1, sleeptime))
                continue
            field_count = 0
            if self.image_check("POKEMON_ZA_X_MENU_OPEN"):
                button = Button.B
            elif (selected_picture_enabled
                    and self.image_check(selected_pic)):
                self.wait(1.0)
                for _ in range(selected_target):
                    self.etc_sendCommand("Lbutton_down")
                    self.wait(0.5)
                self.pressRep(
                    Button.A, repeat=1, duration=0.15,
                    wait=0.0, interval=0.1)
                self.wait(max(0.1, sleeptime))
                continue
            elif (self.image_check("POKEMON_ZA_HELP_MARKER")
                    or self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")
                    or self.image_check("POKEMON_ZA_CHAT_MARKER")
                    or self.image_check("POKEMON_ZA_COIN_ICON")
                    or self.image_check("POKEMON_ZA_1_SELECT")
                    or self.image_check("POKEMON_ZA_2_SELECT")
                    or self.image_check("POKEMON_ZA_3_SELECT")
                    or self.image_check("POKEMON_ZA_4_SELECT")):
                button = Button.A
            elif (self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT")
                    or self.image_check("POKEMON_ZA_TEXT_GREEN_COMMENT")
                    or self.image_check("POKEMON_ZA_COMMENT_MARKER")):
                button = Button.B
            else:
                self.wait(max(0.1, sleeptime))
                continue
            self.pressRep(
                button, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)

    def _ZA_story_battle_before_safe_renda_once(
            self, green_check, sleeptime):
        """before用に安全入力を1回だけ送り、停止理由を返す。"""
        self.checkIfAlive()
        wait_time = max(0.1, float(sleeptime))
        hard_field_visible = self.image_check(
            "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")

        # HELPはFIELD上でも優先する。黒Commentと戦闘Lv.はSELECTより
        # 先に止め、黒Comment背景や戦闘HUDのSELECT誤一致を累計させない。
        if self.image_check("POKEMON_ZA_HELP_MARKER"):
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.0, interval=0.1)
            self.wait(wait_time)
            return "continue", "POKEMON_ZA_HELP_MARKER"
        if self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"):
            return "black_comment", "POKEMON_ZA_TEXT_BLACK_COMMENT"
        if self.image_check("POKEMON_ZA_BATTLE_ACTIVE_LEVEL"):
            return "active_level", "POKEMON_ZA_BATTLE_ACTIVE_LEVEL"

        # 1～4択はFIELD背景の模様を誤検知する場合があるため、
        # HARD_FIELD不一致時だけ扱う。
        if not hard_field_visible:
            for picture in (
                    "POKEMON_ZA_1_SELECT",
                    "POKEMON_ZA_2_SELECT",
                    "POKEMON_ZA_3_SELECT",
                    "POKEMON_ZA_4_SELECT"):
                if not self.image_check(picture):
                    continue
                self.pressRep(
                    Button.A, repeat=1, duration=0.15,
                    wait=0.0, interval=0.1)
                self.wait(wait_time)
                return "continue", picture

        # ここからは入力せずにRendaを止め、呼出元が画面別に処理する。
        if (self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT")
                or self.image_check("POKEMON_ZA_COMMENT_MARKER")
                or (green_check == 1 and self.image_check(
                    "POKEMON_ZA_TEXT_GREEN_COMMENT"))):
            return "result_comment", "comment"
        if self.image_check("POKEMON_ZA_COIN_ICON"):
            return "result", "POKEMON_ZA_COIN_ICON"
        if self.image_check("POKEMON_ZA_MISSION_COMPLETE"):
            return "result", "POKEMON_ZA_MISSION_COMPLETE"
        if self.image_check("POKEMON_ZA_IN_ICON"):
            return "result", "POKEMON_ZA_IN_ICON"
        if self.image_check("POKEMON_ZA_CHAT_MARKER"):
            return "chat", "POKEMON_ZA_CHAT_MARKER"
        if hard_field_visible:
            return "field", "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"

        # Bが必要な既知画面だけ入力する。全画像不一致時は待機も入力も
        # 行わず、外側のStep監視へすぐ返して次フレームを確認する。
        if self.image_check("POKEMON_ZA_X_MENU_OPEN"):
            self.pressRep(
                Button.B, repeat=1, duration=0.15,
                wait=0.0, interval=0.1)
            self.wait(wait_time)
            return "continue", "x_menu_b"
        return "continue", "no_input"

    def ZA_story_Template_battle_before_renda_route(
            self, noprg_ret, prg_ret, battle_flow_key=None,
            green_check=0, no_filed=0, sleeptime=0.5,
            black_comment_is_defeat=False, event_move_duration=0.05,
            event_move_attempts=1, rebattle=1,
            event_marker_missing_sets=0,
            event_marker_missing_fallback="",
            event_marker_seen_resets_missing_sets=True,
            guri_select_defeat_state=""):
        """B基準の1入力Rendaで戦闘開始または結果候補まで進める。"""
        del no_filed  # 呼び出し互換用。従来のactive_level版でも未使用。
        if not battle_flow_key:
            battle_flow_key = prg_ret
        state = self._ZA_story_battle_flow_state(battle_flow_key)
        retry_entry = state["phase"] == "RETRY_ENTRY"
        marker_missing_counts = getattr(
            self, "_za_story_event_marker_missing_counts", None)
        if not isinstance(marker_missing_counts, dict):
            marker_missing_counts = {}
            self._za_story_event_marker_missing_counts = (
                marker_missing_counts)
        marker_missing_key = str(battle_flow_key)
        marker_missing_limit = max(0, int(event_marker_missing_sets))
        marker_missing_fallback = str(event_marker_missing_fallback or "")
        event_reacquire_allowed = (
            rebattle != 0
            and state["phase"] not in {"RESULT_CANDIDATE", "RESULT_SEEN"}
            and not state["result_seen"])

        def event_marker_missing_fallback_for_search(
                event_marker_seen, count_seen_as_no_progress=False):
            """Return the configured fallback after one complete EVENT search set."""
            if not (marker_missing_limit > 0 and marker_missing_fallback):
                return ""
            if event_marker_seen and not count_seen_as_no_progress:
                previous_missing = marker_missing_counts.pop(
                    marker_missing_key, 0)
                if previous_missing:
                    print(
                        "[BATTLE_EVENT_MARKER_FALLBACK] {}: "
                        "EVENT found; missing sets {}/{} -> 0".format(
                            battle_flow_key, previous_missing,
                            marker_missing_limit))
                return ""

            missing_sets = int(marker_missing_counts.get(
                marker_missing_key, 0)) + 1
            marker_missing_counts[marker_missing_key] = missing_sets
            if event_marker_seen:
                print(
                    "[BATTLE_EVENT_MARKER_FALLBACK] {}: "
                    "EVENT found but FIELD no progress set={}/{}".format(
                        battle_flow_key, missing_sets,
                        marker_missing_limit))
            else:
                print(
                    "[BATTLE_EVENT_MARKER_FALLBACK] {}: "
                    "EVENT not found set={}/{}".format(
                        battle_flow_key, missing_sets,
                        marker_missing_limit))
            if missing_sets < marker_missing_limit:
                return ""

            marker_missing_counts.pop(marker_missing_key, None)
            reset_reason = "event_marker_missing_{}_sets".format(
                marker_missing_limit)
            if event_marker_seen:
                reset_reason = "event_marker_field_no_progress_{}_sets".format(
                    marker_missing_limit)
            self._ZA_story_battle_flow_reset(
                battle_flow_key, reset_reason)
            print(
                "[BATTLE_EVENT_MARKER_FALLBACK] {}: "
                "EVENT entry stalled for {} sets -> {}".format(
                    battle_flow_key, marker_missing_limit,
                    marker_missing_fallback))
            return marker_missing_fallback

        stop_reason, stop_picture = (
            self._ZA_story_battle_before_safe_renda_once(
                green_check=green_check,
                sleeptime=sleeptime))
        # Step固有の復旧判定から、共通beforeが実際にどの画面で
        # noprg_retへ戻ったかを区別できるようにする。戻り値だけでは
        # FIELD／全画像不一致と、Comment・SELECT処理後を判別できない。
        self._za_story_battle_before_last_observation = {
            "battle_flow_key": str(battle_flow_key),
            "stop_reason": stop_reason,
            "stop_picture": stop_picture,
        }
        if guri_select_defeat_state:
            select_return = self._ZA_story_guri_select_defeat_observe(
                guri_select_defeat_state, stop_picture)
            if select_return is not None:
                return select_return
        if stop_reason != "continue":
            print(
                "[BATTLE_RENDA_BEFORE] {}: stop={} picture={}".format(
                    battle_flow_key, stop_reason, stop_picture))
        if stop_reason not in {"field", "chat"} and marker_missing_limit > 0:
            # EVENT探索が連続したFIELD周回だけを1セットとして数える。
            # 戦闘・結果画面など別画面へ進めた場合は前回分を持ち越さない。
            # CHAT_MARKERはこの下でEVENT探索するため、FIELDと同じセット。
            marker_missing_counts.pop(marker_missing_key, None)

        if stop_reason == "active_level":
            state["active_seen"] = True
            state["field_result_count"] = 0
            state["field_result_since"] = None
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "ACTIVE_SEEN", "active_level_before_renda")
            return prg_ret

        if stop_reason == "black_comment":
            # afterでは敗北Commentを閉じずにbeforeへ返すため、ここで
            # 安全側のBを1回送り、RETRY_ENTRYを維持する。
            self.pressRep(
                Button.B, repeat=1, duration=0.15,
                wait=0.0, interval=0.1)
            self.wait(max(0.1, float(sleeptime)))
            if black_comment_is_defeat:
                state["active_seen"] = False
                state["result_seen"] = False
                state["field_result_count"] = 0
                state["field_result_since"] = None
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "RETRY_ENTRY",
                    "black_comment_defeat_before_renda")
            return noprg_ret

        if stop_reason == "result_comment":
            if retry_entry or not state["active_seen"]:
                # 実戦闘前または敗北後の会話はBで閉じ、EVENT再取得へ戻す。
                self.pressRep(
                    Button.B, repeat=1, duration=0.15,
                    wait=0.0, interval=0.1)
                self.wait(max(0.1, float(sleeptime)))
                if not retry_entry:
                    state["active_seen"] = False
                    state["result_seen"] = False
                    state["field_result_count"] = 0
                    state["field_result_since"] = None
                    self._ZA_story_battle_flow_mark(
                        battle_flow_key, "WAIT_ENTRY",
                        "comment_closed_before_renda")
                return noprg_ret
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_CANDIDATE",
                "result_comment_before_renda")
            return prg_ret

        if stop_reason == "result":
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_CANDIDATE",
                "{}_before_renda".format(stop_picture))
            return prg_ret

        if stop_reason == "chat":
            # 話しかけ表示はRendaを止めてからEVENTを中央化し、0.05秒
            # 接近後も表示が残っている場合だけAを送る。再戦なしでは
            # 既定移動で接近済みなのでEVENTを探さず、その場でAを送る。
            if (not event_reacquire_allowed
                    or int(event_move_attempts) > 1):
                self.pressRep(
                    Button.A, repeat=1, duration=0.15,
                    wait=0.5, interval=0.1)
            else:
                event_marker_aligned = self.ZA_markerdir(
                    "EVENT", 1, nofiled=True,
                    stop_after_first_scan_move=(
                        marker_missing_limit > 0))
                event_marker_seen = bool(getattr(
                    self,
                    "_za_markerdir_marker_seen_POKEMON_ZA_EVENT_MARKER",
                    event_marker_aligned))
                missing_fallback = event_marker_missing_fallback_for_search(
                    event_marker_seen)
                if missing_fallback:
                    return missing_fallback
                if event_marker_aligned:
                    self.press(
                        Direction(Stick.LEFT, 90),
                        duration=max(0.02, float(event_move_duration)), wait=0.2)
                    if self.image_check("POKEMON_ZA_CHAT_MARKER"):
                        self.pressRep(
                            Button.A, repeat=1, duration=0.15,
                            wait=0.5, interval=0.1)
                else:
                    self.wait(max(0.1, float(sleeptime)))
            return noprg_ret

        if stop_reason == "field":
            # RESULT_SEEN（after到達後）または再戦なしでは、EVENT探索・
            # 移動を行わない。
            event_marker_aligned = False
            if event_reacquire_allowed:
                event_marker_aligned = self.ZA_markerdir(
                    "EVENT", 1,
                    stop_after_first_scan_move=(
                        marker_missing_limit > 0))
                event_marker_seen = bool(getattr(
                    self,
                    "_za_markerdir_marker_seen_POKEMON_ZA_EVENT_MARKER",
                    event_marker_aligned))
                missing_fallback = event_marker_missing_fallback_for_search(
                    event_marker_seen,
                    count_seen_as_no_progress=(
                        not bool(event_marker_seen_resets_missing_sets)))
                if missing_fallback:
                    return missing_fallback
            if (event_reacquire_allowed
                    and (event_marker_aligned
                         or self.ZA_markerdir("SIDE_MARKER"))):
                move_attempts = max(1, int(event_move_attempts))
                if move_attempts == 1:
                    self.press(
                        Direction(Stick.LEFT, 90),
                        duration=max(0.02, float(event_move_duration)),
                        wait=0.5)
                else:
                    # 再戦位置では最大10回など、短い接近を同一Step内で
                    # 続ける。各移動の前後で話しかけ表示を確認し、表示
                    # された時点で即Aを送り、戦闘画面なら移動を止める。
                    for _ in range(move_attempts):
                        self.checkIfAlive()
                        if self.image_check("POKEMON_ZA_CHAT_MARKER"):
                            self.pressRep(
                                Button.A, repeat=1, duration=0.15,
                                wait=0.5, interval=0.1)
                            return noprg_ret
                        if not self.image_check(
                                "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"):
                            return noprg_ret
                        self.press(
                            Direction(Stick.LEFT, 90),
                            duration=max(
                                0.02, float(event_move_duration)),
                            wait=0.2)
                        if self.image_check("POKEMON_ZA_CHAT_MARKER"):
                            self.pressRep(
                                Button.A, repeat=1, duration=0.15,
                                wait=0.5, interval=0.1)
                            return noprg_ret
            return noprg_ret

        # HELP／選択肢のA、XメニューのB、または無入力で外側のStep監視へ
        # 必ず制御を返し、無限ループで復旧タイマーを止めない。
        return noprg_ret

    def ZA_story_Template_battle_function_renda_route(
            self, bkprg_ret, prg_ret, noprg_ret, battle_flow_key=None,
            Xaction=1, Aaction=1, Yaction=1, Baction=1,
            lockon_endskip=0, get_chanceicon4=0, noCp=0,
            markertype=0, battle_mode=0, move=0, sleeptime=0.5,
            rebattle_move_fast=0.1, lockon_attack_wait=0.0,
            lockon_attack_checks=1,
            result_picture="POKEMON_ZA_FALSE_RETURN",
            black_comment_is_defeat=False,
            green_comment_is_victory=False, rebattle=1,
            white_comment_result_retries=0, usenum=1):
        """新しい安全連打フロー用の戦闘中入口。"""
        return self.ZA_story_Template_battle_function_active_level(
            bkprg_ret=bkprg_ret,
            prg_ret=prg_ret,
            noprg_ret=noprg_ret,
            battle_flow_key=battle_flow_key,
            Xaction=Xaction,
            Aaction=Aaction,
            Yaction=Yaction,
            Baction=Baction,
            lockon_endskip=lockon_endskip,
            get_chanceicon4=get_chanceicon4,
            noCp=noCp,
            markertype=markertype,
            battle_mode=battle_mode,
            move=move,
            sleeptime=sleeptime,
            rebattle_move_fast=rebattle_move_fast,
            lockon_attack_wait=lockon_attack_wait,
            lockon_attack_checks=lockon_attack_checks,
            result_picture=result_picture,
            black_comment_is_defeat=black_comment_is_defeat,
            green_comment_is_victory=green_comment_is_victory,
            rebattle=rebattle,
            white_comment_result_retries=white_comment_result_retries,
            usenum=usenum)

    def _ZA_story_battle_after_safe_renda(
            self, selected_pic, selected_target, endpictures, sleeptime,
            guri_select_defeat_state=""):
        """B連打を基準にし、停止した画面の種類と画像名を返す。"""
        false_pictures = {
            None, "", "RETURN_FALSE", "RETURN FALSE",
            "POKEMON_ZA_FALSE_RETURN",
        }
        selected_picture_enabled = selected_pic not in false_pictures
        select_pictures = (
            "POKEMON_ZA_1_SELECT",
            "POKEMON_ZA_2_SELECT",
            "POKEMON_ZA_3_SELECT",
            "POKEMON_ZA_4_SELECT",
        )
        a_click_pictures = (
            "POKEMON_ZA_MORNING",
            "POKEMON_ZA_NIGHT",
        )
        wait_time = max(0.1, float(sleeptime))

        while True:
            self.checkIfAlive()

            # 指定選択画像とHELPだけは、停止画像より先にAで閉じる。
            # これによりHELPと終了画像が重なっても即終了しない。
            if (selected_picture_enabled
                    and self.image_check(selected_pic)):
                self.wait(1.0)
                for _ in range(max(0, int(selected_target))):
                    self.etc_sendCommand("Lbutton_down")
                    self.wait(0.5)
                self.pressRep(
                    Button.A, repeat=1, duration=0.15,
                    wait=0.0, interval=0.1)
                self.wait(wait_time)
                continue
            if self.image_check("POKEMON_ZA_HELP_MARKER"):
                self.pressRep(
                    Button.A, repeat=1, duration=0.15,
                    wait=0.0, interval=0.1)
                self.wait(wait_time)
                continue

            for picture in endpictures:
                if self.image_check(picture):
                    return "endpicture", picture
            if self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"):
                return "black_comment", "POKEMON_ZA_TEXT_BLACK_COMMENT"
            active_pictures = ["POKEMON_ZA_BATTLE_ACTIVE_LEVEL"]
            if guri_select_defeat_state:
                # GURI_116実録画では戦闘中もFIELDが一致した一方、
                # ESCAPEは0.99で成立していた。FIELDより先に戦闘継続へ
                # 戻し、117／118へ誤って進めない。
                active_pictures.extend((
                    "POKEMON_ZA_BATTLE_BALL_CHECK",
                    "POKEMON_ZA_ESCAPE",
                ))
            active_picture = next((
                picture for picture in active_pictures
                if self.image_check(picture)
            ), None)
            if active_picture is not None:
                return "active_level", active_picture
            if self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"):
                return "field", "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"

            # 選択肢と朝／夜の切替画像はA。それ以外（COMPLETE・
            # 各Comment・Xメニュー・CHAT・COIN・未検知を含む）は、
            # すべて安全側のBを送る。
            matched_select = next((
                picture for picture in select_pictures
                if self.image_check(picture)), None)
            if matched_select is not None:
                button = Button.A
            elif any(self.image_check(
                    picture) for picture in a_click_pictures):
                button = Button.A
            else:
                button = Button.B
            self.pressRep(
                button, repeat=1, duration=0.15,
                wait=0.0, interval=0.1)
            self.wait(wait_time)
            if guri_select_defeat_state and matched_select is not None:
                select_return = self._ZA_story_guri_select_defeat_observe(
                    guri_select_defeat_state, matched_select)
                if select_return is not None:
                    # 116だけは内部whileへ戻さず外側Stepへ制御を返し、
                    # SELECTを各Step周回で1回ずつ累計する。
                    return "guri_select_defeat", select_return

    def ZA_story_Template_battle_after_renda_route(
            self, bkprg_ret, prg_ret, battle_flow_key=None,
            selected_pic="POKEMON_ZA_FALSE_RETURN", selected_target=0,
            mode=0, sleeptime=0.5,
            black_comment_is_defeat=False,
            endpicture="", endpicture2="", endpicture3="",
            guri_select_defeat_state=""):
        """画面別の停止理由で遷移する、B基準の戦闘後連打処理。"""
        del mode  # 呼び出し互換用。
        if not battle_flow_key:
            battle_flow_key = bkprg_ret
        false_pictures = {
            None, "", "RETURN_FALSE", "RETURN FALSE",
            "POKEMON_ZA_FALSE_RETURN",
        }
        endpictures = tuple(
            picture for picture in (endpicture, endpicture2, endpicture3)
            if picture not in false_pictures)
        state = self._ZA_story_battle_flow_state(battle_flow_key)
        if not state["result_seen"]:
            state["result_seen"] = True
            self._ZA_story_battle_flow_mark(
                battle_flow_key, "RESULT_SEEN", "entered_after_renda_route")

        while True:
            stop_reason, stop_picture = self._ZA_story_battle_after_safe_renda(
                selected_pic=selected_pic,
                selected_target=selected_target,
                endpictures=endpictures,
                sleeptime=sleeptime,
                guri_select_defeat_state=guri_select_defeat_state)
            print(
                "[BATTLE_RENDA] {}: stop={} picture={}".format(
                    battle_flow_key, stop_reason, stop_picture))

            if stop_reason == "endpicture":
                self._ZA_story_battle_flow_reset(
                    battle_flow_key, "endpicture_renda")
                if guri_select_defeat_state:
                    self._ZA_story_guri_select_defeat_reset(
                        "battle_after_endpicture")
                return prg_ret
            if stop_reason == "field":
                # FIELDは1回の検知で連打を終了し、その場で次Stepへ進む。
                self._ZA_story_battle_flow_reset(
                    battle_flow_key, "field_renda")
                if guri_select_defeat_state:
                    self._ZA_story_guri_select_defeat_reset(
                        "battle_after_field")
                return prg_ret
            if stop_reason == "guri_select_defeat":
                return stop_picture
            if stop_reason == "active_level":
                # 左下Lv.の再表示はバトル復帰。afterを抜けて戻り先へ返す。
                state["active_seen"] = True
                state["result_seen"] = False
                state["field_result_count"] = 0
                state["field_result_since"] = None
                self._ZA_story_battle_flow_mark(
                    battle_flow_key, "ACTIVE_SEEN",
                    "active_level_returned_after_renda")
                return bkprg_ret
            if stop_reason == "black_comment":
                black_comment_cleared = False
                for _ in range(10):
                    self.checkIfAlive()
                    self.pressRep(
                        Button.B, repeat=1, duration=0.15,
                        wait=0.0, interval=0.1)
                    self.wait(max(0.1, float(sleeptime)))
                    if not self.image_check(
                            "POKEMON_ZA_TEXT_BLACK_COMMENT"):
                        black_comment_cleared = True
                        break

                if not black_comment_cleared:
                    # Bを10回送っても残る黒Commentは、敗戦画面ではなく
                    # アイテム使用時の黒Commentとして扱う。Aで閉じるが
                    # RETRY_ENTRYへは変更せず、同じafter処理を継続する。
                    self.pressRep(
                        Button.A, repeat=1, duration=0.15,
                        wait=0.0, interval=0.1)
                    self.wait(max(0.1, float(sleeptime)))
                    if guri_select_defeat_state:
                        # GURI_116は内部whileを抜け、外側の連続90秒監視へ
                        # 定期的に制御を戻す。B/A入力自体は従来どおり行う。
                        return guri_select_defeat_state
                    continue

                if black_comment_is_defeat:
                    # Bで閉じられた黒Commentだけを敗戦として扱う。
                    state["active_seen"] = False
                    state["result_seen"] = False
                    state["field_result_count"] = 0
                    state["field_result_since"] = None
                    self._ZA_story_battle_flow_mark(
                        battle_flow_key, "RETRY_ENTRY",
                        "black_comment_defeat_after_renda")
                    return bkprg_ret

                if guri_select_defeat_state:
                    # Bで消えた場合も一度外側へ戻し、次周期で黒Comment
                    # 不在を確認して90秒候補を確実にリセットする。
                    return guri_select_defeat_state

                # 敗北判定に使わない黒CommentはBで閉じた後、同じafter
                # 連打へ戻る。
                
    
    def ZA_story_Template_Comment_Out(self,substitute=0,green_check=1,black_check=1,endpicture7="RETURN_FALSE",sub9_button="A",sub9_picture="RETURN_FALSE",selected_pic="RETURN FALSE",selected_target=0,mode=0,sleeptime=0.5):
        selected_out_check=0

        if mode == 0:
            endpicture4="POKEMON_ZA_FILED_HARD_CHECK_0"
        else:
            endpicture4="POKEMON_ZA_FILED_HARD_CHECK_1"
        nofiled_check=0
        #コメントチェックができるまでループ
        for i in range(30):
            if self.image_check("POKEMON_ZA_IN_ICON"):#TODO
                return True
            if (not (self.image_check("POKEMON_ZA_FILED_HARD_CHECK_0"))):
                nofiled_check=1
            if self.image_check("POKEMON_ZA_EYE_CHECK_HIGH_POKE"):
                return True#ポケモンに見つかった場合は即座にTrue扱いで抜ける
            elif self.image_check("POKEMON_ZA_MISSION_COMPLETE"):
                break
            elif (self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT") or self.image_check("POKEMON_ZA_COMMENT_MARKER") or ((green_check==1) and (self.image_check("POKEMON_ZA_TEXT_GREEN_COMMENT"))) or ((black_check==1) and (self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")))):
                break
            elif self.image_check("POKEMON_ZA_COIN_ICON"):
                break
            elif self.image_check("POKEMON_ZA_BATTLE_BALL_CHECK") or self.image_check("POKEMON_ZA_ESCAPE"):
                return True
            elif self.image_check(selected_pic):
                break
            elif sub9_button == "A" and self.image_check(sub9_picture):
                # sub9は従来renda開始後にしか処理されず、FIELD上の操作を
                # 起点として会話を始めるStepではrendaまで到達できなかった。
                # 指定画像が見えている間だけAを送り、実際にFIELDを離れた後は
                # 従来のコメント検知・終了判定へ引き継ぐ。
                print(
                    "[COMMENT_OUT] initial action: A picture={}".format(
                        sub9_picture))
                self.pressRep(
                    Button.A, repeat=1, duration=0.04,
                    wait=0.0, interval=0.1)
                self.wait(max(0.1, float(sleeptime)))
                continue
            elif (nofiled_check==1 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")):
                return True
            elif (nofiled_check==1 and self.image_check("POKEMON_ZA_FILED_HARD_CHECK_0")):
                if (nofiled_check==1 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")):
                    return True
                break
            elif (nofiled_check==0 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")):
                return False 

            #elif (nofiled_check==1 and((not (self.image_check("BATTLE_BALL_CHECK") or self.image_check("ESCAPE")))and (self.image_check("Filed_Hard_Check_0")))):
            #    if filed_check_count > 5:
            #        break
            #    filed_check_count+=1
            #elif i == 9:
            #    return False
            self.wait(0.5)

        #コメントチェック待ちをおこなっても検知ができなかった場合は、False判定とする。
        #if (not (self.image_check("COIN_ICON") or self.image_check("TEXT_WHITE_COMMENT") or ((green_check==1) and (self.image_check("TEXT_GREEN_COMMENT"))) or ((black_check==1) and (self.image_check("TEXT_BLACK_COMMENT"))))):
        #    return False

        while True:
            self.checkIfAlive()
            selected_out_check=0
            if self.ZA_renda_button(rendabutton="B",
                                 endpicture="POKEMON_ZA_BATTLE_BALL_CHECK",
                                 endpicture2="POKEMON_ZA_ESCAPE",
                                 endpicture3=selected_pic,
                                 endpicture4=endpicture4,
                                 endpicture5="POKEMON_ZA_EYE_CHECK_HIGH_POKE",
                                 endpicture6="POKEMON_ZA_IN_ICON",#TODO
                                 endpicture7=endpicture7,
                                 not_endpicture="POKEMON_ZA_ZA_ROYALE",
                                 sub_button="A",sub_picture="POKEMON_ZA_TEXT_BLACK_COMMENT",
                                 sub2_button="A",sub2_picture="POKEMON_ZA_1_SELECT",
                                 sub3_button="A",sub3_picture="POKEMON_ZA_2_SELECT",
                                 sub4_button="A",sub4_picture="POKEMON_ZA_3_SELECT",
                                 sub5_button="A",sub5_picture="POKEMON_ZA_4_SELECT",
                                 sub6_button="A",sub6_picture="POKEMON_ZA_HELP_MARKER",
                                 sub7_button="A",sub7_picture="POKEMON_ZA_MORNING",
                                 sub8_button="A",sub8_picture="POKEMON_ZA_NIGHT",
                                 sub9_button=sub9_button,sub9_picture=sub9_picture,
                                 sleeptime=sleeptime):
                print(f"5rt2{nofiled_check}")
                selected_out_check=0
                filed_check_count=0
                for i in range(30):
                    self.wait(0.5)
                    # mode=1（屋内FIELD）ではZA_renda_button側が終了画像を
                    # 検知しても、従来はこの後の分岐がFILED_HARD_CHECK_0しか
                    # 確認しないため外側の連打へ戻り続けていた。連打終了後の
                    # 実画面でも指定されたFIELDを確認して会話完了とする。
                    if self.image_check(endpicture4):
                        print(
                            "[COMMENT_OUT] complete: {} detected".format(
                                endpicture4))
                        return True
                    elif self.image_check(selected_pic):
                        selected_out_check=1
                        self.wait(1.0)
                        for i in range(selected_target):
                            self.etc_sendCommand("Lbutton_down")
                            self.wait(0.5)
                        self.pressRep(Button.A, repeat=1, duration=0.15, wait=0.5, interval=0.1)
                        break
                    elif self.image_check("POKEMON_ZA_IN_ICON"):#TODO
                        break
                    elif self.image_check(endpicture7):
                        break
                    elif self.image_check("POKEMON_ZA_MISSION_COMPLETE"):
                        break
                    elif ((self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT") or self.image_check("POKEMON_ZA_COMMENT_MARKER") or ((green_check==1) and (self.image_check("POKEMON_ZA_TEXT_GREEN_COMMENT"))) or ((black_check==1) and (self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")))) ):
                        self.wait(0.5)
                        #選択肢チェックのタイミングがずれたようにフォローする
                        if self.image_check(selected_pic):
                            selected_out_check=1
                            self.wait(1.0)
                            for i in range(selected_target):
                                self.etc_sendCommand("Lbutton_down")
                                self.wait(0.5)
                            self.pressRep(Button.A, repeat=1, duration=0.15, wait=0.5, interval=0.1)
                            break
                        else:
                            self.pressRep(Button.B, repeat=1, duration=0.15, wait=0.5, interval=0.1)

                    elif self.image_check("POKEMON_ZA_BATTLE_BALL_CHECK") or self.image_check("POKEMON_ZA_ESCAPE"):
                        if ((self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT") or self.image_check("POKEMON_ZA_COMMENT_MARKER") or ((green_check==1) and (self.image_check("POKEMON_ZA_TEXT_GREEN_COMMENT"))) or ((black_check==1) and (self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")))) ):
                            self.wait(0.5)
                            #選択肢チェックのタイミングがずれたようにフォローする
                            if self.image_check(selected_pic):
                                selected_out_check=1
                                self.wait(1.0)
                                for i in range(selected_target):
                                    self.etc_sendCommand("Lbutton_down")
                                    self.wait(0.5)
                                self.pressRep(Button.A, repeat=1, duration=0.15, wait=0.5, interval=0.1)
                                break
                            else:
                                self.pressRep(Button.B, repeat=1, duration=0.15, wait=0.5, interval=0.1)
                        else:
                            break
                    elif (not (self.image_check("POKEMON_ZA_FILED_HARD_CHECK_0"))):
                        nofiled_check=1
                    elif (nofiled_check==1 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")):
                        break
                    elif (nofiled_check==1 and self.image_check("POKEMON_ZA_FILED_HARD_CHECK_0")):
                        break


                        #if filed_check_count > 5:
                        #    break
                        #filed_check_count+=1

            #選択肢処理を行っている場合は再度ボタン連打を再開する。
            if selected_out_check==1:
                selected_out_check=0
                continue
            self.wait(0.5)
            if self.image_check(endpicture7):
                break
            elif self.image_check("POKEMON_ZA_IN_ICON"):#TODO
                break
            elif self.image_check("POKEMON_ZA_MISSION_COMPLETE"):
                break   
            elif (self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT") or self.image_check("POKEMON_ZA_COMMENT_MARKER") or ((green_check==1) and (self.image_check("POKEMON_ZA_TEXT_GREEN_COMMENT"))) or ((black_check==1) and (self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")))):
                # 下記処理は戦闘不能となっている場合に実施すると抜けられなくなるため、回復などが前提にある場合でなければ使用しないこと
                if substitute==1:
                    endpicture4="POKEMON_ZA_WANINOKO_ICON"
                    endpicture5="POKEMON_ZA_ODAIRU_ICON"
                    endpicture6="POKEMON_ZA_ABSOL_ICON"
            elif self.image_check("POKEMON_ZA_BATTLE_BALL_CHECK") or self.image_check("POKEMON_ZA_ESCAPE"):
                break
            elif self.image_check("POKEMON_ZA_ZA_ROYALE"):
                self.pressRep(Button.B, repeat=1, duration=0.15, wait=0.5, interval=0.1)
            elif (nofiled_check==1 and self.image_check("POKEMON_ZA_FILED_HARD_CHECK_0")):
                if (nofiled_check==1 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")):
                    break  
            elif (nofiled_check==1 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")):
                break
            elif (nofiled_check==0 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")):
                return False 
        return True
       
    def ZA_story_Template_Field_HardGaurd(self,mode=0):
        if ( ((mode==0 and (self.image_check("POKEMON_ZA_FIELD_W") or self.image_check("POKEMON_ZA_FIELD_BACK_W"))) or mode==1)
            and (self.image_check("POKEMON_ZA_MERIP_ICON_GET5") or self.image_check("POKEMON_ZA_BATTLE") or self.image_check("POKEMON_ZA_WANINOKO_ICON") or self.image_check("POKEMON_ZA_ODAIRU_ICON") or self.image_check("POKEMON_ZA_ABSOL_ICON") or self.image_check("POKEMON_ZA_DEAD"))):
            return True
        else:
            return False
        
    def ZA_no_battle_filed_check_HardGaurd(self,mode=0):
    #チェックタイミングによってバトル中が非バトル中扱いとなる可能性があるため、sleeptimeなしで連続でチェックを行ってから判断させる。
    
        if self.ZA_story_Template_Field_HardGaurd(mode):
            if ((not (self.image_check("POKEMON_ZA_BATTLE_BALL_CHECK") or self.image_check("POKEMON_ZA_ESCAPE")))and (self.ZA_story_Template_Field_HardGaurd(mode))):
                for i in range(3):
                    if self.image_check("POKEMON_ZA_EYE_CHECK_HIGH_POKE"):
                        return True#ポケモンに見つかった場合は即座にTrue扱いで抜ける
                    elif (((self.image_check("POKEMON_ZA_BATTLE_BALL_CHECK") or self.image_check("POKEMON_ZA_ESCAPE")))and (self.ZA_story_Template_Field_HardGaurd(mode))):
                        return False #バトル中扱いとする
                    elif (not (self.ZA_story_Template_Field_HardGaurd(mode))):
                        return False #フィールドではないと判定
                return True #時間内にバトル中判定がない場合は非バトル中とする。
            
            elif ((self.image_check("POKEMON_ZA_BATTLE_BALL_CHECK") or self.image_check("POKEMON_ZA_ESCAPE")))and (self.ZA_story_Template_Field_HardGaurd(mode)):
                return False #バトル中扱いとする
        return False #フィールドチェックできない

