    def ZA_story_status_text(self):
        story_state_by_main = {
            "MAIN_1_Z_LANK": self._1_story_current_state,
            "MAIN_2_Y_V_LANK": self._2_story_current_state,
            "MAIN_3_F_LANK": self._3_story_current_state,
            "MAIN_4_E_LANK": self._4_story_current_state,
            "MAIN_5_D_LANK": self._5_story_current_state,
            "MAIN_6_C_LANK": self._6_story_current_state,
            "MAIN_7_B_LANK": self._7_story_current_state,
            "MAIN_8_STORY_LAST": self._8_story_current_state,
        }
        current_story_state = story_state_by_main.get(self.main_current_state)
        main_status = f' STATE_MAIN_FUNCTION   :: {self.main_current_state}'
        if current_story_state:
            main_status += f' :: {current_story_state}'
        game_reset_state = getattr(
            self, "ZA_gamereset_current_state", "IDLE")
        game_reset_status = ""
        if game_reset_state != "IDLE":
            game_reset_status = (
                f'\r\n GAME_RESET_FUNCTION   :: {game_reset_state}')
        mega_mode5_status = ""
        if getattr(self, "_za_mega_last_battle_mode", False):
            hp_ratio=float(getattr(
                self, "_za_mega_testmode1_hp_fill_ratio", 0.0))
            mega_mode5_status = (
                f'\r\n MEGA_MODE5_TESTMODE1  :: '
                f'{int(bool(getattr(self, "_za_mega_testmode1_enabled", False)))}'
                f'\r\n MEGA_MODE5_RESUME_HP  :: '
                f'{getattr(self, "_za_mega_testmode1_resume_hp", "LEGACY")}'
                f' :: {getattr(self, "_za_mega_testmode1_hp_color", "NONE")}'
                f' :: ratio={hp_ratio:.3f}'
                f'\r\n MEGA_MODE5_TEST_PHASE :: '
                f'{getattr(self, "_za_mega_testmode1_phase", "DISABLED")}'
                f'\r\n MEGA_MODE5_START_FLAG :: '
                f'{getattr(self, "_za_mega_mode5_start_flag", 0)}'
                f' :: {getattr(self, "_za_mega_mode5_phase", "WAIT_RESUME")}'
                f'\r\n MEGA_MODE5_DETECTION  :: '
                f'{getattr(self, "_za_mega_mode5_last_detection", "NONE")}'
                f'\r\n MEGA_MODE5_ACTION     :: '
                f'{getattr(self, "_za_mega_mode5_last_action", "NONE")}')

        return (
            f'----------------------------'
            f'\r\n{main_status}'
            f'\r\n'
            f'\r\n ### STATE_2_VAR ###'
            f'\r\n'
            f'\r\n SKILL_CHANGE_FUNCTION :: {self.common_skill_change_current_state}'
            f'\r\n BOX_CHANGE_FUNCTION   :: {self.common_box_change_current_state}'
            f'\r\n ITEM_GIVE_FUNCTION    :: {self.common_item_give_current_state}'
            f'\r\n EVOLUTION_FUNCTION    :: {self.common_evolution_current_state}'
            f'{game_reset_status}'
            f'{mega_mode5_status}'
            f'\r\n----------------------------'
        )

    def ZA_story_main(self):
        # Reloadや開始位置指定で前回実行時の戦闘完了状態を引き継がない。
        self._za_first_battle_started = False
        self._za_first_battle_confirm_count = 0
        self._za_story_battle_flows = {}
        self._za_story_active_lank_battle_zone = None
        self._za_story_active_infi_step = None
        self._za_story_pre_step_gate_state = None
        self._za_story_pre_step_gate_started_at = None
        self._za_story_pre_step_gate_completed = False
        self._za_story_pre_step_gate_last_dispatch_state = None
        self._za_story_event_entry_pending_recovery = None
        self._za_story_mapping_goto_watch = None
        self._za_story_mapping_goto_recovery = None
        while True:
            
            self.main_current_state = self.STATE_MAIN_FUNCTION[self.main_current_state]()
            self.wait(0.1)
            self.out_str = self.ZA_story_status_text()
            

            self.print_tb("d"); self.print_t(f'{self.out_str}')
            self.checkIfAlive()
        return True   
    
    ######################################################
    # MAIN_STATE_INIT (引継ぎ実行用)
    ######################################################
    def main_state_init(self):
        # MAIN_STATE_INIT is a UI-visible dispatcher, not a runnable resume
        # destination.  Treat an explicitly selected MAIN_STATE_INIT exactly
        # like the normal empty default; returning it would loop here forever.
        if self.main_current_state_init in ("", "MAIN_STATE_INIT"):
            return "MAIN_0_START"
        elif  self.main_current_state_init=="MAIN_1_Z_LANK":
            self._1_story_current_state=self._1_story_current_state_init
            return "MAIN_1_Z_LANK"
        elif  self.main_current_state_init=="MAIN_2_Y_V_LANK":
            self._2_story_current_state=self._2_story_current_state_init
            self._2_story_yubiwa_checked = (
                self._2_story_yubiwa_checked_for_start(
                    self._2_story_current_state_init))
            return "MAIN_2_Y_V_LANK"
        elif  self.main_current_state_init=="MAIN_3_F_LANK":
            self._3_story_current_state=self._3_story_current_state_init
            return "MAIN_3_F_LANK"
        elif  self.main_current_state_init=="MAIN_4_E_LANK":
            self._4_story_current_state=self._4_story_current_state_init
            return "MAIN_4_E_LANK"
        elif  self.main_current_state_init=="MAIN_5_D_LANK":
            self._5_story_current_state=self._5_story_current_state_init
            return "MAIN_5_D_LANK"
        elif  self.main_current_state_init=="MAIN_6_C_LANK":
            self._6_story_current_state=self._6_story_current_state_init
            return "MAIN_6_C_LANK"
        elif  self.main_current_state_init=="MAIN_7_B_LANK":
            self._7_story_current_state=self._7_story_current_state_init
            return "MAIN_7_B_LANK"
        elif  self.main_current_state_init=="MAIN_8_STORY_LAST":
            self._8_story_current_state=self._8_story_current_state_init
            return "MAIN_8_STORY_LAST"
        else:
            return self.main_current_state_init
        
