    def _2_story_yubiwa_checked_for_start(self, state):
        """途中Step開始時にYUBIWA確認済み状態を復元する。"""
        states = tuple(self.STATE_2_STORY_FUNCTION)
        try:
            return states.index(str(state)) > states.index("2_STORY_TOWER_55")
        except ValueError:
            return False

