    def ZA_battle_goto_battle_zone2(self):
        self.wait(self.SLEEPLIST[7][2])
        if self.image_check("POKEMON_ZA_MAP2"):        
            if self.image_check("POKEMON_ZA_MOVESPOT_TAB"):         
                if self.image_check("POKEMON_ZA_TAB_FILTER"):
                    for i in range(0,(self.battlecount + 1)):
                        self.etc_sendCommand("Lbutton_up")
                        
                    for i in range(0,self.battle_zone_loop_num + 1):
                        self.targetzone=self.ZA_zone_check()
                        previous_targetzone = getattr(
                            self, "infi_previous_targetzone", None)
                        same_zone = (
                            previous_targetzone is not None
                            and self.targetzone == previous_targetzone)
                        unavailable = (
                            (self.testcode==0 and
                             (not self.ZONELIST[self.targetzone][2]))
                            or (self.testcode==2 and
                                (not (self.targetzone == self.testtarget))))
                        if same_zone or unavailable:
                            print(str(self.targetzone) + ": " + self.ZONELIST[self.targetzone][1])
                            self.battlecount=self.battlecount+1
                            self.etc_sendCommand("Lbutton_up")
                            if unavailable:
                                self.zonemisscount[self.targetzone-1]+=1
                            print("SKIP_SAME" if same_zone else "SKIP")
                            print("==================================")
                            self.wait(self.SLEEPLIST[1][2])
                            if self.battlecount > (self.battle_zone_loop_num - 1):
                                # The requested upper-bound behavior is to
                                # move to the next highlighted area once, then
                                # return through POKEMONCENTER.  Refresh the
                                # detected zone after moving the cursor so the
                                # post-teleport movement data is not stale.
                                self.targetzone=self.ZA_zone_check()
                                break
                        else:
                            print(str(self.targetzone) + ": " + self.ZONELIST[self.targetzone][1])
                            break
                    self.infi_previous_targetzone = self.targetzone
                    self.pressRep(Button.A, repeat=1, duration=0.15, wait=0.1, interval=0.1)

                    for i in range(1,10):
                        self.wait(self.SLEEPLIST[10][2])
                        if self.image_check("POKEMON_ZA_MOVE_COMMENT"): 
                            self.pressRep(Button.A, repeat=5, duration=0.15, wait=0.1, interval=0.1)
                            self.sleepcount=0

                            if self.battlecount> (self.battle_zone_loop_num - 1):
                                return "BATTLE_START"
                            else:
                                self.battle_step_return=0
                                return "BATTLE_MOVE"
                        elif self.image_check("POKEMON_ZA_MOVE_COMMENT_BATTLE"):
                            self.inactioncount+=1
                            self.pressRep(Button.B, repeat=10, duration=0.15, wait=0.1, interval=0.1)
                            self.battle_step_return=1
                            return "BATTLE_MOVE"
                        elif i == 1:
                            if self.image_check("POKEMON_ZA_MOVE_COMMENT"): 
                                self.pressRep(Button.A, repeat=5, duration=0.15, wait=0.1, interval=0.1)
                                self.sleepcount=0
                                if self.battlecount> (self.battle_zone_loop_num - 1):
                                    return "BATTLE_START"
                                else:
                                    self.battle_step_return=0
                                    return "BATTLE_MOVE"
                            self.pressRep(Button.A, repeat=1, duration=0.15, wait=0.2, interval=0.1)
                            
                    print("MOVE_COM_ELSE")
                    if self.battlecheck == 1:
                        self.inactioncount+=1
                        self.pressRep(Button.B, repeat=20, duration=0.15, wait=0.1, interval=0.1)
                        self.battle_step_return=1
                        return "BATTLE_MOVE"

                    self.pressRep(Button.A, repeat=5, duration=0.15, wait=0.1, interval=0.1)
                    self.sleepcount=0
                    if self.battlecount> (self.battle_zone_loop_num - 1):
                        return "BATTLE_START"
                    else:
                        self.battle_step_return=0
                        return "BATTLE_MOVE"
        return "BATTLE_GOTO_BATTLE_ZONE2"
    
    def ZA_battle_move(self):
        
        if self.battle_step_return == 0:
            self.battle_step=0
        else:
            self.battle_step=self.battle_step_return  
        
        count=0
        if self.battle_step_return == 0:
            if not (self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")): #FIELDから変更
                for i in range(20):
                    if (self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")): #FIELDから変更
                        return "BATTLE_MOVE"
                    self.wait(1.0)
                return "BATTLE_START"

            elif not (self.image_check("POKEMON_ZA_FIELD") or self.image_check("POKEMON_ZA_FIELD_BACK")):
                self.etc_sendCommand("Lbutton_left")
                if self.battle_current_state=="BATTLE_MOVE":
                    self.pressRep(Button.B, repeat=10, duration=0.15, wait=0.1, interval=0.1)
                if self.image_check("POKEMON_ZA_DEAD"):
                    return "BATTLE_START"
                elif not self.image_check("POKEMON_ZA_BATTLE"):
                    return "BATTLE_MOVE"
                #else:
                #    return "BATTLE_MOVE"
            elif self.image_check("POKEMON_ZA_DEAD"):
                return "BATTLE_START"
         
      #TEST
        battlecount_before = self.battlecount
        self._za_infi_area_end_reason = ""
        if self.battle_step_return == 0:
            result = self.ZA_battle_move_test()
        else:
            self.battle_step_return = 0
            result = self.ZA_battle_move_test(1)

        if result == "BATTLE_MAP_OPEN":
            if self._za_infi_area_end_reason == "reward":
                self.infi_area_failure_count = 0
            else:
                # Several recovery branches leave the movement loop with a
                # bare ``break``.  Count that area exactly once even when the
                # branch forgot to advance battlecount itself.
                if self.battlecount <= battlecount_before:
                    self.battlecount = battlecount_before + 1
                self.infi_area_failure_count = (
                    int(getattr(self, "infi_area_failure_count", 0)) + 1)
                failure_limit = max(
                    1, int(getattr(self, "infi_area_failure_limit", 3)))
                if (self.infi_area_failure_count >= failure_limit
                        or self.battlecount >
                           (self.battle_zone_loop_num - 1)):
                    return "BATTLE_START"
        return result
        
    def ZA_infi_attack_ready(self):
        # 通常閾値を優先し、取りこぼした場合だけ0.60のLOWを確認する。
        return (
            self.image_check("POKEMON_ZA_C+")
            or self.image_check("POKEMON_ZA_C+_LOW"))

    def ZA_infi_guarded_ladder_climb(self, stop_on_field=False):
        """Send ladder input in slices, yielding as soon as combat resumes."""
        moved = False
        for _ in range(20):
            if ((stop_on_field and self.image_check(
                    "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK"))
                    or self.image_check("POKEMON_ZA_ESCAPE")
                    or self.ZA_infi_attack_ready()
                    or self.image_check("POKEMON_ZA_SELECT")
                    or self.image_check("POKEMON_ZA_2_SELECT")
                    or self.image_check("POKEMON_ZA_3_SELECT")
                    or self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")
                    or self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT")):
                return moved, False
            self.press(
                Direction(Stick.LEFT, 90), duration=0.5, wait=0.0)
            moved = True
        return moved, True

    def ZA_infi_stalled_ladder_recovery(
            self, attack_ready=False, now=None, frame=None,
            allow_bench=False):
        """Climb out of a stalled ladder without overriding live combat."""
        state_suffix = "_bench" if allow_bench else ""
        reset_names = (
            "_za_infi_ladder_previous_frame" + state_suffix,
            "_za_infi_ladder_still_since" + state_suffix,
        )

        def reset_candidate():
            for name in reset_names:
                setattr(self, name, None)

        if (not allow_bench
                and (self.battle_current_state != "BATTLE_MOVE"
                     or self.battle_step not in (0, 1))):
            reset_candidate()
            return False
        if attack_ready or self.image_check("POKEMON_ZA_ESCAPE"):
            reset_candidate()
            return False
        if (self.image_check("POKEMON_ZA_SELECT")
                or self.image_check("POKEMON_ZA_2_SELECT")
                or self.image_check("POKEMON_ZA_3_SELECT")
                or self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT")
                or self.image_check("POKEMON_ZA_TEXT_WHITE_COMMENT")):
            reset_candidate()
            return False

        if frame is None:
            camera = getattr(self, "camera", None)
            if camera is None:
                reset_candidate()
                return False
            if hasattr(camera, "readFreshFrame"):
                frame = camera.readFreshFrame(timeout=0.75)
            else:
                frame = camera.readFrame() if hasattr(
                    camera, "readFrame") else None
        if frame is None or getattr(frame, "size", 0) == 0:
            reset_candidate()
            return False

        height, width = frame.shape[:2]
        region = frame[
            int(height * 0.12):max(int(height * 0.12) + 1,
                                   int(height * 0.82)),
            int(width * 0.15):max(int(width * 0.15) + 1,
                                  int(width * 0.85))]
        if region.size == 0:
            reset_candidate()
            return False
        fingerprint = cv2.resize(
            cv2.cvtColor(region, cv2.COLOR_BGR2GRAY), (32, 18))
        current_time = time.monotonic() if now is None else float(now)
        previous_name = "_za_infi_ladder_previous_frame" + state_suffix
        still_since_name = "_za_infi_ladder_still_since" + state_suffix
        previous = getattr(self, previous_name, None)
        setattr(self, previous_name, fingerprint)
        if previous is None:
            setattr(self, still_since_name, current_time)
            return False

        frame_difference = cv2.mean(
            cv2.absdiff(fingerprint, previous))[0]
        if frame_difference > 1.5:
            setattr(self, still_since_name, current_time)
            return False
        still_since = getattr(self, still_since_name, None)
        if still_since is None:
            setattr(self, still_since_name, current_time)
            return False
        if current_time - float(still_since) < 3.0:
            return False
        last_attempt_name = "_za_infi_ladder_last_attempt" + state_suffix
        last_attempt = float(getattr(
            self, last_attempt_name, -1000000.0))
        if current_time - last_attempt < 30.0:
            return False

        # C+ is checked here even when this story Step normally uses
        # no_Cplus=1.  A visible attack opportunity always takes priority over
        # ladder recovery.
        if self.ZA_infi_attack_ready():
            reset_candidate()
            return False

        setattr(self, last_attempt_name, current_time)
        reset_candidate()
        self.ZA_MOVE_SEE("END")
        self.ZA_ZL_ACTION("END")
        # A long uninterrupted hold can suppress combat for ten seconds.
        # Send 0.5-second slices and stop before the next slice as soon as the
        # normal battle UI or an attack opportunity returns.
        moved, _ = self.ZA_infi_guarded_ladder_climb(
            stop_on_field=allow_bench)
        if moved:
            recovery_context = "BENCH_CHECK_TIME" if allow_bench else "BATTLE_MOVE"
            print(
                f"[INFI_LADDER_RECOVERY] context={recovery_context} "
                "静止を検出したため上入力で復帰")
        return moved

    def ZA_infi_target_marker_direction(self):
        # Mega戦と同じく、左上マップを除外した全画面座標から
        # 画面下中央を起点とする左スティック方向を求める。
        targets = getattr(self, "IMAGE_DETECTION_TARGETS", {})
        marker_variants = [
            (target, targets[target][0])
            for target in (
                "POKEMON_ZA_TARGET_LEFT_LOW",
                "POKEMON_ZA_TARGET_RIGHT_LOW")
            if targets.get(target)
        ]
        if not marker_variants:
            return None
        camera = getattr(self, "camera", None)
        if camera is None:
            return None
        if hasattr(camera, "readFreshFrame"):
            frame = camera.readFreshFrame(timeout=0.75)
        else:
            frame = camera.readFrame() if hasattr(
                camera, "readFrame") else None
        if frame is None:
            return None

        detection_details = []
        for target, variant in marker_variants:
            template_path = str(variant.get("template_path", ""))
            normalized_path = template_path.replace("\\", "/")
            if (not os.path.isabs(template_path)
                    and normalized_path.startswith("Template/")):
                template_path = self.get_filespec(
                    normalized_path[len("Template/"):], mode="t")
            template = cv2.imread(template_path, cv2.IMREAD_COLOR)
            if template is None:
                continue
            source_match = frame
            template_match = template
            if variant.get("use_gray", False):
                source_match = cv2.cvtColor(
                    source_match, cv2.COLOR_BGR2GRAY)
                template_match = cv2.cvtColor(
                    template_match, cv2.COLOR_BGR2GRAY)
            if (source_match.shape[0] < template_match.shape[0]
                    or source_match.shape[1] < template_match.shape[1]):
                continue
            result = cv2.matchTemplate(
                source_match,
                template_match,
                cv2.TM_CCOEFF_NORMED)
            result = result.copy()
            result_height, result_width = result.shape[:2]
            template_height, template_width = template_match.shape[:2]
            exclusion_right = min(result_width, 210)
            exclusion_bottom = min(result_height, 210)
            if exclusion_right > 0 and exclusion_bottom > 0:
                result[0:exclusion_bottom, 0:exclusion_right] = -2.0
            _, score, _, location = cv2.minMaxLoc(result)
            detection_details.append({
                "name": target,
                "matched": float(score) >= float(
                    variant.get("threshold", 0.5)),
                "score": float(score),
                "position": location,
                "template_size": (
                    int(template_width), int(template_height)),
            })
        if not detection_details:
            return None
        detail = max(
            detection_details,
            key=lambda item: float(item.get("score", -1.0)))
        self.last_image_detection = detail
        if not detail.get("matched"):
            return None

        x, y = detail["position"]
        width, height = detail["template_size"]
        marker_x = float(x) + float(width) / 2.0
        marker_y = float(y) + float(height) / 2.0
        delta_x = marker_x - 640.0
        delta_y = 720.0 - marker_y
        if abs(delta_x) < 1.0 and abs(delta_y) < 1.0:
            angle = 90.0
        else:
            angle = (
                math.degrees(math.atan2(delta_y, delta_x))
                + 360.0) % 360.0
        return Direction(Stick.LEFT, angle, 0.5)

    def ZA_infi_relock_toward_marker(self):
        marker_direction = self.ZA_infi_target_marker_direction()
        self.ZA_ZL_ACTION("END")
        if marker_direction:
            self.press(marker_direction, duration=0.2, wait=0.0)
            self.pressRep(
                Button.L, repeat=1, duration=0.04,
                wait=0.0, interval=0.1)
        self.ZA_ZL_ACTION("")
        return bool(marker_direction)

    def ZA_battle_move_test(self,fast=0):
        self.quasar_battle_lockon=0
        count=0
        movestep=0
        Seecheckflg=0
        Seecheckflg2=0
        self.notargetcount=0
        self.see_r=self.SEE_DEFAULT
        
        self.ZA_MOVE_SEE("END")
        self.ZA_ZL_ACTION("END")
        
        if self.battle_current_state=="BATTLE_MOVE" and self.inactioncount>3 and self.image_check("POKEMON_ZA_ESCAPE"):
            self.ZA_MOVE_SEE("END")
            self.ZA_ZL_ACTION("END")

            self.battleescapecount+=1
            self.pressRep(Button.MINUS, repeat=1, duration=0.15, wait=0.3, interval=0.1)
            for loop in range(100):
                if self.image_check("POKEMON_ZA_ESCAPE_SELECT"):
                    self.press(Button.A, wait=0.0)
                elif self.image_check("POKEMON_ZA_ESCAPE_COMMENT1"):
                    self.press(Button.A, wait=0.0)
                elif self.image_check("POKEMON_ZA_ESCAPE_COMMENT2"):
                    for i in range(1,10):
                        self.press(Button.B, wait=0.0)
                        return "BATTLE_START"
                #補足できなかった場合の代用
                elif self.image_check("POKEMON_ZA_FIELD") or self.image_check("POKEMON_ZA_FIELD_BACK") or self.image_check("POKEMON_ZA_DEAD"):
                    for i in range(1,10):
                        self.press(Button.B, wait=0.0)
                        return "BATTLE_START"

        if self.ZONELIST[self.targetzone][4] == -1 or self.quasar_current_state=="QUASAR_BATTLE_LOOP":
            lockonflg = 1
        else:
            lockonflg = 0
        
        start = time.perf_counter()  # 計測開始
        end = start
        endbk = end
        lastescape = time.perf_counter() 
        
